//! Tests for the attach-time collector body.
//!
//! Extracted verbatim from `attach_log.rs`, where they were 23,291 lines.
//! Original indentation kept so the bodies stay byte-identical.

        use super::*;
        use std::fs;

        #[test]
        fn collector_host_image_filter_is_ascii_case_insensitive_and_exact() {
            assert!(utf16_ascii_eq_ignore_case(
                &"hoi4.exe".encode_utf16().collect::<Vec<_>>(),
                b"hoi4.exe"
            ));
            assert!(utf16_ascii_eq_ignore_case(
                &"HOI4.EXE".encode_utf16().collect::<Vec<_>>(),
                b"hoi4.exe"
            ));
            assert!(!utf16_ascii_eq_ignore_case(
                &"collector_record.exe".encode_utf16().collect::<Vec<_>>(),
                b"hoi4.exe"
            ));
            assert!(!utf16_ascii_eq_ignore_case(
                &"hoi4.exe.bak".encode_utf16().collect::<Vec<_>>(),
                b"hoi4.exe"
            ));
        }

        #[test]
        fn d71_capture_diagnostics_preserve_failure_branches() {
            let absent = d71_capture_attempt(Some(71), 9, 0, false, |_| {
                panic!("an absent A28 owner must not be drained")
            });
            assert_eq!(absent.branch, D71CaptureBranch::InstallAbsent);

            let no_observation =
                d71_capture_attempt(Some(71), 9, 0, true, |_| Ok(None));
            assert_eq!(
                no_observation.branch,
                D71CaptureBranch::NoObservation
            );

            let drain_error = d71_capture_attempt(Some(71), 9, 0, true, |_| {
                Err("A28 hook owner poisoned".into())
            });
            assert_eq!(drain_error.branch, D71CaptureBranch::DrainError);
            assert_eq!(
                drain_error.detail_fingerprint,
                fnv1a_64(b"A28 hook owner poisoned")
            );

            let decode_mismatch = d71_capture_attempt(Some(71), 9, 0, true, |_| {
                Ok(Some(b"not-a-DCT1-carrier".to_vec()))
            });
            assert_eq!(
                decode_mismatch.branch,
                D71CaptureBranch::DecodeMismatch
            );
            assert_eq!(
                decode_mismatch.decode_mismatch,
                D71DecodeMismatch::CarrierDecode
            );

            for attempt in [absent, no_observation, drain_error, decode_mismatch] {
                assert_ne!(attempt.branch, D71CaptureBranch::Captured);
                assert_ne!(
                    attempt.domain_status
                        & (COMPACT_STATUS_SOURCE_UNAVAILABLE | COMPACT_STATUS_PARTIAL_DATA),
                    0
                );
                let unavailable =
                    dynamic_collection_trace_live_lane::decode_payload(&attempt.payload)
                        .expect("typed D71 unavailable carrier");
                assert_eq!(unavailable.status_flags, attempt.domain_status);
                assert!(unavailable.collections.is_empty());
            }
        }

        #[test]
        fn d71_decode_diagnostics_separate_hour_and_status_mismatch() {
            let wrong_hour =
                dynamic_collection_trace_live_lane::encode_source_unavailable(
                    70,
                    9,
                    COMPACT_STATUS_SOURCE_UNAVAILABLE,
                )
                .unwrap();
            let attempt = d71_capture_attempt(
                Some(71),
                9,
                COMPACT_STATUS_SOURCE_UNAVAILABLE,
                true,
                |_| Ok(Some(wrong_hour)),
            );
            assert_eq!(attempt.branch, D71CaptureBranch::DecodeMismatch);
            assert_eq!(
                attempt.decode_mismatch,
                D71DecodeMismatch::FrameHour
            );
            assert_eq!(attempt.detail_fingerprint, 70);

            let wrong_status =
                dynamic_collection_trace_live_lane::encode_source_unavailable(
                    71,
                    9,
                    COMPACT_STATUS_SOURCE_UNAVAILABLE,
                )
                .unwrap();
            let attempt = d71_capture_attempt(
                Some(71),
                9,
                COMPACT_STATUS_PARTIAL_DATA,
                true,
                |_| Ok(Some(wrong_status)),
            );
            assert_eq!(attempt.branch, D71CaptureBranch::DecodeMismatch);
            assert_eq!(
                attempt.decode_mismatch,
                D71DecodeMismatch::StatusFlags
            );
            assert_eq!(
                attempt.detail_fingerprint,
                u64::from(COMPACT_STATUS_SOURCE_UNAVAILABLE)
            );
        }

