        #[test]
        fn d79_collector_emission_preserves_exact_runtime_root_names_without_pointers() {
            use hud_role_observer_live_lane::{
                decode_activation_payload, HudSurface, HudSurfaceActivation, RawHudControllerRoot,
            };
            let fixed = [
                (
                    HudSurface::TheatreSelector,
                    hud_role_observer_live_lane::THEATRE_SETUP_RVA,
                    "mod_theatre",
                ),
                (
                    HudSurface::Topbar,
                    hud_role_observer_live_lane::TOPBAR_SETUP_RVA,
                    "mod_topbar",
                ),
                (
                    HudSurface::Mapmodes,
                    hud_role_observer_live_lane::MAPMODE_SETUP_RVA,
                    "mod_mapmodes",
                ),
                (
                    HudSurface::Minimap,
                    hud_role_observer_live_lane::MINIMAP_SETUP_RVA,
                    "mod_minimap",
                ),
            ]
            .into_iter()
            .enumerate()
            .map(
                |(index, (surface, setup_rva, runtime_root_name))| RawHudControllerRoot {
                    sequence: index as u64 + 1,
                    setup_rva,
                    surface,
                    controller_ptr: 0x1111_0000 + index,
                    runtime_root_ptr: 0x2222_0000 + index,
                    runtime_root_name: runtime_root_name.into(),
                },
            )
            .collect::<Vec<_>>();
            let payload = encode_hud_activation_from_roots_and_alerts(
                77,
                0,
                &fixed,
                Some((HudSurface::DesignerTank, "mod_tank_designer".into(), 15)),
                &hud_role_observer_live_lane::TopbarAlertCounts {
                    country_tag_db_id: 7,
                    intel_available: 0,
                    intel_prepared_or_completed: 0,
                    market_non_delivering: 0,
                    market_ongoing: 0,
                    active_alerts: Vec::new(),
                },
            )
            .unwrap();
            let decoded = decode_activation_payload(&payload).unwrap();
            assert_eq!(decoded.frame_hour, 77);
            assert_eq!(decoded.observation_sequence, 15);
            assert_eq!(
                decoded.active_surfaces,
                vec![
                    HudSurfaceActivation {
                        surface: HudSurface::Topbar,
                        runtime_root_name: "mod_topbar".into()
                    },
                    HudSurfaceActivation {
                        surface: HudSurface::Minimap,
                        runtime_root_name: "mod_minimap".into()
                    },
                    HudSurfaceActivation {
                        surface: HudSurface::Mapmodes,
                        runtime_root_name: "mod_mapmodes".into()
                    },
                    HudSurfaceActivation {
                        surface: HudSurface::TheatreSelector,
                        runtime_root_name: "mod_theatre".into()
                    },
                    HudSurfaceActivation {
                        surface: HudSurface::DesignerTank,
                        runtime_root_name: "mod_tank_designer".into()
                    },
                ]
            );
            for root in &fixed {
                assert!(!payload
                    .windows(std::mem::size_of::<usize>())
                    .any(|bytes| bytes == root.runtime_root_ptr.to_le_bytes()));
            }
        }

