        // Regression: the full-heap `scan_qword_hits` sweeps read live game
        // memory in big chunks and MUST NOT fault the process when a region is
        // decommitted mid-read (observed crash: VCRUNTIME140 memcpy AV inside
        // the naval supremacy region scan on attach 2). `read_bytes_scan` routes
        // the bulk copy through `ReadProcessMemory`, which fails clean on
        // unmapped/decommitted source memory instead of raising an in-thread AV.
        #[test]
        fn read_bytes_scan_reads_valid_and_fails_clean_on_unmapped() {
            let mut scratch: Vec<u8> = Vec::new();

            // Valid buffer: exact contents copied.
            let src: Vec<u8> = (0u8..64).collect();
            let got = read_bytes_scan(src.as_ptr() as usize, src.len(), &mut scratch)
                .expect("valid buffer must read");
            assert_eq!(got, &src[..]);

            // The reused scratch must not leak stale bytes: a second, shorter
            // read exposes only its own bytes, never the tail of the prior one.
            let src2: Vec<u8> = (100u8..116).collect();
            let got2 = read_bytes_scan(src2.as_ptr() as usize, src2.len(), &mut scratch)
                .expect("second valid buffer must read");
            assert_eq!(got2, &src2[..]);
            assert_eq!(got2.len(), src2.len());

            // Zero length is rejected (nothing to scan).
            assert!(read_bytes_scan(src.as_ptr() as usize, 0, &mut scratch).is_none());

            // A guaranteed-unmapped low address must fail clean (return None),
            // NOT fault. If `read_bytes_scan` ever regressed to a raw
            // `ptr::copy_nonoverlapping`, this line would crash the test
            // process instead of returning None.
            assert!(read_bytes_scan(0x1000, 0x2000, &mut scratch).is_none());

            // Under-reserve regression guard: start with a scratch that has
            // SOME spare capacity but LESS than the requested read. The helper
            // must grow to a full capacity >= len before RPM writes `len` bytes;
            // an under-reserve (the `reserve(len - capacity)` bug) would let RPM
            // overrun the allocation and corrupt the heap. We request 4096 bytes
            // into a buffer preseeded with a smaller capacity, then verify the
            // full contents came back intact.
            let mut small: Vec<u8> = Vec::with_capacity(64);
            let big: Vec<u8> = (0..4096u32).map(|i| (i & 0xff) as u8).collect();
            let gotbig = read_bytes_scan(big.as_ptr() as usize, big.len(), &mut small)
                .expect("grown scratch must read the full range");
            assert_eq!(gotbig.len(), big.len());
            assert_eq!(gotbig, &big[..]);
            assert!(small.capacity() >= big.len(), "capacity must reach len");
        }

        #[test]
        fn object_snapshot_reads_fields_locally_and_fails_closed() {
            // Little-endian source object laid out at known offsets.
            let mut src = [0u8; 32];
            src[0] = 0xAB; // u8 @0
            src[2..4].copy_from_slice(&0x1234u16.to_le_bytes()); // u16 @2
            src[4..8].copy_from_slice(&0xDEADBEEFu32.to_le_bytes()); // u32 @4
            src[8..12].copy_from_slice(&(-5i32).to_le_bytes()); // i32 @8
            src[12..16].copy_from_slice(&1.5f32.to_le_bytes()); // f32 @12
            src[16..24].copy_from_slice(&0x1122334455667788u64.to_le_bytes()); // u64/ptr @16

            let snap =
                ObjectSnapshot::<32>::read(src.as_ptr() as usize).expect("valid object reads");
            assert_eq!(snap.u8(0), Some(0xAB));
            assert_eq!(snap.u16(2), Some(0x1234));
            assert_eq!(snap.u32(4), Some(0xDEAD_BEEF));
            assert_eq!(snap.i32(8), Some(-5));
            assert_eq!(snap.f32(12), Some(1.5));
            assert_eq!(snap.u64(16), Some(0x1122_3344_5566_7788));
            assert_eq!(snap.ptr(16), Some(0x1122_3344_5566_7788usize));

            // Field bounds: a read that runs past the captured N returns None,
            // never reads out of the buffer.
            assert_eq!(snap.u64(28), None, "u64@28 needs bytes 28..36 > N=32");
            assert_eq!(snap.u32(30), None, "u32@30 needs bytes 30..34 > N=32");
            assert_eq!(snap.u8(31), Some(0), "last byte in range is fine");
            assert_eq!(snap.u8(32), None, "one past the end");

            // Fail-closed: a guaranteed-unmapped address returns None (no fault).
            assert!(ObjectSnapshot::<32>::read(0x1000).is_none());
        }

        // ObjectSnapshot must fail CLOSED exactly like a scalar read of its far
        // end: if the object's byte range crosses a committed->uncommitted
        // boundary, `read` returns None rather than faulting or returning a
        // partial. Same manufactured boundary as the read_bytes_scan test.
        #[test]
        fn object_snapshot_fails_closed_across_commit_boundary() {
            const PAGE: usize = 0x1000;
            #[link(name = "kernel32")]
            extern "system" {
                fn VirtualAlloc(
                    address: *mut c_void,
                    size: usize,
                    alloc_type: Dword,
                    protect: Dword,
                ) -> *mut c_void;
                fn VirtualFree(address: *mut c_void, size: usize, free_type: Dword) -> Bool;
            }
            const MEM_RESERVE: Dword = 0x2000;
            const MEM_COMMIT: Dword = 0x1000;
            const MEM_RELEASE: Dword = 0x8000;
            const PAGE_READWRITE: Dword = 0x04;
            unsafe {
                let base = VirtualAlloc(ptr::null_mut(), 2 * PAGE, MEM_RESERVE, PAGE_READWRITE);
                assert!(!base.is_null(), "reserve failed");
                let committed = VirtualAlloc(base, PAGE, MEM_COMMIT, PAGE_READWRITE);
                assert_eq!(committed, base, "commit first page failed");
                // Reset the per-thread region cache epoch so the just-changed
                // layout is re-queried rather than served from a stale span.
                let _ = rc_take_and_reset();
                // An object wholly inside the committed page reads fine.
                let inside = base as usize + (PAGE - 64);
                assert!(
                    ObjectSnapshot::<64>::read(inside).is_some(),
                    "object inside committed page must read"
                );
                // An object straddling the committed->reserved boundary must fail
                // closed (its tail is in the uncommitted second page).
                let straddle = base as usize + (PAGE - 16);
                assert!(
                    ObjectSnapshot::<64>::read(straddle).is_none(),
                    "object crossing into the uncommitted page must fail closed"
                );
                VirtualFree(base, 0, MEM_RELEASE);
            }
        }

        // The load-bearing crash-safety property: a bulk scan read that SPANS a
        // committed -> uncommitted region boundary must degrade to a clean short
        // read of the committed prefix, NEVER a process-killing access violation.
        // This is the exact shape of the shipped crash (a chunk `want` reaching
        // into pages the game decommitted). We manufacture the boundary here:
        // reserve two adjacent pages, commit only the first, write a marker into
        // it, then ask `read_bytes_scan` for BOTH pages at once. RPM copies the
        // committed page and stops clean at the boundary; a raw `memcpy` would
        // fault crossing into the reserved page and take the test process down.
        #[test]
        fn read_bytes_scan_short_reads_across_commit_boundary() {
            const PAGE: usize = 0x1000;
            #[link(name = "kernel32")]
            extern "system" {
                fn VirtualAlloc(
                    address: *mut c_void,
                    size: usize,
                    alloc_type: Dword,
                    protect: Dword,
                ) -> *mut c_void;
                fn VirtualFree(address: *mut c_void, size: usize, free_type: Dword) -> Bool;
            }
            const MEM_RESERVE: Dword = 0x2000;
            const MEM_DECOMMIT: Dword = 0x4000;
            const MEM_RELEASE: Dword = 0x8000;
            const PAGE_READWRITE: Dword = 0x04;

            unsafe {
                // Reserve a 2-page run so the two pages are ADJACENT (one
                // reservation), reproducing the abutting committed->reserved
                // layout the game's allocator produces.
                let base = VirtualAlloc(ptr::null_mut(), 2 * PAGE, MEM_RESERVE, PAGE_READWRITE);
                assert!(!base.is_null(), "reserve failed");
                // Commit ONLY page 0.
                let committed = VirtualAlloc(base, PAGE, MEM_COMMIT, PAGE_READWRITE);
                assert_eq!(committed, base, "commit page0 failed");

                // Marker bytes across the whole committed page.
                let bytes = base as *mut u8;
                for i in 0..PAGE {
                    *bytes.add(i) = (i & 0xff) as u8;
                }

                // Committed-extent correctness: `readable_region` (VirtualQuery)
                // must report ONLY the committed page, never a merged
                // committed+reserved size. If it over-reported, callers would
                // hand `read_bytes_scan` a `want` reaching into the reserved
                // page — the exact miscompute the clamp is supposed to prevent.
                let (rstart, rsize) =
                    readable_region(base as usize).expect("committed page is readable");
                assert_eq!(
                    rstart, base as usize,
                    "region start must be the committed base"
                );
                assert_eq!(
                    rsize, PAGE,
                    "readable_region must return committed-only extent"
                );
                assert!(
                    readable_region(base as usize + PAGE).is_none(),
                    "the reserved page must not read as committed/readable"
                );

                let mut scratch: Vec<u8> = Vec::new();
                // Ask for BOTH pages: [committed page | reserved page]. A raw
                // memcpy would AV on page 1 and kill the process. The LOAD-
                // BEARING invariant is that `read_bytes_scan` returns WITHOUT
                // faulting. RPM's partial-read behaviour across a straddling
                // range is NOT contractually guaranteed: Windows may copy the
                // committed prefix and report it, or fail the whole call with
                // bytes_read == 0. Both are safe here — the scan callers advance
                // past a `None` chunk and re-query. So we assert only: no crash,
                // and IF a prefix is returned it is a valid prefix of the
                // committed page (never bytes from the reserved page).
                match read_bytes_scan(base as usize, 2 * PAGE, &mut scratch) {
                    Some(got) => {
                        assert!(
                            got.len() <= PAGE,
                            "must never expose bytes past the committed page ({} > {})",
                            got.len(),
                            PAGE
                        );
                        assert_eq!(got[0], 0, "prefix must be the committed page's marker");
                        assert_eq!(got[got.len() - 1], ((got.len() - 1) & 0xff) as u8);
                    }
                    None => { /* whole straddling read declined — also safe */ }
                }

                // A read fully WITHIN the committed page must always succeed with
                // the exact marker bytes (the common, non-straddling case).
                let inside = read_bytes_scan(base as usize, PAGE, &mut scratch)
                    .expect("a read wholly inside the committed page must succeed");
                assert_eq!(inside.len(), PAGE);
                assert_eq!(inside[PAGE - 1], ((PAGE - 1) & 0xff) as u8);

                // Now DECOMMIT page 0 too and read again: nothing committed at
                // the start -> clean None, still no fault.
                let _ = VirtualFree(base, PAGE, MEM_DECOMMIT);
                assert!(
                    read_bytes_scan(base as usize, 2 * PAGE, &mut scratch).is_none(),
                    "fully decommitted start must fail clean"
                );

                let _ = VirtualFree(base, 0, MEM_RELEASE);
            }
        }

        // ============================================================
        // P4c-1: crash-safe RPM scalar/bytes primitive tests
        // ============================================================

        // Test-local VirtualAlloc/Free bindings + constants (mirrors the
        // boundary test above; kept separate so each test is self-contained).
        #[link(name = "kernel32")]
        extern "system" {
            fn VirtualAlloc(
                address: *mut c_void,
                size: usize,
                alloc_type: Dword,
                protect: Dword,
            ) -> *mut c_void;
            fn VirtualFree(address: *mut c_void, size: usize, free_type: Dword) -> Bool;
            fn VirtualProtect(
                address: *mut c_void,
                size: usize,
                new_protect: Dword,
                old_protect: *mut Dword,
            ) -> Bool;
        }
        const T_MEM_RESERVE: Dword = 0x2000;
        const T_MEM_DECOMMIT: Dword = 0x4000;
        const T_MEM_RELEASE: Dword = 0x8000;
        const T_PAGE_READWRITE: Dword = 0x04;

        // The new fixed-width readers must return byte-identical values to a
        // direct little-endian decode of the same in-process bytes (i.e. to
        // the OLD read_bytes+from_le_bytes path) for a VALID range.
        #[test]
        fn rpm_scalars_match_direct_decode_for_valid_range() {
            page_cache_new_frame();
            // Aligned buffer; fill with a known pattern.
            let src: Vec<u8> = (0u8..=255).collect();
            let base = src.as_ptr() as usize;

            // u64/u32/u16/u8/i32/i64 at a few in-page offsets.
            for off in [0usize, 1, 3, 8, 16, 100, 200] {
                let a = base + off;
                assert_eq!(
                    read_u64(a),
                    Some(u64::from_le_bytes(src[off..off + 8].try_into().unwrap())),
                    "u64 @+{off}"
                );
                assert_eq!(
                    read_u32(a),
                    Some(u32::from_le_bytes(src[off..off + 4].try_into().unwrap())),
                    "u32 @+{off}"
                );
                assert_eq!(
                    read_u16(a),
                    Some(u16::from_le_bytes(src[off..off + 2].try_into().unwrap())),
                    "u16 @+{off}"
                );
                assert_eq!(read_u8(a), Some(src[off]), "u8 @+{off}");
                assert_eq!(
                    read_i32(a),
                    Some(i32::from_le_bytes(src[off..off + 4].try_into().unwrap())),
                    "i32 @+{off}"
                );
                assert_eq!(
                    read_i64(a),
                    Some(i64::from_le_bytes(src[off..off + 8].try_into().unwrap())),
                    "i64 @+{off}"
                );
            }

            // read_bytes must return the exact slice.
            let got = read_bytes(base + 10, 32).expect("valid read_bytes");
            assert_eq!(got, &src[10..42]);
        }

        // Fail-closed: an unmapped address returns None from EVERY reader and
        // does NOT fault the process (a raw memcpy would crash here).
        #[test]
        fn rpm_scalars_fail_closed_on_unmapped() {
            page_cache_new_frame();
            let bad = 0x1000usize; // guaranteed-unmapped low address
            assert_eq!(read_u64(bad), None);
            assert_eq!(read_u32(bad), None);
            assert_eq!(read_u16(bad), None);
            assert_eq!(read_u8(bad), None);
            assert_eq!(read_i32(bad), None);
            assert_eq!(read_i64(bad), None);
            assert_eq!(read_bytes(bad, 8), None);
            assert_eq!(read_bytes(bad, 0), None, "zero-length is None");
        }

        // A scalar that straddles a committed->reserved page boundary must fail
        // closed (all-or-nothing), NEVER crash, NEVER expose committed-prefix
        // bytes as a partial value. This exercises the straddle branch that
        // keeps the old is_readable_range gate.
        #[test]
        fn rpm_scalar_straddling_commit_boundary_fails_closed() {
            const PAGE: usize = 0x1000;
            page_cache_new_frame();
            unsafe {
                let base = VirtualAlloc(ptr::null_mut(), 2 * PAGE, T_MEM_RESERVE, T_PAGE_READWRITE);
                assert!(!base.is_null());
                let committed = VirtualAlloc(base, PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                assert_eq!(committed, base);
                let bytes = base as *mut u8;
                for i in 0..PAGE {
                    *bytes.add(i) = (i & 0xff) as u8;
                }
                // A u64 whose last byte is in the reserved page: last 4 bytes at
                // page0 end, first bytes... place so it straddles: start at
                // PAGE-4 -> reads [PAGE-4 .. PAGE+4), crossing into reserved.
                let straddle_addr = base as usize + PAGE - 4;
                assert_eq!(
                    read_u64(straddle_addr),
                    None,
                    "straddling read into reserved page must fail closed"
                );
                // A u64 wholly inside the committed page succeeds with exact bytes.
                let inside_addr = base as usize + PAGE - 8;
                let expect = {
                    let mut a = [0u8; 8];
                    for (i, b) in a.iter_mut().enumerate() {
                        *b = ((PAGE - 8 + i) & 0xff) as u8;
                    }
                    u64::from_le_bytes(a)
                };
                assert_eq!(read_u64(inside_addr), Some(expect), "in-page read exact");

                let _ = VirtualFree(base, 0, T_MEM_RELEASE);
            }
        }

        // The page cache must not let a scalar be read once its page has been
        // decommitted: even on a stale (cached-good) page, the RPM copy
        // re-validates and fails closed. We commit a page, warm the cache with a
        // successful read, decommit it WITHOUT bumping the epoch, and confirm the
        // next read returns None (RPM fails) rather than a crash or stale bytes.
        // A PAGE_GUARD page must fail closed (None) via the VirtualQuery gate,
        // and (belt-and-suspenders) never be RPM'd on a cache miss because the
        // gate rejects it before any RPM. This documents the guard-safety
        // property Codex flagged.
        #[test]
        fn rpm_scalar_rejects_guard_page_via_gate() {
            const PAGE: usize = 0x1000;
            const T_PAGE_GUARD: Dword = 0x100;
            page_cache_new_frame();
            unsafe {
                let base = VirtualAlloc(ptr::null_mut(), PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                assert!(!base.is_null());
                // Arm the guard bit on the page.
                let mut old: Dword = 0;
                let ok = VirtualProtect(
                    base,
                    PAGE,
                    T_PAGE_READWRITE | T_PAGE_GUARD,
                    &mut old as *mut Dword,
                );
                assert_ne!(ok, 0, "VirtualProtect guard-arm failed");
                let addr = base as usize + 16;
                // is_page_committed_readable_nonguard must reject the guard page,
                // so read_u64 returns None WITHOUT the RPM ever touching it.
                assert!(
                    !is_page_committed_readable_nonguard(base as usize),
                    "guard page must not be confirmed-good"
                );
                assert_eq!(read_u64(addr), None, "guard page read must fail closed");
                let _ = VirtualFree(base, 0, T_MEM_RELEASE);
            }
        }

        // Plan-v2 P2: the region-interval gate must make the EXACT same
        // accept/reject decision as `is_readable_range` for every (addr,len)
        // (identical MEM_COMMIT && !(NOACCESS|GUARD), whole-range-in-one-region
        // predicate), so routing read_scalar/read_bytes/read_into through it is
        // byte-identical to the pre-P2 gate. Covers valid, boundary-straddling,
        // past-the-end, and unmapped ranges, and re-runs to exercise the region-
        // cache HIT path (which must agree too).
        #[test]
        fn range_confirmed_good_matches_is_readable_range() {
            let buf: Vec<u8> = (0..(2usize << 20)).map(|i| i as u8).collect();
            let base = buf.as_ptr() as usize;
            let len = buf.len();
            page_cache_new_frame();
            let cases = [
                (base, 8usize),
                (base + 7, 8),
                (base + 4093, 8), // straddles a 4 KiB page boundary in-buffer
                (base + len - 8, 8),
                (base + len - 4, 8), // runs off the buffer end
                (base + len, 8),
                (0x1000usize, 8),   // unmapped low address
                (base, len),        // whole buffer in one read
                (base, len + 4096), // past the end
            ];
            // Miss path (fresh epoch), then hit path (same epoch) -> both agree.
            for _ in 0..2 {
                for (a, n) in cases {
                    assert_eq!(
                        range_confirmed_good(a, n),
                        is_readable_range(a, n),
                        "gate mismatch at addr={a:#x} len={n}"
                    );
                }
            }
        }

        // P2b B1: the interval cache's pure span helpers must keep the list
        // sorted + disjoint under region-boundary churn (overlapping inserts
        // evict the stale spans) and must never act as if adjacent regions were
        // merged — a range straddling two cached spans stays a miss, exactly
        // like the old cross-region rejection.
        #[test]
        fn region_spans_insert_keeps_sorted_disjoint_under_overlap() {
            let mut spans: Vec<(usize, usize)> = Vec::new();
            region_spans_insert(&mut spans, 0x3000, 0x5000);
            region_spans_insert(&mut spans, 0x1000, 0x2000);
            region_spans_insert(&mut spans, 0x8000, 0x9000);
            assert_eq!(
                spans,
                vec![(0x1000, 0x2000), (0x3000, 0x5000), (0x8000, 0x9000)]
            );
            // Partial overlap evicts the stale span it collides with.
            region_spans_insert(&mut spans, 0x2800, 0x3800);
            assert_eq!(
                spans,
                vec![(0x1000, 0x2000), (0x2800, 0x3800), (0x8000, 0x9000)]
            );
            // A spanning insert evicts every span it covers.
            region_spans_insert(&mut spans, 0x0800, 0x9800);
            assert_eq!(spans, vec![(0x0800, 0x9800)]);
            // Exact duplicate stays a single span.
            region_spans_insert(&mut spans, 0x0800, 0x9800);
            assert_eq!(spans, vec![(0x0800, 0x9800)]);
            // Touching spans are kept SEPARATE — never merged.
            region_spans_insert(&mut spans, 0x9800, 0xa000);
            assert_eq!(spans, vec![(0x0800, 0x9800), (0x9800, 0xa000)]);
        }

        #[test]
        fn region_spans_lookup_rejects_cross_span_ranges() {
            let spans = vec![
                (0x1000usize, 0x2000usize),
                (0x2000, 0x3000),
                (0x8000, 0x9000),
            ];
            assert_eq!(
                region_spans_lookup(&spans, 0x1000, 0x1008),
                Some((0x1000, 0x2000))
            );
            assert_eq!(
                region_spans_lookup(&spans, 0x1ff8, 0x2000),
                Some((0x1000, 0x2000))
            );
            // Adjacent cached spans: a straddling range is NOT a hit.
            assert_eq!(region_spans_lookup(&spans, 0x1ffc, 0x2004), None);
            assert_eq!(region_spans_lookup(&spans, 0x3000, 0x3008), None); // gap
            assert_eq!(region_spans_lookup(&spans, 0x0800, 0x0808), None); // before first
            assert_eq!(
                region_spans_lookup(&spans, 0x8fff, 0x9000),
                Some((0x8000, 0x9000))
            );
            assert_eq!(region_spans_lookup(&spans, 0x8fff, 0x9001), None); // past end
            assert_eq!(region_spans_lookup(&[], 0x1000, 0x1008), None);
        }

        #[test]
        fn region_spans_insert_cap_resets() {
            let mut spans: Vec<(usize, usize)> = Vec::new();
            for i in 0..REGION_CACHE_CAP {
                let s = 0x10_0000 + i * 0x2000;
                region_spans_insert(&mut spans, s, s + 0x1000);
            }
            assert_eq!(spans.len(), REGION_CACHE_CAP);
            region_spans_insert(&mut spans, 0x1000, 0x2000);
            assert_eq!(spans, vec![(0x1000, 0x2000)]);
        }

        // P2b B1 property test: after ANY sequence of inserts the span list stays
        // sorted + pairwise-disjoint, and `region_spans_lookup` agrees exactly
        // with a brute-force linear "which single cached span wholly contains
        // this range" scan. This is the invariant the byte-identical gate rests
        // on (a merged/overlapping list could accept a cross-region range the VQ
        // gate rejects). Deterministic LCG so it is reproducible without
        // Math.random.
        #[test]
        fn region_spans_insert_lookup_property() {
            fn brute(spans: &[(usize, usize)], a: usize, end: usize) -> Option<(usize, usize)> {
                spans.iter().copied().find(|&(s, e)| s <= a && end <= e)
            }
            fn disjoint_sorted(spans: &[(usize, usize)]) -> bool {
                spans.windows(2).all(|w| w[0].1 <= w[1].0) && spans.iter().all(|&(s, e)| s < e)
            }
            let mut rng: u64 = 0x1234_5678_9abc_def0;
            let mut next = || {
                rng = rng
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                rng
            };
            // Small address universe so overlaps/adjacency happen often.
            let mut spans: Vec<(usize, usize)> = Vec::new();
            for _ in 0..4000 {
                let start = ((next() >> 33) as usize % 64) * 0x1000;
                let width = (1 + (next() >> 33) as usize % 6) * 0x1000;
                let end = start + width;
                region_spans_insert(&mut spans, start, end);
                assert!(
                    disjoint_sorted(&spans),
                    "invariant broken after insert ({start:#x},{end:#x}): {spans:?}"
                );
                assert!(spans.len() <= REGION_CACHE_CAP);
                // Probe several ranges; lookup must equal brute force exactly.
                for _ in 0..8 {
                    let pa = ((next() >> 33) as usize % 72) * 0x1000
                        + ((next() >> 40) as usize % 0x1000);
                    let pw = 1 + (next() >> 33) as usize % 0x2000;
                    let pend = pa + pw;
                    assert_eq!(
                        region_spans_lookup(&spans, pa, pend),
                        brute(&spans, pa, pend),
                        "lookup!=brute for ({pa:#x},{pend:#x}) over {spans:?}"
                    );
                }
            }
        }

        // P2b B1: the interval cache must make the SAME accept/reject decision as
        // is_readable_range across MULTIPLE distinct VQ regions (the single-region
        // equivalence test can't exercise cross-region rejection through the cache).
        // Allocates three separate committed regions with unmapped gaps and checks
        // every reader gate agrees, on both the miss (fresh) and hit (cached) pass.
        #[test]
        fn range_confirmed_good_matches_across_multiple_regions() {
            const PAGE: usize = 0x1000;
            page_cache_new_frame();
            unsafe {
                // Three independent committed regions (the allocator leaves gaps).
                let r0 = VirtualAlloc(ptr::null_mut(), 4 * PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                let r1 = VirtualAlloc(ptr::null_mut(), 4 * PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                let r2 = VirtualAlloc(ptr::null_mut(), 4 * PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                assert!(!r0.is_null() && !r1.is_null() && !r2.is_null());
                let b0 = r0 as usize;
                let b1 = r1 as usize;
                let b2 = r2 as usize;
                let cases = [
                    (b0, 8usize),
                    (b0 + 4 * PAGE - 8, 8),
                    (b0 + 4 * PAGE - 4, 8), // runs off region 0
                    (b1, 8),
                    (b1 + PAGE, 4096),
                    (b2, 8),
                    (b2 + 4 * PAGE, 8), // past region 2 end
                    (0x1000usize, 8),   // unmapped low address
                ];
                // Interleave regions so a single-slot cache would thrash; run the
                // whole set twice (miss then hit) — every decision must match.
                for _ in 0..2 {
                    for (a, n) in cases {
                        assert_eq!(
                            range_confirmed_good(a, n),
                            is_readable_range(a, n),
                            "multi-region gate mismatch at addr={a:#x} len={n}"
                        );
                    }
                }
                let _ = VirtualFree(r0, 0, T_MEM_RELEASE);
                let _ = VirtualFree(r1, 0, T_MEM_RELEASE);
                let _ = VirtualFree(r2, 0, T_MEM_RELEASE);
            }
        }

        // Plan-v2 P2: the SEH primitive is the one change that can crash the
        // game, so prove it fails CLOSED (returns None, no access violation
        // escapes) on the two live hazards -- a page that becomes a guard page
        // and a page that is decommitted -- even on a stale-good region-cache HIT
        // (VirtualQuery skipped, so ONLY the SEH filter stands between us and the
        // fault). Forces the SEH primitive explicitly. Both primitives fail
        // closed, so temporarily flipping the global cannot perturb other tests.
        #[test]
        fn seh_primitive_fails_closed_on_guard_and_decommit() {
            const PAGE: usize = 0x1000;
            const T_PAGE_GUARD: Dword = 0x100;
            const T_MEM_DECOMMIT: Dword = 0x4000;
            CURRENT_FRAME_PRIMITIVE.store(READ_PRIM_SEH, Ordering::Relaxed);
            // --- guard-page hazard on a stale-good cache hit ---
            page_cache_new_frame();
            unsafe {
                let base = VirtualAlloc(ptr::null_mut(), PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                assert!(!base.is_null());
                let bytes = base as *mut u8;
                for i in 0..PAGE {
                    *bytes.add(i) = (i & 0xff) as u8;
                }
                let addr = base as usize + 16;
                assert!(read_u64(addr).is_some(), "SEH warm read must succeed");
                // Arm guard WITHOUT a new epoch -> region-cache HIT skips VQ.
                let mut old: Dword = 0;
                let ok = VirtualProtect(
                    base,
                    PAGE,
                    T_PAGE_READWRITE | T_PAGE_GUARD,
                    &mut old as *mut Dword,
                );
                assert_ne!(ok, 0, "VirtualProtect guard-arm failed");
                assert_eq!(
                    read_u64(addr),
                    None,
                    "SEH must fail closed on a guard page (stale-good cache hit)"
                );
                let _ = VirtualFree(base, 0, T_MEM_RELEASE);
            }
            // --- decommit hazard on a stale-good cache hit (the live case) ---
            page_cache_new_frame();
            unsafe {
                let base = VirtualAlloc(ptr::null_mut(), PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                assert!(!base.is_null());
                let bytes = base as *mut u8;
                for i in 0..PAGE {
                    *bytes.add(i) = (i & 0xff) as u8;
                }
                let addr = base as usize + 16;
                assert!(read_u64(addr).is_some(), "SEH warm read must succeed");
                // Decommit (keep reservation) WITHOUT a new epoch -> cache HIT,
                // page now uncommitted; the SEH copy must fault closed, not crash.
                let ok = VirtualFree(base, PAGE, T_MEM_DECOMMIT);
                assert_ne!(ok, 0, "VirtualFree decommit failed");
                assert_eq!(
                    read_u64(addr),
                    None,
                    "SEH must fail closed on a decommitted page (stale-good cache hit)"
                );
                let _ = VirtualFree(base, 0, T_MEM_RELEASE);
            }
            // Restore the default primitive for any subsequent test.
            CURRENT_FRAME_PRIMITIVE.store(READ_PRIM_SEH, Ordering::Relaxed);
        }

        // STALE-GOOD guard test (the exact off-frame residual): warm the page
        // cache with a successful read, then arm PAGE_GUARD WITHOUT bumping the
        // frame epoch, so the cache still reports the page "good" (a cache HIT
        // that skips VirtualQuery). The RPM copy must STILL fail closed (None) --
        // it does not return stale bytes and does not crash. (It may trip+clear
        // the one-shot guard bit; that is the documented sub-frame side effect,
        // not a wire-byte or crash issue.) This proves a stale-good cache entry
        // on a page that becomes a guard page still emits None, identical to the
        // old VirtualQuery-reject path.
        // ============================================================
        // T1 (perf_rearch_20260706): alloc-free scalar-override equivalence.
        //
        // Each lane's collector `Memory` impl now overrides its defaulted scalar
        // reads with the alloc-free `read_scalar::<N>` primitives instead of the
        // trait default (`self.read_bytes(addr, N)` + `from_le_bytes`). These
        // tests pin BYTE-IDENTICAL behavior: a per-trait shim implements ONLY the
        // required method(s) so the trait DEFAULTS run over the SAME underlying
        // collector `read_bytes`, and every case is asserted equal (value AND, for
        // Result-typed traits, the error payload) against the real overridden
        // impl. Covers: every scalar width on readable memory (incl. high-bit-set
        // values for sign/endianness), an unreadable/decommitted address, and a
        // scalar straddling a committed->decommitted page boundary.
        // ============================================================

        // --- d53 shim: only `module_base` + `read_bytes`; scalar DEFAULTS run. ---
        struct Domain53DefaultShim;
        impl diplomacy53::extractor::Domain53Memory for Domain53DefaultShim {
            fn module_base(&self) -> u64 {
                0
            }
            fn read_bytes(
                &self,
                address: u64,
                len: usize,
            ) -> Result<Vec<u8>, diplomacy53::extractor::ExtractError> {
                // Identical to the real impl's read_bytes, so the trait-default
                // scalars see the exact same accept/reject + error mapping.
                let addr = usize::try_from(address).map_err(|_| {
                    diplomacy53::extractor::ExtractError::MemoryRead { address, len }
                })?;
                read_bytes(addr, len)
                    .ok_or(diplomacy53::extractor::ExtractError::MemoryRead { address, len })
            }
        }

        #[test]
        fn t1_d53_scalar_overrides_match_defaults() {
            use diplomacy53::extractor::Domain53Memory;
            page_cache_new_frame();
            // High-bit-set pattern so sign/endianness slips are caught.
            let src: Vec<u8> = (0u8..=255).rev().collect();
            let base = src.as_ptr() as usize;
            let real = Domain53InProcessMemory;
            let shim = Domain53DefaultShim;
            for off in [0usize, 1, 3, 7, 16, 128, 200] {
                let a = (base + off) as u64;
                assert_eq!(real.read_u8(a), shim.read_u8(a), "d53 read_u8 @+{off}");
                assert_eq!(real.read_u32(a), shim.read_u32(a), "d53 read_u32 @+{off}");
                assert_eq!(real.read_i32(a), shim.read_i32(a), "d53 read_i32 @+{off}");
                assert_eq!(real.read_u64(a), shim.read_u64(a), "d53 read_u64 @+{off}");
                assert_eq!(real.read_i64(a), shim.read_i64(a), "d53 read_i64 @+{off}");
                // Also pin the concrete decoded value against a direct decode.
                assert_eq!(
                    real.read_i32(a),
                    Ok(i32::from_le_bytes(src[off..off + 4].try_into().unwrap())),
                    "d53 read_i32 value @+{off}"
                );
            }
            // Unreadable low address: both must produce the SAME Err payload.
            let bad = 0x1000u64;
            assert_eq!(real.read_u8(bad), shim.read_u8(bad));
            assert_eq!(real.read_u32(bad), shim.read_u32(bad));
            assert_eq!(real.read_i32(bad), shim.read_i32(bad));
            assert_eq!(real.read_u64(bad), shim.read_u64(bad));
            assert_eq!(real.read_i64(bad), shim.read_i64(bad));
            assert_eq!(
                real.read_u32(bad),
                Err(diplomacy53::extractor::ExtractError::MemoryRead {
                    address: bad,
                    len: 4,
                }),
                "d53 unreadable err payload"
            );
        }

        #[test]
        fn t1_d53_scalar_overrides_match_defaults_across_commit_boundary() {
            use diplomacy53::extractor::Domain53Memory;
            const PAGE: usize = 0x1000;
            let real = Domain53InProcessMemory;
            let shim = Domain53DefaultShim;
            page_cache_new_frame();
            unsafe {
                let base = VirtualAlloc(ptr::null_mut(), 2 * PAGE, T_MEM_RESERVE, T_PAGE_READWRITE);
                assert!(!base.is_null());
                let committed = VirtualAlloc(base, PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                assert_eq!(committed, base);
                let bytes = base as *mut u8;
                for i in 0..PAGE {
                    *bytes.add(i) = (i & 0xff) as u8;
                }
                page_cache_new_frame();
                // Scalar straddling committed->reserved: both fail closed the same.
                let straddle = (base as usize + PAGE - 4) as u64;
                assert_eq!(
                    real.read_u64(straddle),
                    shim.read_u64(straddle),
                    "d53 u64 straddle"
                );
                assert_eq!(
                    real.read_u32(straddle + 2),
                    shim.read_u32(straddle + 2),
                    "d53 u32 straddle"
                );
                // A wholly-committed scalar just inside the boundary agrees + reads.
                let inside = (base as usize + PAGE - 8) as u64;
                assert_eq!(
                    real.read_u64(inside),
                    shim.read_u64(inside),
                    "d53 u64 inside"
                );
                assert!(real.read_u64(inside).is_ok());
                // Now DECOMMIT the first page (keep the reservation) and re-check:
                // an address that was readable becomes unreadable identically.
                let ok = VirtualFree(base, PAGE, T_MEM_DECOMMIT);
                assert_ne!(ok, 0, "decommit failed");
                page_cache_new_frame();
                assert_eq!(
                    real.read_u64(inside),
                    shim.read_u64(inside),
                    "d53 u64 after decommit"
                );
                assert!(real.read_u64(inside).is_err());
                let _ = VirtualFree(base, 0, T_MEM_RELEASE);
            }
        }

        // --- d48 shim: mirrors the PRE-T1 impl (allocating read_u8 + read_bytes);
        //     scalar DEFAULTS (read_u16/u32/i32/u64) run over it. ---
        struct Domain48DefaultShim;
        impl domain48::LaneMemory for Domain48DefaultShim {
            fn read_u8(&self, addr: usize) -> Option<u8> {
                read_bytes(addr, 1).and_then(|bytes| bytes.first().copied())
            }
            fn read_bytes(&self, addr: usize, len: usize) -> Option<Vec<u8>> {
                if len == 0 {
                    Some(Vec::new())
                } else {
                    read_bytes(addr, len)
                }
            }
        }

