        #[test]
        fn t1_d48_object_window_matches_scalar_reads() {
            // Phase 2 bulk-window: a committed window equals the byte-for-byte
            // scalar reads of each field it serves, and an unreadable window
            // fails closed (None) exactly like a scalar read there.
            use domain48::LaneMemory;
            page_cache_new_frame();
            let src: Vec<u8> = (0u8..=255).rev().collect();
            let base = src.as_ptr() as usize;
            let real = Domain48InProcessMemory;

            let window = real
                .read_object_window::<{ domain48::CBUILDING_WINDOW_LEN }>(base)
                .expect("committed window is readable");
            assert_eq!(&window[..], &src[..domain48::CBUILDING_WINDOW_LEN]);
            // Every field the building walk serves from the window equals its
            // individual guarded scalar read.
            assert_eq!(
                u64::from_le_bytes(window[0..8].try_into().unwrap()),
                real.read_u64(base).unwrap(),
                "vtable"
            );
            assert_eq!(
                u32::from_le_bytes(
                    window[domain48::CBUILDING_OFF_TYPE..domain48::CBUILDING_OFF_TYPE + 4]
                        .try_into()
                        .unwrap()
                ),
                real.read_u32(base + domain48::CBUILDING_OFF_TYPE).unwrap(),
                "type"
            );
            assert_eq!(
                u16::from_le_bytes(
                    window[domain48::CBUILDING_OFF_LEVEL..domain48::CBUILDING_OFF_LEVEL + 2]
                        .try_into()
                        .unwrap()
                ),
                real.read_u16(base + domain48::CBUILDING_OFF_LEVEL).unwrap(),
                "level"
            );
            // The wider line window likewise round-trips.
            let line = real
                .read_object_window::<{ domain48::LINE_WINDOW_LEN }>(base)
                .expect("committed line window is readable");
            assert_eq!(&line[..], &src[..domain48::LINE_WINDOW_LEN]);

            let bad = 0x1000usize;
            assert_eq!(
                real.read_object_window::<{ domain48::CBUILDING_WINDOW_LEN }>(bad),
                None,
                "unreadable window is None"
            );
            assert_eq!(real.read_u64(bad), None, "and so is the scalar read");
        }

        #[test]
        fn t1_d48_object_window_fails_closed_across_commit_boundary() {
            // A window that straddles committed->reserved fails closed (None),
            // identical to a scalar read of a field at the far end; a wholly
            // committed window succeeds and matches scalars; after decommit the
            // same window becomes None.
            use domain48::LaneMemory;
            const PAGE: usize = 0x1000;
            const N: usize = domain48::CBUILDING_WINDOW_LEN;
            let real = Domain48InProcessMemory;
            page_cache_new_frame();
            unsafe {
                let base = VirtualAlloc(ptr::null_mut(), 2 * PAGE, T_MEM_RESERVE, T_PAGE_READWRITE);
                assert!(!base.is_null());
                let committed = VirtualAlloc(base, PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                assert_eq!(committed, base);
                let bytes = base as *mut u8;
                for i in 0..PAGE {
                    *bytes.add(i) = (i & 0xff) as u8;
                }
                page_cache_new_frame();

                // Straddling window: last byte falls in the reserved page.
                let straddle = base as usize + PAGE - (N - 4);
                assert_eq!(
                    real.read_object_window::<N>(straddle),
                    None,
                    "straddle window fails closed"
                );
                // A scalar read of the far end of that same window also fails.
                assert_eq!(real.read_u32(straddle + N - 4), None, "far field also None");

                // Wholly-committed window succeeds and matches the scalar reads.
                let inside = base as usize + PAGE - N;
                let window = real.read_object_window::<N>(inside).expect("inside window");
                assert_eq!(
                    u64::from_le_bytes(window[0..8].try_into().unwrap()),
                    real.read_u64(inside).unwrap()
                );

                let ok = VirtualFree(base, PAGE, T_MEM_DECOMMIT);
                assert_ne!(ok, 0, "decommit failed");
                page_cache_new_frame();
                assert_eq!(
                    real.read_object_window::<N>(inside),
                    None,
                    "window None after decommit"
                );
                assert_eq!(real.read_u64(inside), None, "scalar None after decommit");
                let _ = VirtualFree(base, 0, T_MEM_RELEASE);
            }
        }

