        // --- d47 (characters, FROZEN): only `read_u8` was made alloc-free; the
        //     multi-byte scalars stay as DEFAULTS (byte-by-byte via read_array).
        //     The shim mirrors the PRE-T1 allocating read_u8 so ALL of d47's reads
        //     run their byte-by-byte defaults over it. This proves the alloc-free
        //     read_u8 leaves every read byte-identical, INCLUDING the adjacent-
        //     committed-region case where a bulk read WOULD have diverged: the
        //     two regions abut, so a 8-byte read crossing the seam still succeeds
        //     byte-by-byte (matching the shim) rather than failing as a bulk read
        //     would. ---
        struct Domain47DefaultShim;
        impl domain47::extractor::LaneMemory for Domain47DefaultShim {
            fn read_u8(&self, addr: u64) -> Option<u8> {
                let addr = usize::try_from(addr).ok()?;
                read_bytes(addr, 1).and_then(|bytes| bytes.first().copied())
            }
        }

        #[test]
        fn t1_d47_read_u8_override_matches_default_including_region_seam() {
            use domain47::extractor::LaneMemory;
            const PAGE: usize = 0x1000;
            let real = Domain47InProcessMemory;
            let shim = Domain47DefaultShim;
            // Plain readable buffer: every scalar width agrees.
            page_cache_new_frame();
            let src: Vec<u8> = (0u8..=255).rev().collect();
            let base = src.as_ptr() as usize;
            for off in [0usize, 1, 3, 7, 16, 128, 200] {
                let a = (base + off) as u64;
                assert_eq!(real.read_u8(a), shim.read_u8(a), "d47 read_u8 @+{off}");
                assert_eq!(
                    real.read_u16_le(a),
                    shim.read_u16_le(a),
                    "d47 read_u16 @+{off}"
                );
                assert_eq!(
                    real.read_u32_le(a),
                    shim.read_u32_le(a),
                    "d47 read_u32 @+{off}"
                );
                assert_eq!(
                    real.read_i32_le(a),
                    shim.read_i32_le(a),
                    "d47 read_i32 @+{off}"
                );
                assert_eq!(
                    real.read_u64_le(a),
                    shim.read_u64_le(a),
                    "d47 read_u64 @+{off}"
                );
            }
            let bad = 0x1000u64;
            assert_eq!(real.read_u8(bad), shim.read_u8(bad));
            assert_eq!(real.read_u64_le(bad), shim.read_u64_le(bad));
            // Adjacent committed regions: a read crossing the seam must behave
            // identically for override and default (both byte-by-byte -> succeed).
            page_cache_new_frame();
            unsafe {
                // Reserve two pages, commit BOTH so the seam is committed<->committed.
                let base = VirtualAlloc(ptr::null_mut(), 2 * PAGE, T_MEM_RESERVE, T_PAGE_READWRITE);
                assert!(!base.is_null());
                let c0 = VirtualAlloc(base, PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                let c1 = VirtualAlloc(
                    (base as usize + PAGE) as *mut c_void,
                    PAGE,
                    MEM_COMMIT,
                    T_PAGE_READWRITE,
                );
                assert_eq!(c0, base);
                assert_eq!(c1 as usize, base as usize + PAGE);
                let bytes = base as *mut u8;
                for i in 0..(2 * PAGE) {
                    *bytes.add(i) = (i & 0xff) as u8;
                }
                page_cache_new_frame();
                let seam = (base as usize + PAGE - 4) as u64; // 8-byte read crosses seam
                assert_eq!(
                    real.read_u64_le(seam),
                    shim.read_u64_le(seam),
                    "d47 u64 across committed seam (byte-by-byte)"
                );
                // Straddle into a DECOMMITTED page must fail closed identically.
                let ok = VirtualFree((base as usize + PAGE) as *mut c_void, PAGE, T_MEM_DECOMMIT);
                assert_ne!(ok, 0, "decommit second page failed");
                page_cache_new_frame();
                assert_eq!(
                    real.read_u64_le(seam),
                    shim.read_u64_le(seam),
                    "d47 u64 across committed->decommitted seam"
                );
                assert!(real.read_u64_le(seam).is_none());
                let _ = VirtualFree(base, 0, T_MEM_RELEASE);
            }
        }

        // MICROBENCHMARK (Part A win, gated behind env var so it never runs in
        // the normal test pass). Times N=1e6 read_u64 over a valid in-process
        // buffer for BEFORE (VirtualQuery + vec alloc + memcpy — the old path,
        // reconstructed locally) vs AFTER (RPM + page-cache + stack array — the
        // shipped read_u64). Reads OWN process memory; needs no live game.
        //   RUN: RUN_P4C_MICROBENCH=1 cargo test --release -p collector \
        //        rpm_read_u64_microbench -- --nocapture --ignored
        // W11 (lane/w11-prefetch) READ-PRIMITIVE OUTCOME-SPLIT microbench.
        // ------------------------------------------------------------
        // W1.1 measurement prerequisite from runs/perf_rearch_20260706/
        // W0_AB_RESULTS.md §5.1: attribute where the SHIPPED read primitive's
        // per-read wall goes, split by the region-interval-cache OUTCOME, so the
        // "dark residual" (d53 wall not covered by the phase timers) can be
        // attributed to the primitive vs. downstream row materialisation.
        //
        // It exercises the EXACT shipped path (`range_confirmed_good` gate +
        // `copy_selected` SEH copy, via `read_u64`/`read_bytes`) on real
        // in-process memory (no live game needed), forcing one outcome per arm:
        //   * MRU hit    — read the SAME region repeatedly; after the first read
        //                  the per-thread REGION_MRU short-circuits (2 compares).
        //   * span hit   — round-robin across many regions within one frame so the
        //                  MRU misses but the sorted-disjoint span list hits
        //                  (partition_point binary search), no VirtualQuery.
        //   * region miss— `page_cache_new_frame()` before every read invalidates
        //                  the cache => one VirtualQuery syscall per read.
        //   * reject     — address outside any committed region: gate returns
        //                  false fast (VirtualQuery says not-committed), no copy.
        // Copy cost is reported separately at 8 B and at the 552 B d53 relation
        // hot-window size so the per-byte SEH copy share is explicit.
        //
        // RUN (from extractor/native/):
        //   RUN_OUTCOME_SPLIT=1 cargo test --release -p collector \
        //     read_outcome_split_microbench -- --nocapture --ignored
        // ============================================================
        // PLAN-V2 PHASE-1 DECISIVE EXPERIMENT: primitive contention bench.
        // Compares candidate read primitives under realistic concurrency,
        // working-set size, access shape, and concurrent memory churn (a
        // stand-in for the game touching its own memory at speed 5). Answers:
        //   * Is SEH-guarded direct read materially cheaper than RPM per read?
        //   * Does RPM cost blow up under 8/16/30 concurrent reader threads
        //     (kernel MM-lock contention)?
        //   * Does the VirtualQuery page-gate become the new bottleneck once
        //     the copy is cheap (isolated as gated-minus-direct)?
        //   * Correctness canary: SEH-direct returns the same bytes as RPM.
        //
        // RUN (from extractor/native/):
        //   RUN_PRIM_BENCH=1 cargo test --release -p collector \
        //     primitive_contention_microbench -- --nocapture --ignored
        // Optional env knobs (comma lists): BENCH_THREADS (default 1,4,8,16,30),
        //   BENCH_WS_MB (default 1024), BENCH_SHAPES (rand,seq,chain; default
        //   rand,chain), BENCH_CHURN (default 0,4), BENCH_READS (per-thread,
        //   default 1500000), BENCH_JSON_OUT (path to append one JSON line).
        #[derive(Clone, Copy, PartialEq, Eq)]
        enum BenchPrim {
            RawMemcpy,
            SehDirect,
            SehGated,
            RpmDirect,
            RpmGated,
            NtDirect,
        }

        impl BenchPrim {
            fn name(self) -> &'static str {
                match self {
                    BenchPrim::RawMemcpy => "raw_memcpy",
                    BenchPrim::SehDirect => "seh_direct",
                    BenchPrim::SehGated => "seh_gated(VQ+seh)",
                    BenchPrim::RpmDirect => "rpm_direct",
                    BenchPrim::RpmGated => "rpm_gated(SHIPPED)",
                    BenchPrim::NtDirect => "nt_direct",
                }
            }
        }

        /// Read one 8-byte scalar at `addr` via the chosen primitive. Mirrors
        /// the real gate logic for the *gated* variants (same page-cache /
        /// is_readable_range decision as `read_scalar`), swapping only the copy.
        #[inline]
        fn bench_read_u64(prim: BenchPrim, addr: usize) -> Option<u64> {
            match prim {
                BenchPrim::RawMemcpy => {
                    let mut b = [0u8; 8];
                    unsafe { ptr::copy_nonoverlapping(addr as *const u8, b.as_mut_ptr(), 8) };
                    Some(u64::from_le_bytes(b))
                }
                BenchPrim::SehDirect => {
                    let mut b = [0u8; 8];
                    if unsafe { seh_read_exact(addr, b.as_mut_ptr(), 8) } {
                        Some(u64::from_le_bytes(b))
                    } else {
                        None
                    }
                }
                BenchPrim::SehGated => {
                    let last = addr.checked_add(7)?;
                    if page_base(addr) == page_base(last) {
                        if !page_confirmed_good(page_base(addr)) {
                            return None;
                        }
                    } else if !is_readable_range(addr, 8) {
                        return None;
                    }
                    let mut b = [0u8; 8];
                    if unsafe { seh_read_exact(addr, b.as_mut_ptr(), 8) } {
                        Some(u64::from_le_bytes(b))
                    } else {
                        None
                    }
                }
                BenchPrim::RpmDirect => {
                    let mut b = [0u8; 8];
                    if unsafe { rpm_exact(addr, b.as_mut_ptr(), 8) } {
                        Some(u64::from_le_bytes(b))
                    } else {
                        None
                    }
                }
                BenchPrim::RpmGated => read_u64(addr),
                BenchPrim::NtDirect => {
                    let mut b = [0u8; 8];
                    if unsafe { ntrpm_exact(addr, b.as_mut_ptr(), 8) } {
                        Some(u64::from_le_bytes(b))
                    } else {
                        None
                    }
                }
            }
        }

        // Small xorshift so we do not depend on rand and stay deterministic.
        #[inline]
        fn bench_xs(state: &mut u64) -> u64 {
            let mut x = *state;
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            *state = x;
            x
        }

        #[derive(Clone, Copy, PartialEq, Eq)]
        enum BenchShape {
            Rand,
            Seq,
            Chain,
        }

        // GOLDEN EMIT-PATH test (Q5). The v1-emit bug — the emitter re-encoding
        // v1 and silently dropping side detail — was caught ONLY by the live
        // capture, not by decoder round-trip tests on hand-built packets. This
        // drives the ACTUAL collector emitter and asserts the produced record
        // is schema v7 with side-detail, attribution, reserve authority,
        // terminal records, and dormant X2 observation transports.
        #[test]
        fn land_combat_detail_emitter_produces_v7_record_with_exact_side_fields() {
            let side_detail_rows = vec![
                land_detail55::SideDetailRow {
                    combat_id: 21381,
                    generation: 7,
                    side: land_detail55::CombatSide::Attacker,
                    detail: golden_side_detail(2, 2),
                    reserve_members_known: false,
                },
                land_detail55::SideDetailRow {
                    combat_id: 21381,
                    generation: 7,
                    side: land_detail55::CombatSide::Defender,
                    detail: golden_side_detail(2, 0),
                    reserve_members_known: false,
                },
            ];
            let attribution_rows = vec![
                land_detail55::AttributionRow {
                    combat_id: 21381,
                    generation: 7,
                    side: land_detail55::CombatSide::Attacker,
                    entry: land_detail55::AttributionEntry {
                        dealer_tag_db_id: 3,
                        victim_tag_db_id: 1,
                        damage_raw: 1_421_400,
                    },
                },
                land_detail55::AttributionRow {
                    combat_id: 21381,
                    generation: 7,
                    side: land_detail55::CombatSide::Defender,
                    entry: land_detail55::AttributionEntry {
                        dealer_tag_db_id: 1,
                        victim_tag_db_id: 3,
                        damage_raw: 9_571_110,
                    },
                },
            ];
            let read = CompactLandCombatDetailEventsRead {
                frame: land_detail55::CaptureFrame {
                    compact_stream: Vec::new(),
                    rows: Vec::new(),
                    side_detail_rows: side_detail_rows.clone(),
                    attribution_rows: attribution_rows.clone(),
                    reserve_member_rows: Vec::new(),
                    terminal_record_rows: Vec::new(),
                    width_observation_rows: Vec::new(),
                    current_loss_observation_rows: Vec::new(),
                    panel_observation_rows: Vec::new(),
                },
                read_time_us: 0,
                status_flags: COMPACT_STATUS_DELTA_DATA,
            };

            let mut out = Vec::new();
            append_compact_land_combat_detail_events_data_record(&mut out, 1, 60_787_539, &read, 5);

            // Record header: domain 55, data record.
            let header_len = u16::from_le_bytes([out[6], out[7]]) as usize;
            let domain_id = u16::from_le_bytes([out[20], out[21]]);
            let record_type = u16::from_le_bytes([out[22], out[23]]);
            let payload_len = u32::from_le_bytes([out[24], out[25], out[26], out[27]]) as usize;
            assert_eq!(domain_id, COMPACT_DOMAIN_LAND_COMBAT_DETAIL_EVENTS_LIVE);
            assert_eq!(record_type, COMPACT_RECORD_TYPE_DOMAIN_DATA);
            let payload = &out[header_len..header_len + payload_len];

            // MUST be schema v7; older encoders lack the dormant X2 transports.
            let version = u16::from_le_bytes([payload[0], payload[1]]);
            assert_eq!(
                version,
                land_detail55::SCHEMA_VERSION,
                "emitter must produce schema v7"
            );
            // v7 52-byte header; side_detail_row_count @ offset 24.
            let side_count =
                u32::from_le_bytes([payload[24], payload[25], payload[26], payload[27]]);
            assert_eq!(
                side_count, 2,
                "both side-detail rows present in header count"
            );
            let attribution_count =
                u32::from_le_bytes([payload[28], payload[29], payload[30], payload[31]]);
            assert_eq!(
                attribution_count, 2,
                "both attribution rows present in header count"
            );
            let expected_len = land_detail55::PAYLOAD_HEADER_LEN
                + land_detail55::SIDE_DETAIL_ROW_LEN * 2
                + land_detail55::ATTRIBUTION_ROW_LEN * 2
                + (4 + "tactic_basic_attack".len())
                + (4 + "TACTIC_BASIC_ATTACK".len());
            assert_eq!(
                payload.len(),
                expected_len,
                "v7 payload byte length including tactic strings must be exact"
            );
            // Round-trip: the emitted record decodes back to the same rows.
            let decoded = land_detail55::decode_detail_events_payload(0, payload)
                .expect("emitted v7 record decodes");
            assert_eq!(decoded.side_detail_rows, side_detail_rows);
            assert_eq!(decoded.attribution_rows, attribution_rows);
            assert_eq!(
                decoded.side_detail_rows[0].detail.progress_raw,
                Some(53_000)
            );
            assert_eq!(
                decoded.side_detail_rows[0]
                    .detail
                    .tactic
                    .as_ref()
                    .map(|tactic| (tactic.id, tactic.token.as_str(), tactic.name.as_str())),
                Some((7, "tactic_basic_attack", "TACTIC_BASIC_ATTACK"))
            );
        }

        // GOLDEN REBASELINE test (Q5): the transition-baseline path emits
        // CURRENT-STATE side detail (not just deltas) even with ZERO event
        // rows. A regression that skipped side detail on rebaseline would show
        // combats with no detail right after a capture gap.
        #[test]
        fn land_combat_detail_rebaseline_emits_side_detail_with_zero_events() {
            struct Mem(Vec<land_detail55::LandCombatSnapshot>);
            impl land_detail55::LandCombatDetailMemory for Mem {
                fn land_combat_snapshots(
                    &self,
                ) -> Result<Vec<land_detail55::LandCombatSnapshot>, Vec<String>> {
                    Ok(self.0.clone())
                }
            }
            let snap = land_detail55::LandCombatSnapshot {
                combat_id: 21381,
                generation: 7,
                location: Some(3236),
                day: Some(192),
                duration: Some(192),
                attacker_divisions: vec![101, 102, 103, 104],
                defender_divisions: vec![201, 202],
                attacker_detail: Some(golden_side_detail(2, 2)),
                defender_detail: Some(golden_side_detail(2, 0)),
                attacker_attribution: vec![land_detail55::AttributionEntry {
                    dealer_tag_db_id: 3,
                    victim_tag_db_id: 1,
                    damage_raw: 1_421_400,
                }],
                defender_attribution: vec![land_detail55::AttributionEntry {
                    dealer_tag_db_id: 1,
                    victim_tag_db_id: 3,
                    damage_raw: 9_571_110,
                }],
                attacker_reserve_divisions: Some(vec![103, 104]),
                defender_reserve_divisions: Some(Vec::new()),
            };
            let mut tracker = land_detail55::LandCombatDetailTracker::default();
            tracker.reset_transition_baseline();
            let mem = Mem(vec![snap]);
            let frame = land_detail55::collect_transition_capture_frame(
                &mem,
                &mut tracker,
                0,
                60_787_539,
                1,
            )
            .expect("rebaseline frame");
            // Zero event rows on rebaseline, but current-state side detail present.
            assert!(
                frame.rows.is_empty(),
                "rebaseline emits no synthetic events"
            );
            assert_eq!(
                frame.side_detail_rows.len(),
                2,
                "rebaseline still emits current-state side detail"
            );
            assert_eq!(
                frame.attribution_rows.len(),
                2,
                "rebaseline still emits current-state attribution"
            );
            let payload = &frame.compact_stream[COMPACT_RECORD_HEADER_LEN as usize..];
            let version = u16::from_le_bytes([payload[0], payload[1]]);
            assert_eq!(version, land_detail55::SCHEMA_VERSION);
            let decoded = land_detail55::decode_detail_events_payload(0, payload)
                .expect("rebaseline v3 decodes");
            assert_eq!(decoded.rows.len(), 0);
            assert_eq!(decoded.side_detail_rows.len(), 2);
            assert_eq!(decoded.attribution_rows.len(), 2);
            assert_ne!(
                decoded.status_flags & land_detail55::STATUS_TRANSITION_BASELINE_RESET,
                0
            );
        }

