        /// Stale-generation discard: adopt a completed validation only if its
        /// generation is strictly newer than the set already held.
        /// Completed-set retention while rebuilding: with a validation in flight
        /// and a prior completed set, the spawn gate stays false (no restart) and
        /// the prior discovery remains the one a frame would consume.
        /// A default tracker holds no in-flight thread to leak; dropping is a
        /// no-op (Drop joins only a live handle).
        #[test]
        fn capwar60_tracker_default_has_no_thread_to_leak() {
            let tracker = CompactCapitulationWarStateLiveTracker::default();
            assert!(tracker.discovery.is_none());
            assert_eq!(tracker.validated_gen, None);
            assert_eq!(tracker.attempted_gen, None);
            assert_eq!(tracker.validation_failure_gen, None);
            assert_eq!(tracker.validation_failure_reason, None);
            assert_eq!(tracker.validation_failure_streak, 0);
            assert_eq!(tracker.validation_retry_not_before, None);
            assert!(tracker.validation_handle.is_none());
            drop(tracker);
        }

