        #[test]
        fn compact_frame_end_marks_invalid_scheduled_domains_control() {
            let mut control = raw_test_control();
            control.stream_format = CollectorStreamFormat::Compact;
            control.scheduled_domains_valid = false;
            control.scheduled_domains_error = Some("too_many");

            let mut trackers = CompactPerfGateTrackers::default();
            let (records, next_sequence, timing) = build_compact_extraction_gate_records(
                None,
                &control,
                1,
                0,
                None,
                None,
                None,
                None,
                None,
                &mut trackers,
                None,
                None,
                None,
            );
            // The stream may carry an attribution-probe record (domain 250)
            // BEFORE the frame end: this path records the CONTROL_INVALID
            // status origin, and the global registry may also hold origins
            // from concurrently-running tests (or have had ours drained by
            // one) — so walk the records instead of assuming a fixed layout.
            assert!((2..=3).contains(&next_sequence), "{next_sequence}");
            assert_ne!(timing.status_flags & COMPACT_STATUS_CONTROL_INVALID, 0);

            let mut offset = 0usize;
            let mut last_record: Option<(u16, u32)> = None; // (type, status)
            while offset < records.len() {
                let header = &records[offset..offset + compact_contract::COMPACT_RECORD_HEADER_LEN];
                let record_type = u16::from_le_bytes([header[22], header[23]]);
                let payload_len =
                    u32::from_le_bytes([header[24], header[25], header[26], header[27]]) as usize;
                let payload_start = offset + compact_contract::COMPACT_RECORD_HEADER_LEN;
                // Frame-end payload carries status at offset 24.
                let status = u32::from_le_bytes([
                    records[payload_start + 24],
                    records[payload_start + 25],
                    records[payload_start + 26],
                    records[payload_start + 27],
                ]);
                last_record = Some((record_type, status));
                offset = payload_start + payload_len;
            }
            let (record_type, status_flags) = last_record.expect("at least one record");
            assert_eq!(
                record_type,
                compact_contract::COMPACT_RECORD_TYPE_FRAME_END,
                "the FINAL record must be the frame end"
            );
            assert_ne!(status_flags & COMPACT_STATUS_CONTROL_INVALID, 0);
        }

        #[test]
        fn xui21_d75_emits_typed_incomplete_data_before_frame_end_without_hooks() {
            let mut control = raw_test_control();
            control.stream_format = CollectorStreamFormat::Compact;
            control.scheduled_domains = vec![RAW_FIRED_EVENT_POPUPS_LIVE_DOMAIN.to_string()];
            let state = empty_collector_state();
            let mut trackers = CompactPerfGateTrackers::default();
            let hour_index = 16_959_360i64;
            let game_hour_raw = compact_contract::calendar::DATE_EPOCH_CONST
                .checked_add(hour_index as i32)
                .unwrap();
            let (records, _, _) = build_compact_extraction_gate_records(
                Some(&state),
                &control,
                1,
                7,
                Some(game_hour_raw),
                None,
                None,
                None,
                None,
                &mut trackers,
                None,
                None,
                None,
            );
            let mut headers = Vec::new();
            let mut offset = 0usize;
            while offset < records.len() {
                let header = compact_contract::parse_compact_record_header(&records[offset..])
                    .expect("valid compact record");
                offset += header.record_len();
                headers.push(header);
            }
            let d75 = headers
                .iter()
                .filter(|header| header.domain_id == COMPACT_DOMAIN_FIRED_EVENT_POPUPS_LIVE)
                .map(|header| header.record_type)
                .collect::<Vec<_>>();
            assert_eq!(
                d75,
                vec![
                    COMPACT_RECORD_TYPE_DOMAIN_PERF,
                    COMPACT_RECORD_TYPE_DOMAIN_DATA
                ]
            );
            assert_eq!(
                headers.last().map(|header| header.record_type),
                Some(COMPACT_RECORD_TYPE_FRAME_END)
            );
        }

        #[test]
        fn hour_latch_frontier_labels_frame_when_sweep_clock_is_stale() {
            let stale_clock = ClockSample {
                date: "stale".to_string(),
                hour_index: 0,
                raw_date: 100,
            };
            let mut latch = HourLatch::new(64);
            let mut emitted_labels = Vec::new();

            latch.observe(100);
            let first = latch.take_capture();
            let first_label =
                compact_sweep_game_hour(Some(first), false, Some(&stale_clock)).unwrap();
            let mut first_records = Vec::new();
            append_compact_frame_end_record(&mut first_records, 1, first_label, 0, 0, 0, 0, 0);
            assert!(compact_frame_complete_for_hour_latch(
                &first_records,
                first_label
            ));
            latch.record_complete_frame_emitted_to_sink();
            emitted_labels.push(
                compact_contract::parse_compact_record_header(&first_records)
                    .unwrap()
                    .game_hour_raw,
            );

            // The previous hour was emitted, the sweep clock still reads that
            // previous hour, but the latch has observed and consumed the next.
            latch.observe(101);
            let second = latch.take_capture();
            let second_label =
                compact_sweep_game_hour(Some(second), false, Some(&stale_clock)).unwrap();
            let mut second_records = Vec::new();
            append_compact_frame_end_record(&mut second_records, 2, second_label, 0, 0, 0, 0, 0);
            assert!(compact_frame_complete_for_hour_latch(
                &second_records,
                second_label
            ));
            assert!(
                !compact_frame_complete_for_hour_latch(&second_records, 100),
                "a stale duplicate label must fail the frontier-completeness gate"
            );
            latch.record_complete_frame_emitted_to_sink();
            emitted_labels.push(
                compact_contract::parse_compact_record_header(&second_records)
                    .unwrap()
                    .game_hour_raw,
            );

            assert_eq!(emitted_labels, vec![100, 101], "no duplicate stale label");
            let telemetry = latch.telemetry();
            assert_eq!(telemetry.observed, 2);
            assert_eq!(telemetry.attempts, 2);
            assert_eq!(telemetry.emitted_to_sink, 2);
            assert_eq!(telemetry.capture_failed(), 0);
            assert!(telemetry.invariant_holds(), "frontier gap: {telemetry:?}");
        }

