        fn identity_v1_test_record() -> Vec<u8> {
            use compact_contract::campaign_identity::{
                encode_cid1, Cid1Fields, Cid1Observation, Cid1Witnesses,
                COMPACT_DOMAIN_STREAM_HEADER, COMPACT_RECORD_TYPE_STREAM_HEADER,
            };
            let observation = Cid1Observation {
                game_unique_id: "a4b17fed-ed12-4361-9064-fb6576638110".to_string(),
                game_unique_seed: -1234,
                game_hour_raw: identity_v1_test_hour(),
            };
            let fields = Cid1Fields::from_stable_observations(
                observation.clone(),
                observation,
                "test-profile".to_string(),
                Cid1Witnesses::default(),
            )
            .unwrap();
            let payload = encode_cid1(&fields).unwrap();
            let mut record = Vec::new();
            append_compact_record(
                &mut record,
                0,
                identity_v1_test_hour(),
                COMPACT_DOMAIN_STREAM_HEADER,
                COMPACT_RECORD_TYPE_STREAM_HEADER,
                0,
                &payload,
            );
            record
        }

        fn fresh_pipe_identity_barrier(
            logical_stream_id: u64,
            cid1: &[u8],
        ) -> IdentityV1ProducerBarrier<Vec<u8>> {
            let permit = FreshIdentitySinkPermit::inspect(
                None,
                Some(FreshIdentityPipe::for_new_session_pipe(Vec::new())),
            )
            .unwrap();
            IdentityV1ProducerBarrier::stage(logical_stream_id, cid1, permit).unwrap()
        }

        fn identity_test_file(initial: &[u8]) -> (PathBuf, std::fs::File) {
            static NEXT_FILE: AtomicU64 = AtomicU64::new(1);
            let path = std::env::temp_dir().join(format!(
                "hoi4_identity_v1_barrier_{}_{}.bin",
                std::process::id(),
                NEXT_FILE.fetch_add(1, Ordering::Relaxed)
            ));
            let _ = fs::remove_file(&path);
            let mut file = OpenOptions::new()
                .create_new(true)
                .read(true)
                .write(true)
                .open(&path)
                .unwrap();
            if !initial.is_empty() {
                file.write_all(initial).unwrap();
            }
            (path, file)
        }

        fn identity_test_read_only_file() -> (PathBuf, std::fs::File) {
            let (path, file) = identity_test_file(&[]);
            drop(file);
            let file = OpenOptions::new().read(true).open(&path).unwrap();
            (path, file)
        }

        struct FailingIdentityPipe;

        impl Write for FailingIdentityPipe {
            fn write(&mut self, _buf: &[u8]) -> std::io::Result<usize> {
                Err(std::io::Error::new(
                    std::io::ErrorKind::BrokenPipe,
                    "synthetic pipe failure",
                ))
            }

            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }

        fn write_identity_header(barrier: &mut IdentityV1ProducerBarrier<Vec<u8>>) {
            barrier.write_first_record().unwrap();
        }

        #[test]
        fn cid1_is_the_sole_first_write_to_every_configured_sink() {
            let cid1 = identity_v1_test_record();
            let (path, file) = identity_test_file(&[]);
            let permit = FreshIdentitySinkPermit::inspect(
                Some(file),
                Some(FreshIdentityPipe::for_new_session_pipe(Vec::new())),
            )
            .unwrap();
            let mut barrier = IdentityV1ProducerBarrier::stage(7, &cid1, permit).unwrap();
            barrier.write_first_record().unwrap();
            barrier.file_sink.as_mut().unwrap().flush().unwrap();
            assert_eq!(fs::read(&path).unwrap(), cid1);
            assert_eq!(barrier.pipe_sink.as_ref().unwrap(), &cid1);
            assert_eq!(barrier.first_record(), cid1);
            let header =
                compact_contract::parse_compact_record_header(&fs::read(&path).unwrap()).unwrap();
            assert_eq!(
                (header.sequence, header.domain_id, header.record_type),
                (0, 0, 4)
            );
            assert_eq!(barrier.phase(), IdentityV1ProducerPhase::AwaitingCfa1);
            drop(barrier);
            fs::remove_file(path).unwrap();
        }

        #[test]
        fn identity_v1_barrier_retains_dual_sink_topology_for_ordinary_writes() {
            let cid1 = identity_v1_test_record();
            let (path, file) = identity_test_file(&[]);
            let permit = FreshIdentitySinkPermit::inspect(
                Some(file),
                Some(FreshIdentityPipe::for_new_session_pipe(Vec::new())),
            )
            .unwrap();
            let mut barrier = IdentityV1ProducerBarrier::stage(7, &cid1, permit).unwrap();
            barrier.write_first_record().unwrap();
            let ack = compact_contract::first_compact_ack::encode_first_compact_frame_ack(
                barrier.expected_ack(),
            )
            .unwrap();
            barrier.accept_cfa1(&ack).unwrap();

            let mut ordinary = Vec::new();
            append_compact_frame_end_record(
                &mut ordinary,
                1,
                identity_v1_test_hour(),
                0,
                0,
                0,
                0,
                0,
            );
            barrier.write_ordinary_record(&ordinary).unwrap();
            barrier.file_sink.as_mut().unwrap().flush().unwrap();

            let mut expected = cid1;
            expected.extend_from_slice(&ordinary);
            assert_eq!(fs::read(&path).unwrap(), expected);
            assert_eq!(barrier.pipe_sink.as_ref().unwrap(), &expected);
            assert_eq!(
                barrier.phase(),
                IdentityV1ProducerPhase::Streaming { next_sequence: 2 }
            );
            drop(barrier);
            fs::remove_file(path).unwrap();
        }

