            assert!(barrier
                .with_next_ordinary_sequence(|_| build_calls += 1)
                .is_err());
            assert_eq!(build_calls, 0);
            write_identity_header(&mut barrier);
            assert!(barrier
                .with_next_ordinary_sequence(|_| build_calls += 1)
                .is_err());
