        #[test]
        fn every_cfa1_binding_field_mismatch_is_terminal() {
            let cid1 = identity_v1_test_record();
            for (name, offset, bytes) in [
                ("logical_stream_id", 8usize, 8u64.to_le_bytes().to_vec()),
                ("sequence", 16, 1u64.to_le_bytes().to_vec()),
                (
                    "hour",
                    24,
                    (identity_v1_test_hour() + 24).to_le_bytes().to_vec(),
                ),
                ("domain", 28, 1u16.to_le_bytes().to_vec()),
                ("type", 30, 1u16.to_le_bytes().to_vec()),
                ("record_len", 32, 73u32.to_le_bytes().to_vec()),
                ("complete_hash", 40, vec![0xA5]),
                ("payload_hash", 72, vec![0x5A]),
            ] {
                let mut barrier = fresh_pipe_identity_barrier(7, &cid1);
                write_identity_header(&mut barrier);
                let mut wire = compact_contract::first_compact_ack::encode_first_compact_frame_ack(
                    barrier.expected_ack(),
                )
                .unwrap();
                let bytes = if matches!(name, "complete_hash" | "payload_hash") {
                    vec![wire[offset] ^ 1]
                } else {
                    bytes
                };
                wire[offset..offset + bytes.len()].copy_from_slice(&bytes);
                assert!(barrier.accept_cfa1(&wire).is_err(), "{name}");
                assert_eq!(barrier.phase(), IdentityV1ProducerPhase::Terminal, "{name}");
                let mut calls = 0;
                assert!(barrier.with_next_ordinary_sequence(|_| calls += 1).is_err());
                assert_eq!(calls, 0, "{name}");
            }
        }

        #[test]
        fn nonempty_or_mixed_sink_header_failure_is_terminal() {
            let cid1 = identity_v1_test_record();
            let (path, seeded_file) = identity_test_file(b"old-stream");
            assert!(FreshIdentitySinkPermit::inspect(
                Some(seeded_file),
                Some(FreshIdentityPipe::for_new_session_pipe(Vec::new())),
            )
            .is_err());
            fs::remove_file(path).unwrap();

            let (path, mut displaced_file) = identity_test_file(&[]);
            displaced_file.seek(std::io::SeekFrom::Start(8)).unwrap();
            assert!(FreshIdentitySinkPermit::inspect(
                Some(displaced_file),
                Some(FreshIdentityPipe::for_new_session_pipe(Vec::new())),
            )
            .is_err());
            fs::remove_file(path).unwrap();

            let (path, file) = identity_test_file(&[]);
            let permit = FreshIdentitySinkPermit::inspect(
                Some(file),
                Some(FreshIdentityPipe::for_new_session_pipe(FailingIdentityPipe)),
            )
            .unwrap();
            let mut pipe_failure = IdentityV1ProducerBarrier::stage(7, &cid1, permit).unwrap();
            assert!(pipe_failure.write_first_record().is_err());
            assert!(pipe_failure.sink_delivery.terminal);
            assert_eq!(pipe_failure.phase(), IdentityV1ProducerPhase::Terminal);
            drop(pipe_failure);
            fs::remove_file(path).unwrap();

            let (path, file) = identity_test_read_only_file();
            let permit = FreshIdentitySinkPermit::inspect(
                Some(file),
                Some(FreshIdentityPipe::for_new_session_pipe(Vec::new())),
            )
            .unwrap();
            let mut file_failure = IdentityV1ProducerBarrier::stage(7, &cid1, permit).unwrap();
            assert!(file_failure.write_first_record().is_err());
            assert!(file_failure.sink_delivery.terminal);
            assert_eq!(file_failure.phase(), IdentityV1ProducerPhase::Terminal);
            drop(file_failure);
            fs::remove_file(path).unwrap();
        }

