        #[test]
        fn mixed_sink_partial_write_poison_is_terminal_and_blocks_later_records() {
            let mut state = SinkDeliveryState::new(true, true);
            let mut file_calls = 0usize;
            let mut pipe_calls = 0usize;
            let first = write_sinks_with(
                &mut state,
                b"authoritative-frame-1",
                |_| {
                    file_calls += 1;
                    Ok(())
                },
                |bytes| {
                    pipe_calls += 1;
                    let mut first_chunk = true;
                    if write_all_with(bytes, |chunk| {
                        if first_chunk {
                            first_chunk = false;
                            Some(chunk.len().min(4))
                        } else {
                            None
                        }
                    }) {
                        Ok(())
                    } else {
                        Err(std::io::Error::new(
                            std::io::ErrorKind::BrokenPipe,
                            "synthetic partial pipe write",
                        ))
                    }
                },
            );
            assert!(!first.complete());
            assert!(state.terminal);
            assert!(!state.file_poisoned);
            assert!(state.pipe_poisoned);
            assert_eq!(state.write_failures, 1);
            assert_eq!((file_calls, pipe_calls), (1, 1));

            let second = write_sinks_with(
                &mut state,
                b"must-not-be-written",
                |_| {
                    file_calls += 1;
                    Ok(())
                },
                |_| {
                    pipe_calls += 1;
                    Ok(())
                },
            );
            assert!(!second.complete());
            assert_eq!((file_calls, pipe_calls), (1, 1));
            assert_eq!(state.write_failures, 1, "terminal retries are not writes");
        }

        #[test]
        fn requested_but_unopened_pipe_produces_typed_setup_failure() {
            use compact_contract::sink_failure::{SinkFailureKind, SinkTopology};

            let state = SinkDeliveryState::from_open_results(false, false, true, false);
            assert!(state.terminal);
            assert_eq!(state.configured_sink_count(), 1);
            assert_eq!(state.opened_sink_count(), 0);
            assert_eq!(state.open_failures, 1);
            let report = state.failure_report().expect("typed setup report");
            assert_eq!(report.kind, SinkFailureKind::Setup);
            assert_eq!(report.requested.bits(), SinkTopology::PIPE);
            assert_eq!(report.opened.bits(), 0);
            assert_eq!(report.failed.bits(), SinkTopology::PIPE);
            assert_eq!(report.failed_sequence, None);
        }

