        fn hour_latch_partial_frame_is_attempted_but_not_recorded_complete() {
            let hour = 101;
            let mut records = Vec::new();
            append_compact_domain_perf_record(
                &mut records,
                1,
                hour,
                CompactDomainPerfRecord {
                    domain_id: COMPACT_DOMAIN_FUEL,
                    read_time_us: 0,
                    row_count: 0,
                    changed_rows: 0,
                    unit_count: 0,
                    changed_unit_count: 0,
                    status_flags: COMPACT_STATUS_PARTIAL_DATA,
                },
                0,
            );
            append_compact_frame_end_record(&mut records, 2, hour, 0, 0, 1, 1, 0);

            let mut latch = HourLatch::new(64);
            latch.observe(hour);
            assert!(matches!(
                latch.take_capture(),
                CaptureDecision::Capture { hour: 101, .. }
            ));
            let complete = compact_frame_complete_for_hour_latch(&records, hour);
            if complete {
                latch.record_complete_frame_emitted_to_sink();
            }

            assert!(!complete, "non-tolerated PARTIAL must fail closed");
            let telemetry = latch.telemetry();
            assert_eq!(telemetry.attempts, 1);
            assert_eq!(telemetry.emitted_to_sink, 0);
            assert_eq!(telemetry.capture_failed(), 1);
            assert!(telemetry.invariant_holds());
        }

