        fn hour_latch_barrier_test_lock() -> &'static Mutex<()> {
            static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
            LOCK.get_or_init(|| Mutex::new(()))
        }

        fn boundary_test_hour_latch_runtime(
            date_addr: usize,
            pause_addr: usize,
            initial_hour: i32,
        ) -> HourLatchRuntime {
            let mut latch = HourLatch::new(64);
            latch.observe(initial_hour);
            let barrier_original_pause =
                Arc::new(AtomicU8::new(HOUR_LATCH_NO_PAUSE_OVERRIDE));
            let barrier_acquisitions = Arc::new(AtomicU64::new(0));
            let barrier_failures = Arc::new(AtomicU64::new(0));
            let barrier_releases = Arc::new(AtomicU64::new(0));
            let barrier_restore_failures = Arc::new(AtomicU64::new(0));
            acquire_hour_latch_capture_barrier(
                pause_addr,
                &barrier_original_pause,
                &barrier_acquisitions,
                &barrier_failures,
            );
            HourLatchRuntime {
                shared: Arc::new((Mutex::new(latch), Condvar::new())),
                shutdown: Arc::new(AtomicBool::new(false)),
                handle: None,
                date_addr,
                pause_addr,
                barrier_original_pause,
                barrier_acquisitions,
                barrier_failures,
                barrier_releases,
                barrier_restore_failures,
                last_completed_boundary: Mutex::new(None),
            }
        }

        #[test]
        fn hour_latch_capture_barrier_freezes_and_restores_running_clock() {
            let _guard = hour_latch_barrier_test_lock()
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            HOUR_LATCH_CAPTURE_PAUSE_OVERRIDE
                .store(HOUR_LATCH_NO_PAUSE_OVERRIDE, Ordering::Release);
            let mut pause = 0u8;
            let original = AtomicU8::new(HOUR_LATCH_NO_PAUSE_OVERRIDE);
            let acquisitions = AtomicU64::new(0);
            let failures = AtomicU64::new(0);
            let releases = AtomicU64::new(0);
            let restore_failures = AtomicU64::new(0);

            acquire_hour_latch_capture_barrier(
                (&mut pause as *mut u8) as usize,
                &original,
                &acquisitions,
                &failures,
            );
            assert_eq!(pause, 1);
            assert_eq!(original.load(Ordering::Acquire), 0);
            assert_eq!(
                HOUR_LATCH_CAPTURE_PAUSE_OVERRIDE.load(Ordering::Acquire),
                0
            );
            assert_eq!(acquisitions.load(Ordering::Acquire), 1);
            assert_eq!(failures.load(Ordering::Acquire), 0);

            release_hour_latch_capture_barrier(
                (&mut pause as *mut u8) as usize,
                &original,
                &releases,
                &restore_failures,
            );
            assert_eq!(pause, 0);
            assert_eq!(
                HOUR_LATCH_CAPTURE_PAUSE_OVERRIDE.load(Ordering::Acquire),
                HOUR_LATCH_NO_PAUSE_OVERRIDE
            );
            assert_eq!(releases.load(Ordering::Acquire), 1);
            assert_eq!(restore_failures.load(Ordering::Acquire), 0);
        }

        #[test]
        fn hour_latch_capture_barrier_preserves_player_paused_state() {
            let _guard = hour_latch_barrier_test_lock()
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            HOUR_LATCH_CAPTURE_PAUSE_OVERRIDE
                .store(HOUR_LATCH_NO_PAUSE_OVERRIDE, Ordering::Release);
            let mut pause = 1u8;
            let original = AtomicU8::new(HOUR_LATCH_NO_PAUSE_OVERRIDE);
            let acquisitions = AtomicU64::new(0);
            let failures = AtomicU64::new(0);
            let releases = AtomicU64::new(0);
            let restore_failures = AtomicU64::new(0);

            acquire_hour_latch_capture_barrier(
                (&mut pause as *mut u8) as usize,
                &original,
                &acquisitions,
                &failures,
            );
            release_hour_latch_capture_barrier(
                (&mut pause as *mut u8) as usize,
                &original,
                &releases,
                &restore_failures,
            );

            assert_eq!(pause, 1);
            assert_eq!(acquisitions.load(Ordering::Acquire), 1);
            assert_eq!(failures.load(Ordering::Acquire), 0);
            assert_eq!(releases.load(Ordering::Acquire), 1);
            assert_eq!(restore_failures.load(Ordering::Acquire), 0);
        }

        #[test]
        fn hour_latch_shutdown_reports_last_completed_capture_boundary() {
            let _guard = hour_latch_barrier_test_lock()
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            HOUR_LATCH_CAPTURE_PAUSE_OVERRIDE
                .store(HOUR_LATCH_NO_PAUSE_OVERRIDE, Ordering::Release);
            let mut date = 100i32;
            let mut pause = 0u8;
            let initial_hour = date;
            let mut runtime = boundary_test_hour_latch_runtime(
                (&mut date as *mut i32) as usize,
                (&mut pause as *mut u8) as usize,
                initial_hour,
            );

            assert_eq!(
                runtime.decide(),
                CaptureDecision::Capture {
                    hour: 100,
                    coalesced: 0,
                }
            );
            runtime.release_capture_barrier_and_commit_boundary();
            assert_eq!(pause, 0);

            // The sim advances after the completed frame boundary but before the
            // sweep loop notices graceful shutdown. The latch truthfully sees
            // and freezes it, but it is outside the declared capture interval.
            date = 101;
            {
                let (lock, _cvar) = &*runtime.shared;
                lock.lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .observe(date);
            }
            acquire_hour_latch_capture_barrier(
                runtime.pause_addr,
                &runtime.barrier_original_pause,
                &runtime.barrier_acquisitions,
                &runtime.barrier_failures,
            );
            let live = runtime.telemetry();
            assert_eq!(live.observed, 2);
            assert_eq!(live.attempts, 1);
            assert_eq!(live.in_flight, 1);
            assert_eq!(live.capture_barrier_acquisitions, 2);
            assert_eq!(pause, 1);

            let terminal = runtime.shutdown_and_flush();
            assert_eq!(pause, 0);
            assert_eq!(terminal.observed, 1);
            assert_eq!(terminal.attempts, 1);
            assert_eq!(terminal.coalesced, 0);
            assert_eq!(terminal.in_flight, 0);
            assert_eq!(terminal.capture_barrier_acquisitions, 1);
            assert_eq!(terminal.capture_barrier_releases, 1);
            assert!(terminal.invariant_holds());
        }

        #[test]
        fn hour_latch_shutdown_without_completed_boundary_fails_closed() {
            let _guard = hour_latch_barrier_test_lock()
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            HOUR_LATCH_CAPTURE_PAUSE_OVERRIDE
                .store(HOUR_LATCH_NO_PAUSE_OVERRIDE, Ordering::Release);
            let mut date = 200i32;
            let mut pause = 0u8;
            let initial_hour = date;
            let mut runtime = boundary_test_hour_latch_runtime(
                (&mut date as *mut i32) as usize,
                (&mut pause as *mut u8) as usize,
                initial_hour,
            );

            // No sweep ever consumed the initial frontier, so there is no valid
            // completed endpoint to substitute for the flushed live accounting.
            let terminal = runtime.shutdown_and_flush();
            assert_eq!(pause, 0);
            assert_eq!(terminal.observed, 1);
            assert_eq!(terminal.attempts, 0);
            assert_eq!(terminal.coalesced, 1);
            assert_eq!(terminal.coalesced_flush, 1);
            assert_eq!(terminal.capture_barrier_acquisitions, 1);
            assert_eq!(terminal.capture_barrier_releases, 1);
            assert!(terminal.invariant_holds());
        }

