        #[test]
        fn compact_delayed_events_rejection_surfaces_first_class_country_and_address() {
            let class_name = ".?AVCUnclassifiedTimedEffect@@";
            let rejected = compact_delayed_events_from_domain51_scan(
                Domain51DelayedEventScan::RejectedTimedEffect(
                    Domain64TimedEffectRejection {
                        reason: Domain64TimedEffectRejectionReason::UnsupportedClass,
                        country_tag_db_id: 68,
                        element_address: 0x1234_5678,
                        observed_vtable: 0x14321_0000,
                        class_name_fnv1a64: fnv1a_64(class_name.as_bytes()),
                        originator_tag_db_id: None,
                    },
                ),
                COMPACT_STATUS_EXTRACTION_PERF_GATE,
                29,
            );

            assert!(rejected.rows.is_empty());
            assert_eq!(
                rejected.status_flags,
                COMPACT_STATUS_EXTRACTION_PERF_GATE | COMPACT_STATUS_SOURCE_UNAVAILABLE
            );
            let value = |name| {
                rejected
                    .diagnostic_units
                    .iter()
                    .find(|unit| unit.name == name)
                    .map(|unit| unit.value)
            };
            assert_eq!(
                value("d64_first_rejected_timed_effect_reason"),
                Some(Domain64TimedEffectRejectionReason::UnsupportedClass as u64)
            );
            assert_eq!(
                value("d64_first_rejected_timed_effect_country_tag_db_id"),
                Some(68)
            );
            assert_eq!(
                value("d64_first_rejected_timed_effect_address"),
                Some(0x1234_5678)
            );
            assert_eq!(
                value("d64_first_rejected_timed_effect_vtable"),
                Some(0x14321_0000)
            );
            assert_eq!(
                value("d64_first_rejected_timed_effect_class_fnv1a64"),
                Some(fnv1a_64(class_name.as_bytes()))
            );
            assert_eq!(
                value("d64_first_rejected_timed_effect_originator_tag_db_id"),
                Some(u64::MAX)
            );
        }

