        #[test]
        fn compact_delayed_events_payload_packs_melt_anchored_rows() {
            // Melt-anchored (D04 oracle, independently re-derived from
            // 00_d04_1944_melted.txt):
            //   GER line 970643: event_id 42900001, hours=14 days=2 months=0
            //     -> remaining = 0*720 + 2*24 + 14 = 62.
            //   ITA line 1602315: event_id 6700000, hours=14 days=3 months=4
            //     -> remaining = 4*720 + 3*24 + 14 = 2966.
            // These are legacy-compatibility wire fixtures that deliberately
            // leave originator absent to prove the flag/zero packing law.
            // Exact-a729 production collection now always carries the
            // independently read +0xC0 originator. A third row has both
            // due/originator absent (flags 0).
            let ger = CompactDelayedEventRow {
                owner_tag_db_id: 1,
                event_id: 42_900_001,
                originator_tag_db_id: None,
                due_remaining_hours: Some(62),
            };
            let ita = CompactDelayedEventRow {
                owner_tag_db_id: 2,
                event_id: 6_700_000,
                originator_tag_db_id: None,
                due_remaining_hours: Some(2966),
            };
            let absent = CompactDelayedEventRow {
                owner_tag_db_id: 3,
                event_id: 28_200_333,
                originator_tag_db_id: None,
                due_remaining_hours: None,
            };

            let payload = compact_delayed_events_data_payload(
                &[ger, ita, absent],
                None,
                77,
                COMPACT_STATUS_EXTRACTION_PERF_GATE,
            );

            assert_eq!(payload.len(), 20 + 3 * COMPACT_DELAYED_EVENT_ROW_LEN);
            assert_eq!(u64::from_le_bytes(payload[0..8].try_into().unwrap()), 77);
            assert_eq!(u32::from_le_bytes(payload[8..12].try_into().unwrap()), 3);
            assert_eq!(u32::from_le_bytes(payload[12..16].try_into().unwrap()), 3);
            assert_eq!(
                u32::from_le_bytes(payload[16..20].try_into().unwrap()),
                COMPACT_STATUS_EXTRACTION_PERF_GATE
            );

            // GER row @ 20.
            let g = 20;
            assert_eq!(u32::from_le_bytes(payload[g..g + 4].try_into().unwrap()), 1);
            assert_eq!(
                u32::from_le_bytes(payload[g + 4..g + 8].try_into().unwrap()),
                42_900_001
            );
            assert_eq!(
                u32::from_le_bytes(payload[g + 8..g + 12].try_into().unwrap()),
                COMPACT_DELAYED_EVENT_FLAG_DUE_REMAINING_HOURS
            );
            assert_eq!(
                u32::from_le_bytes(payload[g + 12..g + 16].try_into().unwrap()),
                0
            );
            assert_eq!(
                u32::from_le_bytes(payload[g + 16..g + 20].try_into().unwrap()),
                62
            );

            // ITA row @ 40.
            let it = 20 + COMPACT_DELAYED_EVENT_ROW_LEN;
            assert_eq!(
                u32::from_le_bytes(payload[it..it + 4].try_into().unwrap()),
                2
            );
            assert_eq!(
                u32::from_le_bytes(payload[it + 4..it + 8].try_into().unwrap()),
                6_700_000
            );
            assert_eq!(
                u32::from_le_bytes(payload[it + 16..it + 20].try_into().unwrap()),
                2966
            );

            // Absent row @ 60: flags 0, originator/due zero-packed.
            let a = 20 + 2 * COMPACT_DELAYED_EVENT_ROW_LEN;
            assert_eq!(
                u32::from_le_bytes(payload[a + 8..a + 12].try_into().unwrap()),
                0
            );
            assert_eq!(
                u32::from_le_bytes(payload[a + 12..a + 16].try_into().unwrap()),
                0
            );
            assert_eq!(
                u32::from_le_bytes(payload[a + 16..a + 20].try_into().unwrap()),
                0
            );
        }

        #[test]
        fn compact_special_project_programs_payload_packs_melt_anchored_rows() {
            // Melt-anchored (D04 oracle, independently re-derived from
            // 00_d04_1944_melted.txt):
            //   GER id21 line 956215: province 11366, unread 5 (owner tag 1).
            //   USA id6  line 2650544: province 6707,  unread 5 (owner tag 68).
            //   JAP id16 line 2259429: province 7169,  unread 2 (owner tag 72).
            let ger = CompactSpecialProjectProgramRow {
                owner_tag_db_id: 1,
                program_id: 21,
                province: 11366,
                unread_prototype_rewards: 5,
            };
            let usa = CompactSpecialProjectProgramRow {
                owner_tag_db_id: 68,
                program_id: 6,
                province: 6707,
                unread_prototype_rewards: 5,
            };
            let jap = CompactSpecialProjectProgramRow {
                owner_tag_db_id: 72,
                program_id: 16,
                province: 7169,
                unread_prototype_rewards: 2,
            };

            // dropped_ambiguous = 5 mirrors the D04 alias gap (SWE/CHL/IRQ
            // facilities shared with ROM/BUL/HUN/BRA are dropped fail-closed).
            let payload = compact_special_project_programs_data_payload(
                &[ger, usa, jap],
                5,
                88,
                COMPACT_STATUS_PARTIAL_DATA,
            );

            assert_eq!(
                payload.len(),
                24 + 3 * COMPACT_SPECIAL_PROJECT_PROGRAM_ROW_LEN
            );
            assert_eq!(u64::from_le_bytes(payload[0..8].try_into().unwrap()), 88);
            assert_eq!(u32::from_le_bytes(payload[8..12].try_into().unwrap()), 3);
            assert_eq!(u32::from_le_bytes(payload[12..16].try_into().unwrap()), 3);
            assert_eq!(
                u32::from_le_bytes(payload[16..20].try_into().unwrap()),
                COMPACT_STATUS_PARTIAL_DATA
            );
            assert_eq!(u32::from_le_bytes(payload[20..24].try_into().unwrap()), 5);

            // GER id21 row @ 24.
            let g = 24;
            assert_eq!(u32::from_le_bytes(payload[g..g + 4].try_into().unwrap()), 1);
            assert_eq!(
                u32::from_le_bytes(payload[g + 4..g + 8].try_into().unwrap()),
                21
            );
            assert_eq!(
                u32::from_le_bytes(payload[g + 8..g + 12].try_into().unwrap()),
                11366
            );
            assert_eq!(
                u32::from_le_bytes(payload[g + 12..g + 16].try_into().unwrap()),
                5
            );

            // JAP id16 row @ 24 + 2*16.
            let j = 24 + 2 * COMPACT_SPECIAL_PROJECT_PROGRAM_ROW_LEN;
            assert_eq!(
                u32::from_le_bytes(payload[j..j + 4].try_into().unwrap()),
                72
            );
            assert_eq!(
                u32::from_le_bytes(payload[j + 4..j + 8].try_into().unwrap()),
                16
            );
            assert_eq!(
                u32::from_le_bytes(payload[j + 8..j + 12].try_into().unwrap()),
                7169
            );
            assert_eq!(
                u32::from_le_bytes(payload[j + 12..j + 16].try_into().unwrap()),
                2
            );
        }

        #[test]
        fn special_project_program_fields_use_one_stable_coherent_window() {
            use compact_contract::build_profile as bp;

            let mut program = AlignedBytes::<SPECIAL_PROJECT_PROGRAM_SNAPSHOT_LEN>::new();
            let program_vtable = HEAP_LO;
            program.write_u64(0, program_vtable as u64);
            program.write_u32(bp::DOMAIN65_PROGRAM_ID_OFF, 21);
            program.write_u32(bp::DOMAIN65_PROGRAM_OWNER_PRIMARY_OFF, 1);
            program.write_u32(bp::DOMAIN65_PROGRAM_OWNER_OFF, 1);
            program.write_u32(bp::DOMAIN65_PROGRAM_PROVINCE_PRIMARY_OFF, 11_366);
            program.write_u32(bp::DOMAIN65_PROGRAM_PROVINCE_OFF, 11_366);
            program.write_u32(bp::DOMAIN65_PROGRAM_UNREAD_REWARDS_OFF, 5);

            let row = read_special_project_program_fields(program.addr(), program_vtable)
            .expect("stable coherent d65 CProgram window");
            assert_eq!(row.owner_tag_db_id, 1);
            assert_eq!(row.program_id, 21);
            assert_eq!(row.province, 11_366);
            assert_eq!(row.unread_prototype_rewards, 5);

            program.write_u32(bp::DOMAIN65_PROGRAM_ID_OFF, 0);
            assert!(read_special_project_program_fields(program.addr(), program_vtable).is_none());

            program.write_u32(bp::DOMAIN65_PROGRAM_ID_OFF, 21);
            assert!(
                read_special_project_program_fields(
                    program.addr(),
                    program_vtable + 8,
                )
                .is_none(),
                "the vtable must belong to the same admitted coherent window"
            );

            let first = read_bytes(program.addr(), SPECIAL_PROJECT_PROGRAM_SNAPSHOT_LEN).unwrap();
            let mut second = first.clone();
            second[bp::DOMAIN65_PROGRAM_PROVINCE_OFF] ^= 1;
            assert!(decode_special_project_program_snapshots(
                &first,
                &second,
                program_vtable,
            )
            .is_none());

            program.write_u32(bp::DOMAIN65_PROGRAM_OWNER_OFF, 2);
            let owner_mismatch =
                read_special_project_program_fields_detailed(program.addr(), program_vtable)
            .expect_err("duplicated owner fields must agree");
            assert_eq!(
                owner_mismatch.reason,
                CompactSpecialProjectProgramFailureReason::ProgramOwnerCopiesMismatch
            );

            program.write_u32(bp::DOMAIN65_PROGRAM_OWNER_PRIMARY_OFF, 2);
            let non_roster_owner =
                read_special_project_program_fields_detailed(program.addr(), program_vtable)
                    .expect("a valid intrinsic owner is decoded before current-roster filtering");
            assert_eq!(non_roster_owner.owner_tag_db_id, 2);
            program.write_u32(
                bp::DOMAIN65_PROGRAM_OWNER_PRIMARY_OFF,
                compact_contract::build_profile::MAX_COMPACT_OWNER_TAG_DB_ID + 1,
            );
            program.write_u32(
                bp::DOMAIN65_PROGRAM_OWNER_OFF,
                compact_contract::build_profile::MAX_COMPACT_OWNER_TAG_DB_ID + 1,
            );
            let out_of_range =
                read_special_project_program_fields_detailed(program.addr(), program_vtable)
                    .expect_err("intrinsic owner must be a valid compact tag handle");
            assert_eq!(
                out_of_range.reason,
                CompactSpecialProjectProgramFailureReason::ProgramOwnerOutOfRange
            );
        }

        #[test]
        fn special_project_program_vector_header_requires_equal_coherent_copies() {
            let mut first = Vec::new();
            first.extend_from_slice(&(HEAP_LO as u64 + 0x2000).to_le_bytes());
            first.extend_from_slice(&((4u64 << 32) | 3).to_le_bytes());
            let second = first.clone();
            assert_eq!(
                decode_special_project_program_vector_headers(&first, &second),
                Some((HEAP_LO + 0x2000, (4u64 << 32) | 3))
            );

            let mut changed = second;
            changed[8] ^= 1;
            assert!(decode_special_project_program_vector_headers(&first, &changed).is_none());
        }

