        #[test]
        fn special_project_program_repeated_pointer_conflict_is_poisoned() {
            let element = HEAP_LO + 0x2000;
            let original = CompactSpecialProjectProgramRow {
                owner_tag_db_id: 1,
                program_id: 21,
                province: 11_366,
                unread_prototype_rewards: 5,
            };
            let changed = CompactSpecialProjectProgramRow {
                province: 11_367,
                ..original
            };
            let mut candidates = BTreeMap::new();
            let mut poisoned = BTreeSet::new();

            assert!(insert_special_project_program_candidate(
                &mut candidates,
                &mut poisoned,
                element,
                original,
                1,
            ));
            assert!(insert_special_project_program_candidate(
                &mut candidates,
                &mut poisoned,
                element,
                original,
                2,
            ));
            assert_eq!(candidates[&element].1.len(), 2);
            assert!(!insert_special_project_program_candidate(
                &mut candidates,
                &mut poisoned,
                element,
                changed,
                2,
            ));
            assert!(!candidates.contains_key(&element));
            assert!(poisoned.contains(&element));
            assert!(!insert_special_project_program_candidate(
                &mut candidates,
                &mut poisoned,
                element,
                original,
                1,
            ));
        }

