        #[test]
        fn compact_occupation_state_extras_per_field_completeness_combines_atomically() {
            let first_failure = CompactOccupationExtrasFailure::new(
                CompactOccupationExtrasFailureKind::WrongVtable,
                CompactOccupationExtrasFailureField::OccupationStatus,
                HEAP_LO + 0x100,
                47,
            );
            let later_failure = CompactOccupationExtrasFailure::new(
                CompactOccupationExtrasFailureKind::InvalidStateId,
                CompactOccupationExtrasFailureField::GarrisonState,
                HEAP_LO + 0x200,
                1,
            );
            assert_eq!(
                CompactOccupationExtrasWalk::MeasuredEmpty
                    .combine(CompactOccupationExtrasWalk::Measured),
                CompactOccupationExtrasWalk::Measured
            );
            assert_eq!(
                CompactOccupationExtrasWalk::Measured
                    .combine(CompactOccupationExtrasWalk::MeasuredEmpty),
                CompactOccupationExtrasWalk::Measured
            );
            assert_eq!(
                CompactOccupationExtrasWalk::Measured
                    .combine(CompactOccupationExtrasWalk::Poisoned(first_failure)),
                CompactOccupationExtrasWalk::Poisoned(first_failure)
            );
            assert_eq!(
                CompactOccupationExtrasWalk::Poisoned(first_failure)
                    .combine(CompactOccupationExtrasWalk::Poisoned(later_failure)),
                CompactOccupationExtrasWalk::Poisoned(first_failure),
                "the first poisoned edge is retained for deterministic attribution"
            );

            // One measured field plus one measured-empty field is a complete
            // row, not a partial frame.
            let mut merged = BTreeMap::new();
            merged.insert(
                (47, 180, 891),
                CompactOccupationStateExtrasRow {
                    controller_tag_db_id: 47,
                    occupied_tag_db_id: 180,
                    state_id: 891,
                    occupation_law_token_id: Some(304_778_569),
                    garrison_manpower_source_tag_db_id: None,
                },
            );
            let read = finish_compact_occupation_state_extras_read(
                merged,
                CompactOccupationExtrasWalk::MeasuredEmpty
                    .combine(CompactOccupationExtrasWalk::Measured),
                19,
                0,
            );
            assert_eq!(read.rows.len(), 1);
            assert_eq!(read.observed_rows, 1);
            assert_eq!(read.status_flags & COMPACT_STATUS_SOURCE_UNAVAILABLE, 0);
            assert_eq!(read.status_flags & COMPACT_STATUS_PARTIAL_DATA, 0);
        }

