        #[test]
        fn compact_occupation_state_extras_null_manpower_source_is_measured_absent() {
            use compact_contract::build_profile as bp;

            let mut occupation_data = AlignedBytes::<0x100>::new();
            let mut garrison_container =
                AlignedBytes::<{ bp::DOMAIN66_GARRISON_CONTAINER_SCAN_LEN }>::new();
            let mut garrison = AlignedBytes::<{ bp::DOMAIN66_STATE_GARRISON_READ_LEN }>::new();
            let mut state = AlignedBytes::<0x80>::new();
            let garrison_vtable = HEAP_LO + 0x400;
            let state_vtable = HEAP_LO + 0x500;

            occupation_data.write_u64(
                bp::DOMAIN66_OCCUPATION_DATA_GARRISON_LIST_CONTAINER_OFF,
                garrison_container.addr() as u64,
            );
            garrison_container.write_u64(0, garrison.addr() as u64);
            garrison.write_u64(0, garrison_vtable as u64);
            garrison.write_u64(
                bp::DOMAIN66_STATE_GARRISON_DATA_STATE_OFF,
                state.addr() as u64,
            );
            garrison.write_u64(
                bp::DOMAIN66_STATE_GARRISON_DATA_OCCUPATION_DATA_OFF,
                occupation_data.addr() as u64,
            );
            // Stable null is the authenticated absence witness for this
            // independently presence-flagged field.
            garrison.write_u64(bp::DOMAIN66_STATE_GARRISON_DATA_MANPOWER_POOL_OFF, 0);
            state.write_u64(0, state_vtable as u64);
            state.write_u32(bp::DOMAIN66_STATE_ID_OFF, 891);

            let mut merged = BTreeMap::new();
            let mut conflicts = BTreeSet::new();
            assert_eq!(
                read_occupation_garrison_source_into(
                    occupation_data.addr(),
                    garrison_vtable,
                    state_vtable,
                    47,
                    180,
                    &mut merged,
                    &mut conflicts,
                ),
                CompactOccupationExtrasWalk::MeasuredEmpty
            );
            assert!(merged.is_empty());

            // The bounded qword scan can encounter coherent foreign garrison
            // objects. Their readable mismatched back-ref filters them before
            // any field is interpreted, matching the independently validated
            // D52 traversal semantics.
            garrison.write_u64(
                bp::DOMAIN66_STATE_GARRISON_DATA_OCCUPATION_DATA_OFF,
                (occupation_data.addr() + 8) as u64,
            );
            garrison.write_u64(
                bp::DOMAIN66_STATE_GARRISON_DATA_MANPOWER_POOL_OFF,
                1,
            );
            assert_eq!(
                read_occupation_garrison_source_into(
                    occupation_data.addr(),
                    garrison_vtable,
                    state_vtable,
                    47,
                    180,
                    &mut merged,
                    &mut conflicts,
                ),
                CompactOccupationExtrasWalk::MeasuredEmpty
            );

            // A non-null but invalid source pointer on an object owned by this
            // record remains a poisoned atomic snapshot; only the exact null
            // optional case and authenticated foreign candidates are admitted.
            garrison.write_u64(
                bp::DOMAIN66_STATE_GARRISON_DATA_OCCUPATION_DATA_OFF,
                occupation_data.addr() as u64,
            );
            let poisoned = read_occupation_garrison_source_into(
                occupation_data.addr(),
                garrison_vtable,
                state_vtable,
                47,
                180,
                &mut merged,
                &mut conflicts,
            );
            assert!(matches!(
                poisoned,
                CompactOccupationExtrasWalk::Poisoned(CompactOccupationExtrasFailure {
                    kind: CompactOccupationExtrasFailureKind::InvalidPointer,
                    field: CompactOccupationExtrasFailureField::GarrisonManpowerSource,
                    address: 1,
                    country_tag_db_id: 47,
                })
            ));
            assert!(merged.is_empty());
        }

