        #[test]
        fn fnv1a32_occupation_matches_committed_law_tokens() {
            // The d66 law token must equal the committed d52 default_law FNV
            // scheme byte-for-byte (independently recomputed here from the melt
            // token strings).
            assert_eq!(
                fnv1a32_occupation("local_police_force_garrison"),
                304_778_569
            );
            assert_eq!(
                fnv1a32_occupation("military_governor_occupation"),
                1_626_184_329
            );
            // 0-hash sentinel maps to 1 (never a fabricated absent-token 0).
            assert_ne!(fnv1a32_occupation("no_garrison"), 0);
        }

        #[test]
        fn compact_occupation_state_extras_payload_packs_melt_anchored_rows() {
            // Melt-anchored (D04 oracle 00_d04_1944_melted.txt, independently
            // re-derived):
            //   POR controls ANG state 891: occupation_law
            //     local_police_force_garrison (FNV 304778569), garrison
            //     manpower_pool tag=POR (line 1861550/1861556).
            //   POR controls ANG state 540: same law + tag=POR.
            //   GER controls SOV state 218: occupation_law
            //     military_governor_occupation (FNV 1626184329), garrison
            //     manpower_pool tag=GER value=3298 (line 1083781/1083810).
            //   A law-only row (state 999, garrison absent) proves the presence
            //     bits pack independently.
            // Synthetic tag_db_ids: POR=47, ANG=180, GER=1, SOV=3 (identity join
            // is by tag; the melt-anchored data are the FNV tokens + source==
            // controller relationship).
            let ang891 = CompactOccupationStateExtrasRow {
                controller_tag_db_id: 47,
                occupied_tag_db_id: 180,
                state_id: 891,
                occupation_law_token_id: Some(304_778_569),
                garrison_manpower_source_tag_db_id: Some(47),
            };
            let ang540 = CompactOccupationStateExtrasRow {
                controller_tag_db_id: 47,
                occupied_tag_db_id: 180,
                state_id: 540,
                occupation_law_token_id: Some(304_778_569),
                garrison_manpower_source_tag_db_id: Some(47),
            };
            let sov218 = CompactOccupationStateExtrasRow {
                controller_tag_db_id: 1,
                occupied_tag_db_id: 3,
                state_id: 218,
                occupation_law_token_id: Some(1_626_184_329),
                garrison_manpower_source_tag_db_id: Some(1),
            };
            let law_only = CompactOccupationStateExtrasRow {
                controller_tag_db_id: 1,
                occupied_tag_db_id: 3,
                state_id: 999,
                occupation_law_token_id: Some(1_626_184_329),
                garrison_manpower_source_tag_db_id: None,
            };

            let payload = compact_occupation_state_extras_data_payload(
                &[ang540, ang891, sov218, law_only],
                55,
                COMPACT_STATUS_EXTRACTION_PERF_GATE,
            );

            assert_eq!(
                payload.len(),
                20 + 4 * COMPACT_OCCUPATION_STATE_EXTRAS_ROW_LEN
            );
            assert_eq!(u64::from_le_bytes(payload[0..8].try_into().unwrap()), 55);
            assert_eq!(u32::from_le_bytes(payload[8..12].try_into().unwrap()), 4);
            assert_eq!(u32::from_le_bytes(payload[12..16].try_into().unwrap()), 4);

            // Row 0 (ANG 540): full row.
            let r = 20;
            assert_eq!(
                u32::from_le_bytes(payload[r..r + 4].try_into().unwrap()),
                47
            );
            assert_eq!(
                u32::from_le_bytes(payload[r + 4..r + 8].try_into().unwrap()),
                180
            );
            assert_eq!(
                u32::from_le_bytes(payload[r + 8..r + 12].try_into().unwrap()),
                540
            );
            assert_eq!(
                u32::from_le_bytes(payload[r + 12..r + 16].try_into().unwrap()),
                COMPACT_OCCUPATION_EXTRAS_FLAG_LAW | COMPACT_OCCUPATION_EXTRAS_FLAG_GARRISON_SOURCE
            );
            assert_eq!(
                u32::from_le_bytes(payload[r + 16..r + 20].try_into().unwrap()),
                304_778_569
            );
            assert_eq!(
                u32::from_le_bytes(payload[r + 20..r + 24].try_into().unwrap()),
                47
            );

            // Row 2 (SOV 218): military_governor law + GER source.
            let s = 20 + 2 * COMPACT_OCCUPATION_STATE_EXTRAS_ROW_LEN;
            assert_eq!(
                u32::from_le_bytes(payload[s + 8..s + 12].try_into().unwrap()),
                218
            );
            assert_eq!(
                u32::from_le_bytes(payload[s + 16..s + 20].try_into().unwrap()),
                1_626_184_329
            );
            assert_eq!(
                u32::from_le_bytes(payload[s + 20..s + 24].try_into().unwrap()),
                1
            );

            // Row 3 (law-only): garrison source absent -> flag clear, slot 0.
            let l = 20 + 3 * COMPACT_OCCUPATION_STATE_EXTRAS_ROW_LEN;
            assert_eq!(
                u32::from_le_bytes(payload[l + 12..l + 16].try_into().unwrap()),
                COMPACT_OCCUPATION_EXTRAS_FLAG_LAW
            );
            assert_eq!(
                u32::from_le_bytes(payload[l + 20..l + 24].try_into().unwrap()),
                0
            );
        }

