        #[test]
        fn x4_deployment_native_owner_authenticates_complete_empty_and_backlink() {
            let module_base = HEAP_LO;
            let mut country = AlignedBytes::<0x1300>::new();
            let mut manager = AlignedBytes::<0x128>::new();
            country.write_u64(0, (module_base + COUNTRY_VTABLE_RVA) as u64);
            country.write_u32(OBJ_TAG_DB_ID, 47);
            country.write_u64(COUNTRY_DEPLOYMENT_MANAGER, manager.addr() as u64);
            manager.write_u64(0, (module_base + DEPLOYMENT_MANAGER_VTABLE_RVA) as u64);
            manager.write_u64(DEPLOYMENT_MANAGER_OWNER, country.addr() as u64);

            let observed = read_deployment_country(country.addr(), 47, module_base)
                .expect("authenticated complete-empty deployment vector");
            assert!(observed.queue_complete);
            assert!(observed.conveyors.is_empty());

            manager.write_u64(DEPLOYMENT_MANAGER_OWNER, manager.addr() as u64);
            assert!(read_deployment_country(country.addr(), 47, module_base).is_none());
        }

        #[test]
        fn x4_deployment_pdq1_is_final_self_sized_and_bijective_with_d11_rows() {
            let module_base = HEAP_LO;
            let mut country = AlignedBytes::<0x1300>::new();
            let mut manager = AlignedBytes::<0x128>::new();
            country.write_u64(0, (module_base + COUNTRY_VTABLE_RVA) as u64);
            country.write_u32(OBJ_TAG_DB_ID, 47);
            country.write_u64(COUNTRY_DEPLOYMENT_MANAGER, manager.addr() as u64);
            manager.write_u64(0, (module_base + DEPLOYMENT_MANAGER_VTABLE_RVA) as u64);
            manager.write_u64(DEPLOYMENT_MANAGER_OWNER, country.addr() as u64);

            let mut admitted = test_country_row("POR", 47, country.addr());
            admitted.production = Some(CountryProductionRow {
                stockpile: None,
                military_lines: None,
                naval_lines: None,
                construction_queue: None,
                licenses: None,
            });
            let excluded = test_country_row("GER", 1, country.addr());
            let payload = compact_production_data_payload(&[admitted, excluded], 91, 0x20);
            let start = payload
                .windows(4)
                .rposition(|window| window == COMPACT_PRODUCTION_DEPLOYMENT_TRAILER_MAGIC)
                .expect("PDQ1 trailer");
            assert_eq!(
                u16::from_le_bytes(payload[start + 4..start + 6].try_into().unwrap()),
                1
            );
            assert_eq!(
                u16::from_le_bytes(payload[start + 6..start + 8].try_into().unwrap()),
                20
            );
            assert_eq!(
                u32::from_le_bytes(payload[start + 8..start + 12].try_into().unwrap()) as usize,
                payload.len() - start
            );
            let inner_len =
                u32::from_le_bytes(payload[start + 12..start + 16].try_into().unwrap()) as usize;
            assert_eq!(inner_len + 20, payload.len() - start);
            assert_eq!(
                u32::from_le_bytes(payload[start + 16..start + 20].try_into().unwrap()),
                0
            );
            let frame = country_economy_production_stockpile_live_lane::
                decode_deployment_queue_frame(&payload[start + 20..])
                .expect("strict v2 deployment frame");
            assert_eq!(frame.elapsed_wall_ms, 91);
            assert_eq!(frame.changed_country_rows, 1);
            assert_eq!(frame.status_flags, 0x20);
            assert_eq!(frame.countries.len(), 1);
            assert_eq!(frame.countries[0].tag_db_id, 47);
            assert!(frame.countries[0].queue_complete);
            assert!(frame.countries[0].conveyors.is_empty());
        }

