            assert_eq!(u32::from_le_bytes(payload[military + 4..military + 8].try_into().unwrap()), 1);
            assert_eq!(i32::from_le_bytes(payload[military + 8..military + 12].try_into().unwrap()), 1669);
            assert_eq!(i64::from_le_bytes(payload[military + 12..military + 20].try_into().unwrap()), 7_500_000);
