        #[test]
        fn x4_p4_helper_abi_requires_returned_out_pointer_and_nonnegative_results() {
            unsafe extern "system" fn current(_: usize, out: *mut i64) -> *mut i64 {
                unsafe { *out = 7_500_000 };
                out
            }
            unsafe extern "system" fn cap(_: usize, out: *mut i64) -> *mut i64 {
                unsafe { *out = 10_000_000 };
                out
            }
            unsafe extern "system" fn growth(
                _: usize,
                out: *mut i64,
                detail: *mut std::ffi::c_void,
            ) -> *mut i64 {
                assert!(detail.is_null());
                unsafe { *out = 125_000 };
                out
            }
            unsafe extern "system" fn negative_growth(
                _: usize,
                out: *mut i64,
                _: *mut std::ffi::c_void,
            ) -> *mut i64 {
                unsafe { *out = -1 };
                out
            }

            let helpers = ProductionEfficiencyHelpers {
                current,
                cap,
                growth,
            };
            assert_eq!(
                unsafe { helpers.read(1) },
                Some(ProductionEfficiencyValues {
                    efficiency_raw: 7_500_000,
                    efficiency_cap_raw: 10_000_000,
                    efficiency_growth_raw: 125_000,
                })
            );
            assert_eq!(
                unsafe {
                    ProductionEfficiencyHelpers {
                        current,
                        cap,
                        growth: negative_growth,
                    }
                    .read(1)
                },
                None
            );
        }

        #[test]
        fn x4_production_line_vector_rejects_invalid_or_duplicate_members_as_a_whole() {
            let module_base = 0x1_4000_0000usize;
            let variant_vtable = module_base + VARIANT_VTABLE_RVA;
            let mut manager = AlignedBytes::<0x200>::new();
            let mut pointer_rows = AlignedBytes::<0x10>::new();
            let mut line = AlignedBytes::<0x100>::new();
            let mut variant = AlignedBytes::<0x30>::new();

            variant.write_u64(0, variant_vtable as u64);
            variant.write_u32(VARIANT_DEF_TYPE, VARIANT_TYPE);
            variant.write_u32(VARIANT_DEF_ID, 7316);
            line.write_u64(0, (module_base + MILITARY_PRODUCTION_LINE_VTABLE_RVA) as u64);
            line.write_u32(LINE_TYPE, LINE_TYPE_MILITARY);
            line.write_i32(LINE_ID, 349);
            line.write_i32(LINE_ACTIVE_FACTORIES, 3);
            line.write_i32(LINE_COST, 10_500_000);
            line.write_i32(LINE_SPEED, 3_105_000);
            line.write_i32(LINE_PRODUCED, 3_440_000);
            line.write_i32(LINE_PRIORITY, 0);
            line.write_i32(LINE_AMOUNT, -1);
            line.write_u64(LINE_EQUIPMENT_VARIANT, variant.addr() as u64);
            line.write_u64(LINE_INDUSTRIAL_MANUFACTURER_CID, 0);
            line.write_i32(LINE_REQUESTED_FACTORIES, 5);

            pointer_rows.write_u64(0, line.addr() as u64);
            pointer_rows.write_u64(8, 0);
            manager.write_u64(LINE_BEGIN, pointer_rows.addr() as u64);
            manager.write_u32(LINE_CAP, 2);
            manager.write_u32(LINE_SIZE, 2);
            assert!(read_production_lines(manager.addr(), variant_vtable, module_base).is_none());

            pointer_rows.write_u64(8, line.addr() as u64);
            assert!(read_production_lines(manager.addr(), variant_vtable, module_base).is_none());

            manager.write_u32(LINE_SIZE, 1);
            let (military, naval) = read_production_lines(
                manager.addr(),
                variant_vtable,
                module_base,
            )
            .expect("one complete stable line");
            assert_eq!(military.len(), 1);
            assert!(naval.is_empty());
            assert_eq!(military[0].id, 349);
            assert_eq!(military[0].efficiency, None);
        }

        #[test]
        fn x4_p5_decodes_a729_line_mio_cid_type_id_order_and_null() {
            assert_eq!(decode_production_line_mio_cid(0), Some(None));
            let assigned = ((33u64) << 32) | INDUSTRIAL_ORGANISATION_CID_TYPE as u64;
            assert_eq!(decode_production_line_mio_cid(assigned), Some(Some(33)));
            assert_eq!(
                decode_production_line_mio_cid((33u64) << 32),
                None,
                "nonzero id with zero type is invalid, not null"
            );
            assert_eq!(
                decode_production_line_mio_cid((33u64 << 32) | 70),
                None,
                "a variant CID must never masquerade as an industrial organisation"
            );
        }

