        fn domain54_order_with_path_header(begin: usize, size: u32) -> Box<AlignedBytes<256>> {
            let mut order = AlignedBytes::<256>::new();
            order.write_u64(battleplans54::ORDER_OFF_PATH_BEGIN as usize, begin as u64);
            order.write_u32(battleplans54::ORDER_OFF_PATH_SIZE as usize, size);
            order
        }

        fn domain54_exact_order_container(
            module_base: usize,
            army_id: u32,
            vtable_rva: usize,
        ) -> Box<AlignedBytes<0x220>> {
            let mut group = AlignedBytes::<0x220>::new();
            group.write_u64(0, (module_base + vtable_rva) as u64);
            group.write_u64(ARMY_OFF_HANDLE, ((army_id as u64) << 32) | u64::from(ARMY_TYPE));
            group
        }

        fn domain54_exact_group(module_base: usize, army_id: u32) -> Box<AlignedBytes<0x220>> {
            domain54_exact_order_container(module_base, army_id, ARMY_VTABLE_RVA)
        }

        fn domain54_exact_order(
            module_base: usize,
            group: usize,
            instance_id: u32,
        ) -> Box<AlignedBytes<0x260>> {
            let mut order = AlignedBytes::<0x260>::new();
            order.write_u64(0, (module_base + ORDER_VTABLE_RVA) as u64);
            order.write_u32(ORDER_OFF_TYPE, 99);
            order.write_u64(ORDER_OFF_ARMY_BACKREF, group as u64);
            order.write_u32(ORDER_OFF_INSTANCE_ID, instance_id);
            order.write_u32(ORDER_OFF_ASSIGNED_UNITS_SIZE, 0);
            order.write_u32(ORDER_OFF_CHILD_ORDERS_COUNT, 0);
            order.write_u32(ORDER_OFF_ACTIVE, 1);
            order
        }

