            let army_order = domain54_exact_order(module_base, army.addr(), 2_050);
            let group_order = domain54_exact_order(module_base, army_group.addr(), 2_051);
            let mut army_primary = AlignedBytes::<8>::new();
            let mut group_primary = AlignedBytes::<8>::new();
            army_primary.write_u64(0, army_order.addr() as u64);
            group_primary.write_u64(0, group_order.addr() as u64);
            army.write_u64(ARMY_OFF_ORDERS_VEC, army_primary.addr() as u64);
