        #[test]
        fn army_order_root_census_retries_whole_authenticated_sample() {
            let mut calls = 0u32;
            let (result, attempts, error_code) =
                read_complete_army_order_roots_with_retry(|| {
                    calls = calls.saturating_add(1);
                    if calls < 3 {
                        Err(
                            battleplans54::orders_group_live::OrdersGroupReadError::UnstableTable,
                        )
                    } else {
                        Ok(
                            battleplans54::orders_group_live::CompleteArmyOrdersGroupRoots::default(
                            ),
                        )
                    }
                });

            assert!(result.is_ok());
            assert_eq!(attempts, 3);
            assert_eq!(error_code, 3);
        }

        #[test]
        fn army_order_root_census_stays_fail_closed_after_retry_bound() {
            let mut calls = 0u32;
            let (result, attempts, error_code) =
                read_complete_army_order_roots_with_retry(|| {
                    calls = calls.saturating_add(1);
                    Err(
                        battleplans54::orders_group_live::OrdersGroupReadError::UnstableTable,
                    )
                });

            assert_eq!(calls, MAX_ARMY_ORDER_ROOT_CENSUS_ATTEMPTS);
            assert_eq!(attempts, MAX_ARMY_ORDER_ROOT_CENSUS_ATTEMPTS);
            assert_eq!(error_code, 3);
            assert_eq!(
                result,
                Err(battleplans54::orders_group_live::OrdersGroupReadError::UnstableTable)
            );
        }

