        fn assert_domain54_rowless_failure(
            read: &CompactArmyBattleplansDepthRead,
            required_flag: u32,
        ) {
            let decoded = battleplans54::decode_depth_payload(0, &read.payload);
            assert_eq!(decoded.parse_errors, Vec::<String>::new());
            assert_eq!(decoded.totals.rows, 0);
            assert_eq!(read.emitted_rows, 0);
            assert_ne!(read.status_flags & COMPACT_STATUS_PARTIAL_DATA, 0);
            assert_ne!(read.status_flags & required_flag, 0);
            assert!(compact_contract::compact_status_is_failure(
                read.status_flags
            ));
        }

