        #[test]
        fn compact_oob_command_partial_updates_known_key_without_tracker_mutation() {
            let mut tracker = CompactOobCommandTracker::default();
            let row = CompactOobCommandRow {
                kind: COMPACT_OOB_KIND_ARMY,
                object_id: 17,
                deleted: false,
                parent_id: Some(301),
                owner_tag_db_id: Some(47),
                member_ids: Some(vec![101]),
                member_count: 1,
                member_count_engine: Some(1),
                missing_member_count: Some(0),
                location_province_id: None,
                leader_id: Some(9001),
                leader_skill: Some(4),
                leader_trait_count: Some(3),
                parent_status: "exact",
                member_status: "exact",
                owner_status: "exact",
                leader_status: "exact",
                leader_trait_status: "exact",
            };
            let mut member_change = row.clone();
            member_change.member_ids = Some(vec![101, 102]);
            member_change.member_count = 2;
            member_change.member_count_engine = Some(2);
            let mut attribute_change = row.clone();
            attribute_change.leader_skill = Some(5);

            let (rows, _, _) =
                compact_oob_command_delta_rows(&mut tracker, vec![row.clone()], false);
            assert_eq!(rows.len(), 1);
            assert_eq!(
                tracker.previous[&(row.kind, row.object_id)]
                    .member_ids
                    .as_deref(),
                Some(&[101][..])
            );

            // A member-link change on a partial frame could imply identities whose own
            // rows were deferred: the whole update defers until a clean sample.
            let (rows, changed_rows, deleted_rows) =
                compact_oob_command_delta_rows(&mut tracker, vec![member_change.clone()], true);
            assert!(rows.is_empty(), "{rows:?}");
            assert_eq!(changed_rows, 0);
            assert_eq!(deleted_rows, 0);
            assert_eq!(
                tracker.previous[&(row.kind, row.object_id)]
                    .member_ids
                    .as_deref(),
                Some(&[101][..])
            );

            // Attribute-only changes over baseline-proven links still flow on partial frames.
            let (rows, changed_rows, deleted_rows) =
                compact_oob_command_delta_rows(&mut tracker, vec![attribute_change], true);
            assert_eq!(rows.len(), 1);
            assert!(!rows[0].deleted);
            assert_eq!(rows[0].leader_skill, Some(5));
            assert_eq!(rows[0].member_ids.as_deref(), Some(&[101][..]));
            assert_eq!(changed_rows, 1);
            assert_eq!(deleted_rows, 0);
            assert_eq!(
                tracker.previous[&(row.kind, row.object_id)].leader_skill,
                Some(4)
            );

            // The next clean sample applies the deferred member change normally.
            let (rows, changed_rows, deleted_rows) =
                compact_oob_command_delta_rows(&mut tracker, vec![member_change], false);
            assert_eq!(rows.len(), 1);
            assert_eq!(rows[0].member_ids.as_deref(), Some(&[101, 102][..]));
            assert_eq!(changed_rows, 1);
            assert_eq!(deleted_rows, 0);
            assert_eq!(
                tracker.previous[&(row.kind, row.object_id)]
                    .member_ids
                    .as_deref(),
                Some(&[101, 102][..])
            );
        }

