        #[test]
        fn compact_air_strength_seed_emits_wing_scalar_baseline_rows() {
            let mut tracker = CompactAirStrengthDeltaTracker::default();
            let samples = vec![
                air_strength_sample(HEAP_LO + 0x100, 4, 100, 3, 42_000),
                air_strength_sample(HEAP_LO + 0x200, 5, 50, 0, 12_500),
            ];
            let (rows, changed, loss, reinforcement, deleted, mismatch) =
                compact_air_strength_delta_rows(&mut tracker, samples.clone(), 0);
            assert_eq!(changed, 2);
            assert_eq!((loss, reinforcement, deleted, mismatch), (0, 0, 0, 0));
            assert!(rows.iter().all(|row| row.baseline && !row.deleted));
            assert_eq!(rows[0].air_accidents, 3);
            assert_eq!(rows[0].experience_raw, 42_000);
            assert_eq!(rows[0].count_delta, 0);
            assert_eq!(rows[0].old_count, rows[0].new_count);

            // Unchanged second frame: nothing re-emits.
            let (rows, changed, ..) = compact_air_strength_delta_rows(&mut tracker, samples, 0);
            assert!(rows.is_empty());
            assert_eq!(changed, 0);
        }

        #[test]
        fn compact_air_strength_scalar_only_change_emits_scalar_change_row() {
            let mut tracker = CompactAirStrengthDeltaTracker::default();
            let first = vec![air_strength_sample(HEAP_LO + 0x100, 4, 100, 3, 42_000)];
            let _ = compact_air_strength_delta_rows(&mut tracker, first, 0);

            // Same count/equipment; only the cumulative scalars moved.
            let second = vec![air_strength_sample(HEAP_LO + 0x100, 4, 100, 4, 42_500)];
            let (rows, changed, loss, reinforcement, deleted, _mismatch) =
                compact_air_strength_delta_rows(&mut tracker, second, 0);
            assert_eq!(changed, 1);
            assert_eq!((loss, reinforcement, deleted), (0, 0, 0));
            let row = &rows[0];
            assert!(row.scalar_change);
            assert!(!row.baseline && !row.deleted);
            assert_eq!(row.count_delta, 0);
            assert_eq!(row.air_accidents, 4);
            assert_eq!(row.experience_raw, 42_500);
        }

        #[test]
        fn compact_air_strength_deleted_row_carries_last_known_scalars() {
            let mut tracker = CompactAirStrengthDeltaTracker::default();
            let first = vec![air_strength_sample(HEAP_LO + 0x100, 4, 100, 7, 99_000)];
            let _ = compact_air_strength_delta_rows(&mut tracker, first, 0);
            let (rows, changed, _loss, _reinforcement, deleted, _mismatch) =
                compact_air_strength_delta_rows(&mut tracker, Vec::new(), 0);
            assert_eq!(changed, 1);
            assert_eq!(deleted, 1);
            let row = &rows[0];
            assert!(row.deleted && !row.baseline && !row.scalar_change);
            assert_eq!(row.air_accidents, 7);
            assert_eq!(row.experience_raw, 99_000);
        }

        #[test]
        fn compact_air_strength_payload_carries_wing_scalars_and_baseline_flags() {
            let mut tracker = CompactAirStrengthDeltaTracker::default();
            let samples = vec![air_strength_sample(HEAP_LO + 0x100, 4, 100, 3, 42_000)];
            let (rows, changed, loss, reinforcement, deleted, _mismatch) =
                compact_air_strength_delta_rows(&mut tracker, samples, 0);
            let payload = compact_air_strength_deltas_data_payload(
                &rows,
                &[],
                10,
                COMPACT_STATUS_DELTA_DATA,
                changed,
                1,
                1,
                loss,
                reinforcement,
                deleted,
                0,
                2,
                3,
                1,
                CompactAirStrengthInvalidReason::ExperienceRange as u16,
            );
            assert_eq!(
                payload.len(),
                48 + COMPACT_AIR_STRENGTH_DELTA_ROW_LEN * rows.len()
                    + COMPACT_AIR_REGION_STATS_TRAILER_HEADER_LEN
            );
            let flags = u32::from_le_bytes(payload[48 + 16..48 + 20].try_into().unwrap());
            assert_ne!(flags & COMPACT_AIR_STRENGTH_DELTA_ROW_FLAG_WING_SCALARS, 0);
            assert_ne!(
                flags & COMPACT_AIR_STRENGTH_DELTA_ROW_FLAG_STATE_BASELINE,
                0
            );
            let air_accidents = u32::from_le_bytes(payload[48 + 68..48 + 72].try_into().unwrap());
            let experience_raw = i32::from_le_bytes(payload[48 + 72..48 + 76].try_into().unwrap());
            assert_eq!(air_accidents, 3);
            assert_eq!(experience_raw, 42_000);
            let trailer = 48 + COMPACT_AIR_STRENGTH_DELTA_ROW_LEN * rows.len();
            assert_eq!(
                u16::from_le_bytes(payload[trailer + 4..trailer + 6].try_into().unwrap()),
                COMPACT_AIR_REGION_STATS_TRAILER_VERSION
            );
            assert_eq!(
                u32::from_le_bytes(payload[trailer + 20..trailer + 24].try_into().unwrap()),
                2
            );
            assert_eq!(
                u32::from_le_bytes(payload[trailer + 24..trailer + 28].try_into().unwrap()),
                3
            );
            assert_eq!(
                u32::from_le_bytes(payload[trailer + 28..trailer + 32].try_into().unwrap()),
                (1 << 16) | CompactAirStrengthInvalidReason::ExperienceRange as u32
            );
        }

