        #[test]
        fn d91_stable_zero_parent_vector_is_authenticated_clean_empty() {
            const GAME_STATE_RAID_SYSTEM: usize = 0x3F0;
            const RAID_SYSTEM_VTABLE_RVA: usize = 0x295B3E8;
            const PARENT_BEGIN: usize = 0xD8;
            const PARENT_CAPACITY: usize = 0xE0;
            const PARENT_COUNT: usize = 0xE4;

            let mut game_state = AlignedBytes::<0x400>::new();
            let mut raid_system = AlignedBytes::<0xE8>::new();
            let module_base = raid_system
                .addr()
                .checked_sub(RAID_SYSTEM_VTABLE_RVA)
                .expect("test allocation address exceeds D91 raid-system vtable RVA");
            game_state.write_u64(GAME_STATE_RAID_SYSTEM, raid_system.addr() as u64);
            raid_system.write_u64(
                0,
                module_base.checked_add(RAID_SYSTEM_VTABLE_RVA).unwrap() as u64,
            );
            raid_system.write_u64(PARENT_BEGIN, 0);
            raid_system.write_u32(PARENT_CAPACITY, 0);
            raid_system.write_u32(PARENT_COUNT, 0);

            let mut state = empty_collector_state();
            state.base = module_base;
            state.date_ptr = game_state.addr() as u64;
            page_cache_new_frame();

            let (parents, children) =
                read_exact_raid_instances_rows(&state).expect("stable empty D91 census");
            assert!(parents.is_empty());
            assert!(children.is_empty());

            let game_hour_raw = compact_contract::calendar::DATE_EPOCH_CONST
                + (1936 * 365 * 24);
            let read = read_compact_raid_instances(
                &state,
                game_hour_raw,
                7,
                COMPACT_STATUS_EXTRACTION_PERF_GATE,
            );
            assert_eq!(
                read.status_flags,
                COMPACT_STATUS_EXTRACTION_PERF_GATE,
                "the informational production perf marker must not suppress D91"
            );
            assert_eq!(read.observed_parents, 0);
            assert_eq!(read.observed_children, 0);
            let decoded = compact_contract::raid_instances::decode_payload(&read.payload)
                .expect("clean-empty RID1 payload");
            assert_eq!(
                decoded.status_flags,
                COMPACT_STATUS_EXTRACTION_PERF_GATE
            );
            assert!(decoded.parents.is_empty());
            assert!(decoded.children.is_empty());

            // Empty admission does not relax a nonzero population or a
            // malformed empty-vector pointer into a clean frame.
            raid_system.write_u32(PARENT_COUNT, 1);
            page_cache_new_frame();
            assert!(read_exact_raid_instances_rows(&state).is_err());
            raid_system.write_u32(PARENT_COUNT, 0);
            raid_system.write_u64(PARENT_BEGIN, usize::MAX as u64);
            page_cache_new_frame();
            assert!(read_exact_raid_instances_rows(&state).is_err());
        }

