        #[test]
        fn d81_current_production_marks_v1_hub_unavailability_as_domain_failure() {
            let province = RailProvinceState {
                province_id: 1,
                active_terminal: false,
                anchor_variant: 0,
                anchor_bits: [0.0f32.to_bits(), 1.0f32.to_bits(), 2.0f32.to_bits()],
                neighbors: Vec::new(),
            };
            let mut unavailable = CompactRailReplayRead {
                provinces: vec![province.clone()],
                hub_frames: None,
                observed_neighbors: 0,
                read_time_us: 1,
                status_flags: 0,
                first_failure: None,
            };
            let payload = encode_compact_rail_replay_production(&mut unavailable, 10);
            let decoded = rail_replay::decode_payload(&payload).unwrap();
            assert_eq!(decoded.payload_version, rail_replay::PAYLOAD_VERSION_V1);
            assert_ne!(
                decoded.status_flags & COMPACT_STATUS_SOURCE_UNAVAILABLE,
                0
            );
            assert_ne!(decoded.status_flags & COMPACT_STATUS_PARTIAL_DATA, 0);
            assert!(!decoded.hub_frames_complete);

            let mut measured_empty = CompactRailReplayRead {
                provinces: vec![province],
                hub_frames: Some(Vec::new()),
                observed_neighbors: 0,
                read_time_us: 1,
                status_flags: 0,
                first_failure: None,
            };
            let payload = encode_compact_rail_replay_production(&mut measured_empty, 10);
            let decoded = rail_replay::decode_payload(&payload).unwrap();
            assert_eq!(decoded.payload_version, rail_replay::PAYLOAD_VERSION_V2);
            assert_eq!(decoded.status_flags, 0);
            assert!(decoded.hub_frames_complete);
            assert!(decoded.hub_frames.is_empty());
        }

