        #[test]
        fn domain47_refresh_failure_retains_adopted_roots_fail_closed() {
            let mut state = empty_collector_state();
            // Type roots unresolvable -> the refresh attempt hits the hold
            // path (same shape as a torn/cold-snapshot refresh failure).
            state.base = usize::MAX;
            let mut cache = domain47_adopted_root_cache();

            let held = prewarm_compact_characters_leaders_cabinet_roots(&state, &mut cache);
            assert!(held.ran);
            assert!(held.refresh);
            assert!(held.refresh_held_roots);
            assert!(
                cache.roots.has_stable_roots(),
                "a transient refresh failure must NEVER downgrade adopted roots to empty"
            );
            assert_eq!(held.stable_root_count, 1);
            assert_eq!(cache.sweep_gen, Some(u64::MAX));
            assert_eq!(
                cache.negative_prewarm_frames_remaining,
                DOMAIN47_NEGATIVE_PREWARM_RESCAN_FRAMES
            );

            // Backoff frames drain while the adopted roots keep serving, still
            // CLEAN (first hold is a tolerated transient).
            let backoff = prewarm_compact_characters_leaders_cabinet_roots(&state, &mut cache);
            assert!(backoff.negative_cache_hit);
            assert!(backoff.refresh);
            assert_eq!(backoff.stable_root_count, 1);
            assert!(cache.roots.has_stable_roots());
            assert_eq!(
                cache.roots.skipped_root_rows, 0,
                "one hold must not poison the retained roots"
            );

            // Drain the rest of the backoff window (the explicit backoff call
            // above already consumed one frame); the retry then fails again
            // (type roots still unresolvable) -> SECOND consecutive hold ->
            // the retained roots are POISONED so the scheduled reader
            // fail-closes frames as rowless PARTIAL (bounded staleness; O3
            // gate HIGH). Roots themselves are still retained for recovery.
            for _ in 0..DOMAIN47_NEGATIVE_PREWARM_RESCAN_FRAMES - 1 {
                let drained = prewarm_compact_characters_leaders_cabinet_roots(&state, &mut cache);
                assert!(drained.negative_cache_hit);
            }
            let second_hold = prewarm_compact_characters_leaders_cabinet_roots(&state, &mut cache);
            assert!(second_hold.ran);
            assert!(second_hold.refresh_held_roots);
            assert_eq!(cache.refresh_hold_streak, 2);
            assert!(cache.roots.has_stable_roots());
            assert_ne!(
                cache.roots.skipped_root_rows, 0,
                "a persistent hold must surface as the reader's fail-closed marker"
            );
            // The scheduled reader converts the poisoned marker into a rowless
            // fail-closed PARTIAL frame (never a CLEAN emit from a knowingly
            // stale root view).
            let read = read_compact_characters_leaders_cabinet_live(
                &state,
                0,
                &cache.roots,
                second_hold,
            );
            assert_ne!(read.frame.status_flags & COMPACT_STATUS_PARTIAL_DATA, 0);
            assert_eq!(read.frame.row_count, 0);
        }

        #[test]
        fn domain47_rejection_invalidation_gate_fires_only_on_stale_root_signature() {
            // Parse errors on a cached-roots frame (prewarm early-returned):
            // the stale-root signature -> invalidate.
            assert!(domain47_should_invalidate_roots_on_frame(3, false, false));
            // An INVALIDATION-triggered rebuild already ran THIS frame and it
            // still parse-errors: not staleness; re-invalidating would rebuild
            // every frame.
            assert!(!domain47_should_invalidate_roots_on_frame(3, true, false));
            // A generation-triggered/cold rebuild frame passes
            // `invalidation_rebuild_ran == false` at the call site — parse
            // errors there (a character died in the prewarm-to-read window)
            // invalidate PROMPTLY (O3 gate MEDIUM: one death = one rowless
            // frame, not two). Same predicate arm as the first case.
            // Backoff-window frames drain untouched.
            assert!(!domain47_should_invalidate_roots_on_frame(3, false, true));
            // Clean frames never invalidate.
            assert!(!domain47_should_invalidate_roots_on_frame(0, false, false));
        }

        #[test]
        fn domain47_adapter_output_rows_covers_every_output_family() {
            // Fix-round re-gate finding 3 regression: an advisor-roster-only
            // (or appointed-advisor-only / portrait-only) built frame MUST
            // count as adapter output, so its discard trips the per-frame
            // work-without-emission gate — the original five-family sum let
            // exactly these frames vanish silently once one earlier frame's
            // row masked the whole-run aggregate.
            let base = domain47::adapter::AdapterBuildStats::default();
            assert_eq!(domain47_adapter_output_rows(&base), 0);
            for build in [
                |s: &mut domain47::adapter::AdapterBuildStats| s.character_rows = 1,
                |s: &mut domain47::adapter::AdapterBuildStats| s.unit_leader_rows = 1,
                |s: &mut domain47::adapter::AdapterBuildStats| s.unit_leader_trait_rows = 1,
                |s: &mut domain47::adapter::AdapterBuildStats| s.country_leader_role_rows = 1,
                |s: &mut domain47::adapter::AdapterBuildStats| s.active_ruler_rows = 1,
                |s: &mut domain47::adapter::AdapterBuildStats| s.advisor_roster_rows = 1,
                |s: &mut domain47::adapter::AdapterBuildStats| s.appointed_advisor_rows = 1,
                |s: &mut domain47::adapter::AdapterBuildStats| s.portrait_rows = 1,
            ] {
                let mut stats = domain47::adapter::AdapterBuildStats::default();
                build(&mut stats);
                assert_eq!(
                    domain47_adapter_output_rows(&stats),
                    1,
                    "an output-row family is missing from the sum"
                );
            }
            // Non-output work/rejection counters must NOT count as rows.
            let noise = domain47::adapter::AdapterBuildStats {
                character_roots_seen: 5,
                unit_leader_roots_seen: 5,
                country_leader_roots_seen: 5,
                country_roots_seen: 5,
                advisor_roots_seen: 5,
                portrait_inputs_seen: 5,
                active_ruler_unresolved_roots: 5,
                rejected_roots: 5,
                missing_trait_tokens: 5,
                dead_roots: 5,
                ..domain47::adapter::AdapterBuildStats::default()
            };
            assert_eq!(domain47_adapter_output_rows(&noise), 0);
        }

        #[test]
        fn domain47_manager_identity_set_requires_exact_unique_index_parity() {
            let exact = [(11u32, 0x1100usize), (22u32, 0x2200usize)];
            let lookup = |char_id| match char_id {
                11 => Some(0x1100),
                22 => Some(0x2200),
                _ => None,
            };
            assert!(domain47_manager_identity_set_is_exact(&exact, 2, lookup));
            assert!(!domain47_manager_identity_set_is_exact(&exact, 1, lookup));
            assert!(!domain47_manager_identity_set_is_exact(
                &[(11, 0x1100), (11, 0x2200)],
                2,
                lookup,
            ));
            assert!(!domain47_manager_identity_set_is_exact(
                &[(11, 0x1100), (22, 0x1100)],
                2,
                lookup,
            ));
            assert!(!domain47_manager_identity_set_is_exact(
                &exact,
                2,
                |char_id| match char_id {
                    11 => Some(0x1100),
                    22 => Some(0x3300),
                    _ => None,
                },
            ));
        }

