        /// Blocker-1 acceptance test 1 (Codex tid 019f5387): a large valid
        /// character world with ONE country-conflicting char_id adopts roots
        /// (skipped_root_rows stays 0, adoption not blocked), counts the
        /// ambiguity, and quarantines the conflicting identity so it emits
        /// under NEITHER country — instead of the pre-fix behavior where the
        /// persistent conflict re-failed the whole prewarm forever (d47 = 0
        /// rows for the whole session).
        #[test]
        fn domain47_dedup_quarantines_country_conflict_without_gating_adoption() {
            // Integration-style: drive the REAL admit loop shape (push on
            // Insert, skip on Merge/Ambiguous) into a real root vector, then
            // run the production filter — review 019f53fb MINOR: bookkeeping-
            // only assertions would pass even if the caller never removed the
            // quarantined root.
            let mut dedup = Domain47CharacterDedup::default();
            let mut characters: Vec<domain47::adapter::CharacterRoot> = Vec::new();
            let root = |addr: u64| domain47::adapter::CharacterRoot {
                character_addr: addr,
                name: None,
                token: None,
            };
            // Hit sequence: (char_id, country, leader_ptr). Char 1234 carries
            // a leader ptr and later duplicates under a DIFFERENT country.
            let hits: &[(u32, u32, u64)] = &[
                (1, 10, 0),
                (2, 11, 0),
                (1234, 10, 0x9000),
                (3, 11, 0),
                (1234, 30, 0), // country conflict -> quarantine id 1234
                (1234, 10, 0), // further duplicate stays out
                (4, 12, 0),
                (5, 40, 0x9000), // BLOCKER regression (019f53fb): the
                                 // quarantined root's ptr must be
                                 // TOMBSTONED — this claim must NOT
                                 // re-insert a mapping (else the leader
                                 // row emits under whichever country
                                 // scanned last).
            ];
            for &(char_id, country, ptr) in hits {
                match dedup.admit_character(char_id, country, ptr, characters.len()) {
                    Domain47CharacterAdmit::Insert => {
                        dedup.admit_leader(ptr, country);
                        characters.push(root(u64::from(char_id) * 0x10));
                    }
                    Domain47CharacterAdmit::Merge(_) | Domain47CharacterAdmit::Ambiguous { .. } => {
                    }
                }
            }
            // Kept mapping existed until the conflict, then dropped + poisoned.
            assert!(!dedup.leader_country_by_ptr.contains_key(&0x9000));
            assert!(dedup.ambiguous_leader_ptrs.contains(&0x9000));
            // conflict (2) + repeat duplicate (1) + poisoned re-claim (1).
            assert_eq!(dedup.ambiguous_root_rows, 4);
            domain47_filter_quarantined_roots(&mut characters, &dedup.quarantined_indices());
            // Survivors: every unambiguous character, quarantined 1234 GONE
            // (emits under NEITHER country), and char_ids are unique — the
            // payload gate rejects any frame carrying a duplicate char_id.
            let addrs: Vec<u64> = characters.iter().map(|c| c.character_addr).collect();
            assert_eq!(addrs, vec![0x10, 0x20, 0x30, 0x40, 0x50]);
            // The adoption gate takes torn reads + root count ONLY: the
            // ambiguity does not block adopting the surviving roots.
            assert!(!domain47_prewarm_adoption_blocked(0, characters.len()));
        }

        /// Blocker-1 acceptance test 2: two DIFFERENT characters claiming one
        /// unit-leader pointer across countries keep BOTH character roots;
        /// only the leader mapping is dropped (no first-inserted winner), and
        /// a third claim cannot re-insert it.
        #[test]
        fn domain47_dedup_drops_cross_country_leader_mapping_keeps_both_roots() {
            let mut dedup = Domain47CharacterDedup::default();
            assert!(matches!(
                dedup.admit_character(1, 10, 0x5000, 0),
                Domain47CharacterAdmit::Insert
            ));
            dedup.admit_leader(0x5000, 10);
            assert_eq!(dedup.leader_country_by_ptr.get(&0x5000), Some(&10));
            assert!(matches!(
                dedup.admit_character(2, 20, 0x5000, 1),
                Domain47CharacterAdmit::Insert
            ));
            dedup.admit_leader(0x5000, 20);
            // Mapping dropped, pointer poisoned, both roots kept, none
            // quarantined (the ambiguity is the ASSOCIATION, not the chars).
            assert!(dedup.leader_country_by_ptr.is_empty());
            assert!(dedup.ambiguous_leader_ptrs.contains(&0x5000));
            assert_eq!(dedup.ambiguous_root_rows, 2);
            assert_eq!(dedup.kept.len(), 2);
            assert!(dedup.quarantined_indices().is_empty());
            // A third claim finds the poisoned pointer and stays out.
            assert!(matches!(
                dedup.admit_character(3, 10, 0x5000, 2),
                Domain47CharacterAdmit::Insert
            ));
            dedup.admit_leader(0x5000, 10);
            assert!(dedup.leader_country_by_ptr.is_empty());
            assert_eq!(dedup.ambiguous_root_rows, 3);
            // Same-country duplicates still merge (dedup unchanged for the
            // unambiguous case).
            assert!(matches!(
                dedup.admit_character(1, 10, 0x5000, 3),
                Domain47CharacterAdmit::Merge(0)
            ));
        }

        /// Blocker-1 acceptance tests 3+4: the whole-prewarm fail-closed gate
        /// is UNCHANGED for its two legitimate inputs — genuinely torn
        /// double-reads still refuse adoption (rootless retry window ->
        /// SOURCE/PARTIAL rowless), and a zero-character world still fails
        /// closed.
        #[test]
        fn domain47_torn_reads_and_zero_roots_still_block_adoption() {
            assert!(domain47_prewarm_adoption_blocked(1, 4000));
            assert!(domain47_prewarm_adoption_blocked(0, 0));
            assert!(domain47_prewarm_adoption_blocked(3, 0));
            assert!(!domain47_prewarm_adoption_blocked(0, 1));
        }

