        #[test]
        fn domain51_shared_timed_effect_policy_accepts_modifier_but_not_unknown_rtti() {
            let event_vtable = 0xDE10;
            assert_eq!(
                domain51_timed_effect_kind_from_rtti(
                    ".?AVCDelayedEvent@@",
                    event_vtable,
                    event_vtable,
                ),
                Some(Domain51TimedEffectKind::DelayedEvent)
            );
            assert_eq!(
                domain51_timed_effect_kind_from_rtti(".?AVCModifier@@", 0xC0DE, event_vtable,),
                Some(Domain51TimedEffectKind::Modifier)
            );
            assert_eq!(
                domain51_timed_effect_kind_from_rtti(
                    ".?AVCUnclassifiedTimedEffect@@",
                    0xBAD0,
                    event_vtable,
                ),
                None,
                "unknown shared-container members must keep bit 12 unresolved"
            );
            assert_eq!(
                domain51_timed_effect_kind_from_rtti(
                    ".?AVCDelayedEvent@@",
                    event_vtable + 8,
                    event_vtable,
                ),
                None,
                "a shifted event vtable is profile uncertainty"
            );
        }

