        #[test]
        fn compact_division_root_census_preserves_missing_and_duplicate_candidates() {
            let first = DivisionBodyBridgeEntry {
                div_id: 17,
                body_ptr: HEAP_LO + 0x1000,
                owner_tag_db_id: 1,
            };
            let duplicate_id = DivisionBodyBridgeEntry {
                div_id: 17,
                body_ptr: HEAP_LO + 0x2000,
                owner_tag_db_id: 2,
            };
            let duplicate = compact_division_root_cache_from_observations(
                2,
                true,
                vec![first, duplicate_id],
            );
            assert_eq!(duplicate.observed_candidate_rows, 2);
            assert_eq!(duplicate.rows.len(), 1);
            assert!(!duplicate.complete, "deduplication must poison the roster");

            let missing =
                compact_division_root_cache_from_observations(2, true, vec![first]);
            assert_eq!(missing.observed_candidate_rows, 2);
            assert_eq!(missing.rows.len(), 1);
            assert!(
                !missing.complete,
                "a filtered/missing wrapper candidate must poison the roster"
            );
        }

