        fn state_resource_entries_scalar_for_test(
            state_ptr: usize,
        ) -> Option<Vec<CompactStateResourceEntry>> {
            if !is_map_control_heap_pointer(state_ptr) {
                return None;
            }
            let state_def = read_u64(state_ptr.checked_add(STATE_OFF_DEF)?)? as usize;
            if !is_map_control_heap_pointer(state_def) {
                return None;
            }
            let header = read_bytes(state_def.checked_add(STATE_DEF_OFF_RESOURCES_PTR)?, 16)?;
            let data = read_u64_from_slice(&header, 0)? as usize;
            let size = read_u32_from_slice(
                &header,
                STATE_DEF_OFF_RESOURCES_SIZE - STATE_DEF_OFF_RESOURCES_PTR,
            )?;
            let cap = read_u32_from_slice(
                &header,
                STATE_DEF_OFF_RESOURCES_CAP - STATE_DEF_OFF_RESOURCES_PTR,
            )?;
            if size == 0 {
                return Some(Vec::new());
            }
            let logical_rows = state_resource_logical_rows(size, cap)?;
            if logical_rows == 0 {
                return Some(Vec::new());
            }
            if !is_map_control_heap_pointer(data) {
                return None;
            }
            let byte_len = (logical_rows as usize).checked_mul(STATE_RESOURCE_STRIDE)?;
            let rows = read_bytes(data, byte_len)?;
            if rows.len() != byte_len {
                return None;
            }
            state_resource_entries_from_rows(logical_rows, logical_rows, &rows)
        }

        fn d23_resource_fixture() -> (
            Box<AlignedBytes<MAP_STATE_DEF_WINDOW_LEN>>,
            Box<AlignedBytes<{ STATE_DEF_OFF_RESOURCES_CAP + 4 }>>,
            Box<AlignedBytes<{ 3 * STATE_RESOURCE_STRIDE }>>,
        ) {
            let mut state = AlignedBytes::<MAP_STATE_DEF_WINDOW_LEN>::new();
            let mut state_def = AlignedBytes::<{ STATE_DEF_OFF_RESOURCES_CAP + 4 }>::new();
            let mut rows = AlignedBytes::<{ 3 * STATE_RESOURCE_STRIDE }>::new();

            rows.write_i32(0, 700_000);
            rows.write_u32(8, 0x3E03);
            rows.write_i32(STATE_RESOURCE_STRIDE, 25_000);
            rows.write_u32(STATE_RESOURCE_STRIDE + 8, STATE_RESOURCE_NO_ID);
            rows.write_i32(2 * STATE_RESOURCE_STRIDE, 900_000);
            rows.write_u32(2 * STATE_RESOURCE_STRIDE + 8, 0x4E37);

            state_def.write_u64(STATE_DEF_OFF_RESOURCES_PTR, rows.addr() as u64);
            state_def.write_u32(STATE_DEF_OFF_RESOURCES_SIZE, 3);
            state_def.write_u32(STATE_DEF_OFF_RESOURCES_CAP, 3);
            state.write_u64(STATE_OFF_DEF, state_def.addr() as u64);

            assert!(is_map_control_heap_pointer(state.addr()));
            assert!(is_map_control_heap_pointer(state_def.addr()));
            assert!(is_map_control_heap_pointer(rows.addr()));

            (state, state_def, rows)
        }

