        #[test]
        fn compact_frd_depth_payload_packs_decision_country_targets() {
            let read = CompactFrdDepthRead {
                focus_events: Vec::new(),
                research_eta: Vec::new(),
                decision_status: vec![CompactFrdDecisionStatusRow {
                    tag_db_id: 47,
                    active_timed_count: 0,
                    targeted_count: 0,
                    targeted_timed_count: 1,
                    decisions_taken_bucket_count: 0,
                    re_enable_count: 0,
                    timed_live_count: 0,
                }],
                decision_events: Vec::new(),
                decision_targets: vec![CompactFrdDecisionTargetRow {
                    tag_db_id: 47,
                    target_id: 12,
                    flags: COMPACT_FRD_DECISION_TARGET_COUNTRY_FLAGS,
                    source_kind: COMPACT_FRD_DECISION_TARGET_SOURCE_ACTIVE_TARGETED_TIMED,
                    lifecycle_state: 0,
                    ignore: false,
                    days: 44,
                    decision: Some("POR_targeted_mission".to_string()),
                }],
                decision_target_omitted_rows: 0,
                targeted_timed_structural_failure: false,
                targeted_failure_reason_mask: 0,
                targeted_timed_failure_reason_mask: 0,
                cooldown_source_missing_rows: 0,
                badges: Vec::new(),
                direct_transitions: Vec::new(),
                direct_batch: None,
                direct_hook_source_validated: false,
                read_time_us: 0,
                changed_rows: 2,
                status_flags: COMPACT_STATUS_DELTA_DATA | COMPACT_STATUS_PARTIAL_DATA,
                depth_status_flags: COMPACT_FRD_STATUS_KNOWN_MASK,
                observed_focus_rows: 0,
                observed_research_slot_rows: 0,
                observed_decision_rows: 1,
                observed_timed_decision_rows: 0,
            };

            let payload = compact_frd_depth_data_payload(&read, 115);

            assert_eq!(&payload[0..4], b"FRD2");
            assert_eq!(u16::from_le_bytes(payload[4..6].try_into().unwrap()), 4);
            assert_eq!(
                u16::from_le_bytes(payload[6..8].try_into().unwrap()),
                COMPACT_FRD_DEPTH_HEADER_LEN as u16
            );
            assert_eq!(
                u32::from_le_bytes(payload[8..12].try_into().unwrap()),
                COMPACT_FRD_STATUS_KNOWN_MASK
                    & !COMPACT_FRD_STATUS_DIRECT_HOOK_SOURCE_VALIDATED
            );
            assert_eq!(u32::from_le_bytes(payload[20..24].try_into().unwrap()), 1);
            assert_eq!(u32::from_le_bytes(payload[28..32].try_into().unwrap()), 1);
            assert_eq!(u32::from_le_bytes(payload[52..56].try_into().unwrap()), 0);
            assert_eq!(
                u32::from_le_bytes(payload[56..60].try_into().unwrap()),
                COMPACT_STATUS_DELTA_DATA | COMPACT_STATUS_PARTIAL_DATA
            );
            let target = COMPACT_FRD_DEPTH_HEADER_LEN + COMPACT_FRD_DECISION_STATUS_ROW_LEN;
            assert_eq!(
                u32::from_le_bytes(payload[target..target + 4].try_into().unwrap()),
                47
            );
            assert_eq!(
                u32::from_le_bytes(payload[target + 4..target + 8].try_into().unwrap()),
                12
            );
            assert_eq!(
                u32::from_le_bytes(payload[target + 8..target + 12].try_into().unwrap()),
                COMPACT_FRD_DECISION_TARGET_COUNTRY_FLAGS
            );
            assert_eq!(
                i32::from_le_bytes(payload[target + 16..target + 20].try_into().unwrap()),
                0
            );
            assert_eq!(
                u32::from_le_bytes(payload[target + 20..target + 24].try_into().unwrap()),
                0
            );
            assert_eq!(
                i32::from_le_bytes(payload[target + 24..target + 28].try_into().unwrap()),
                44
            );
            assert!(payload_contains(&payload, "POR_targeted_mission"));
        }

        #[test]
        fn compact_frd_v5_embeds_validated_pointer_free_direct_trailer() {
            use direct_frd_transitions_live::{
                DirectEventCarrier, DirectEventKind, DirectEventStateSummary,
                UnsequencedDirectEventRow,
            };

            let mut carrier = DirectEventCarrier::new();
            let owner = carrier.allocate_instance_id().unwrap();
            let subject = carrier.allocate_instance_id().unwrap();
            carrier
                .capture(UnsequencedDirectEventRow {
                    kind: DirectEventKind::ResearchCompleted,
                    thread_id: 17,
                    game_hour_raw: 200,
                    root_rva: DirectEventKind::ResearchCompleted.expected_root_rva_a729(),
                    owner_instance_id: owner,
                    subject_instance_id: subject,
                    argument_instance_id: direct_frd_transitions_live::OpaqueInstanceId::NONE,
                    owner_key: 0,
                    subject_token_hash: 0,
                    subject_key: 1,
                    input_bits: 123,
                    return_bits: 1,
                    before: DirectEventStateSummary::default(),
                    after: DirectEventStateSummary {
                        state_bits: 1 << 63,
                        ..DirectEventStateSummary::default()
                    },
                })
                .unwrap();
            let direct_transitions = carrier.drain_rows().unwrap();
            let direct_batch = direct_frd_transitions_live::DirectEventBatch {
                hook_epoch: 1,
                drain_sequence: 1,
                installed_root_mask:
                    direct_frd_transitions_live::D45_V5_DIRECT_EVENT_REQUIRED_ROOT_MASK,
                observed_kind_mask:
                    direct_frd_transitions_live::DirectEventKind::ResearchCompleted.root_mask_bit(),
                sequence_cursor: 2,
                producer_complete: true,
                evidence_fixture: false,
                rows: direct_transitions.clone(),
            };
            let mut read = CompactFrdDepthRead {
                focus_events: Vec::new(),
                research_eta: Vec::new(),
                decision_status: Vec::new(),
                decision_events: Vec::new(),
                decision_targets: Vec::new(),
                decision_target_omitted_rows: 0,
                targeted_timed_structural_failure: false,
                targeted_failure_reason_mask: 0,
                targeted_timed_failure_reason_mask: 0,
                cooldown_source_missing_rows: 0,
                badges: Vec::new(),
                direct_transitions,
                direct_batch: Some(direct_batch),
                direct_hook_source_validated: true,
                read_time_us: 0,
                changed_rows: 1,
                status_flags: COMPACT_STATUS_DELTA_DATA,
                depth_status_flags: 0,
                observed_focus_rows: 0,
                observed_research_slot_rows: 0,
                observed_decision_rows: 0,
                observed_timed_decision_rows: 0,
            };
            compact_frd_apply_required_badges(&mut read);
            let payload = compact_frd_depth_data_payload(&read, 0);
            assert_eq!(u16::from_le_bytes(payload[4..6].try_into().unwrap()), 5);
            assert_eq!(u16::from_le_bytes(payload[6..8].try_into().unwrap()), 64);
            assert_ne!(
                u32::from_le_bytes(payload[8..12].try_into().unwrap())
                    & COMPACT_FRD_STATUS_DIRECT_HOOK_SOURCE_VALIDATED,
                0
            );
            assert_eq!(u32::from_le_bytes(payload[60..64].try_into().unwrap()), 1);
            assert_eq!(
                direct_frd_transitions_live::decode_trailer(&payload[64..], 1)
                    .unwrap()
                    .len(),
                1
            );
        }

        #[test]
        fn d45_targeted_vector_bound_is_not_the_active_timer_bound() {
            // Regression: the retained 1,068-frame capture reported the
            // vector-bounds reason on every D45 frame and about 990 omitted
            // target rows per frame. Targeted vectors use the independently
            // proven CDecisionStatus list bound, not the 256-row active-timer
            // safety limit.
            assert!(d45_targeted_vector_bounds_valid(990, 1_024));
            assert!(d45_targeted_vector_bounds_valid(
                MAX_DECISION_STATUS_LIST,
                MAX_DECISION_STATUS_LIST,
            ));
            assert!(!d45_targeted_vector_bounds_valid(1_025, 1_024));
            assert!(!d45_targeted_vector_bounds_valid(
                MAX_DECISION_STATUS_LIST,
                MAX_DECISION_STATUS_LIST + 1,
            ));
        }

