        #[test]
        fn compact_supply_owner_identity_is_embedded_not_positional() {
            let mut seen = BTreeSet::new();
            // The exact-a729 active-country vector can place the portable tag
            // identity 443 at positional slot 365. The embedded identity is
            // authoritative; the slot ordinal is only the owner/supply join.
            // Tag zero remains the unique empty-owner sentinel whose decoded
            // rows are required to be empty by the caller.
            assert!(compact_supply_owner_tag_is_valid(0, &mut seen));
            assert!(!compact_supply_owner_tag_is_valid(0, &mut seen));
            assert!(compact_supply_owner_tag_is_valid(443, &mut seen));
            assert!(!compact_supply_owner_tag_is_valid(443, &mut seen));
            assert!(!compact_supply_owner_tag_is_valid(
                MAX_CGAMESTATE_COUNTRIES + 1,
                &mut seen
            ));
        }

        #[test]
        fn compact_supply_disrupted_bucket_decoder_enforces_robin_hood_body_law() {
            fn bucket(marker: u8, province_id: u32, node_type: u32, value_raw: i64) -> Vec<u8> {
                let mut out =
                    vec![0u8; CCOUNTRY_SUPPLY_SYSTEM_DISRUPTED_BUCKET_STRIDE];
                out[4] = marker;
                out[8..12].copy_from_slice(&province_id.to_le_bytes());
                out[12..16].copy_from_slice(&node_type.to_le_bytes());
                out[16..24].copy_from_slice(&value_raw.to_le_bytes());
                out
            }

            let mut valid = bucket(1, 7081, 3, 4017);
            valid.extend_from_slice(&bucket(0, 0, 0, 0));
            valid.extend_from_slice(&bucket(0, 0, 0, 0));
            let rows = compact_supply_logistics_attrition_disrupted_bucket_blob_rows(
                47, 1, 1, &valid,
            )
            .expect("valid one-row robin-hood body");
            assert_eq!(rows.len(), 1);
            assert_eq!(rows[0].entity_id, 7081);
            assert_eq!(rows[0].join_id, 3);
            assert_eq!(rows[0].owner_tag_db_id, 47);
            assert_eq!(rows[0].value_a_raw, 4017);

            let negative = bucket(1, 7081, 3, -4017);
            let rows = compact_supply_logistics_attrition_disrupted_bucket_blob_rows(
                47, 1, 1, &negative,
            )
            .expect("signed engine value fits the exact i32 wire slot");
            assert_eq!(rows[0].value_a_raw, -4017);

            let wire_max = bucket(1, 7081, 3, i64::from(i32::MAX));
            let rows = compact_supply_logistics_attrition_disrupted_bucket_blob_rows(
                47, 1, 1, &wire_max,
            )
            .expect("signed engine value at the exact wire bound");
            assert_eq!(rows[0].value_a_raw, i32::MAX);

            let above_wire = bucket(1, 7081, 3, i64::from(i32::MAX) + 1);
            assert!(
                compact_supply_logistics_attrition_disrupted_bucket_blob_rows(
                    47,
                    1,
                    1,
                    &above_wire,
                )
                .is_none()
            );

            let sentinel = bucket(u8::MAX, 7081, 3, 4017);
            assert!(
                compact_supply_logistics_attrition_disrupted_bucket_blob_rows(
                    47, 1, 1, &sentinel,
                )
                .is_none()
            );
            let beyond_max_distance = bucket(2, 7081, 3, 4017);
            assert!(
                compact_supply_logistics_attrition_disrupted_bucket_blob_rows(
                    47,
                    1,
                    1,
                    &beyond_max_distance,
                )
                .is_none()
            );
            let count_disagreement = bucket(1, 7081, 3, 4017);
            assert!(
                compact_supply_logistics_attrition_disrupted_bucket_blob_rows(
                    47,
                    2,
                    1,
                    &count_disagreement,
                )
                .is_none()
            );
            let mut duplicate = bucket(1, 7081, 3, 4017);
            duplicate.extend_from_slice(&bucket(1, 7081, 3, 4017));
            assert!(
                compact_supply_logistics_attrition_disrupted_bucket_blob_rows(
                    47, 2, 1, &duplicate,
                )
                .is_none()
            );
        }

        #[test]
        fn compact_supply_empty_disrupted_table_accepts_retained_allocation_shape() {
            let mut country_supply = AlignedBytes::<0xB0>::new();
            let retained_buckets = AlignedBytes::<0x180>::new();
            country_supply.write_u64(
                CCOUNTRY_SUPPLY_SYSTEM_DISRUPTED_BUCKETS,
                retained_buckets.addr() as u64,
            );
            country_supply.write_u32(CCOUNTRY_SUPPLY_SYSTEM_DISRUPTED_COUNT, 0);
            country_supply.write_u32(CCOUNTRY_SUPPLY_SYSTEM_DISRUPTED_MASK, 15);
            country_supply.write_u8(CCOUNTRY_SUPPLY_SYSTEM_DISRUPTED_MAX_DISTANCE, 6);
            let header_end = CCOUNTRY_SUPPLY_SYSTEM_DISRUPTED_MAX_DISTANCE + 8;
            let header = country_supply.bytes
                [CCOUNTRY_SUPPLY_SYSTEM_DISRUPTED_BUCKETS..header_end]
                .to_vec();

            let rows = compact_supply_logistics_attrition_disrupted_table_rows(
                country_supply.addr(),
                47,
                &header,
            )
            .expect("count-zero table may retain its prior allocation metadata");
            assert!(rows.is_empty());

            country_supply.write_u32(CCOUNTRY_SUPPLY_SYSTEM_DISRUPTED_MASK, 14);
            let invalid_header = country_supply.bytes
                [CCOUNTRY_SUPPLY_SYSTEM_DISRUPTED_BUCKETS..header_end]
                .to_vec();
            assert!(
                compact_supply_logistics_attrition_disrupted_table_rows(
                    country_supply.addr(),
                    47,
                    &invalid_header,
                )
                .is_none(),
                "retained allocation still requires a power-of-two bucket shape"
            );
        }

