        fn write_test_msvc_inline_string<const N: usize>(
            arena: &mut AlignedBytes<N>,
            offset: usize,
            value: &str,
        ) {
            let bytes = value.as_bytes();
            assert!(bytes.len() < 16);
            arena.write_bytes(offset, bytes);
            arena.write_u8(offset + bytes.len(), 0);
            arena.write_u64(offset + 0x10, bytes.len() as u64);
            arena.write_u64(offset + 0x18, 15);
        }

        fn write_test_msvc_heap_string<const N: usize>(
            arena: &mut AlignedBytes<N>,
            offset: usize,
            value: &str,
        ) {
            let bytes = value.as_bytes();
            let chars_offset = offset + 0x20;
            assert!(bytes.len() >= 16);
            assert!(chars_offset + bytes.len() < N);
            let chars_addr = arena.addr() + chars_offset;
            arena.write_u64(offset, chars_addr as u64);
            arena.write_u64(offset + 0x10, bytes.len() as u64);
            arena.write_u64(offset + 0x18, (N - chars_offset - 1) as u64);
            arena.write_bytes(chars_offset, bytes);
            arena.write_u8(chars_offset + bytes.len(), 0);
        }

        #[test]
        fn domain57_utf8_reader_accepts_empty_threat_reason() {
            let mut reason = AlignedBytes::<0x20>::new();
            write_test_msvc_inline_string(&mut reason, 0, "");
            assert_eq!(
                read_domain57_utf8_string(reason.addr(), DOMAIN57_MAX_WORLD_TENSION_REASON_BYTES),
                Some(String::new())
            );
        }

        #[test]
        fn domain57_threat_reason_preserves_engine_color_markers_only() {
            let mut reason = AlignedBytes::<0x80>::new();
            let value = "Guaranteeing Independence of \u{11}YKingdom of Greece\u{11}!";
            write_test_msvc_heap_string(&mut reason, 0, value);
            assert_eq!(
                read_domain57_world_tension_reason(
                    reason.addr(),
                    DOMAIN57_MAX_WORLD_TENSION_REASON_BYTES,
                ),
                Some(value.to_string())
            );

            write_test_msvc_inline_string(&mut reason, 0, "bad\u{12}control");
            assert_eq!(
                read_domain57_world_tension_reason(
                    reason.addr(),
                    DOMAIN57_MAX_WORLD_TENSION_REASON_BYTES,
                ),
                None
            );
        }

        #[test]
        fn domain57_country_slot_identity_accepts_only_pointer_joined_aliases() {
            const COUNTRY_COUNT: i32 = 440;
            const ALIAS_SLOT: u32 = 365;
            const CANONICAL_SLOT: u32 = 1;
            let mut country_table = AlignedBytes::<{ COUNTRY_COUNT as usize * 8 }>::new();
            let mut equivalence = AlignedBytes::<{ COUNTRY_COUNT as usize * 4 }>::new();
            let mut country =
                AlignedBytes::<{ compact_contract::build_profile::DOMAIN57_COUNTRY_TAG_DB_ID + 4 }>::new();

            country.write_i32(
                compact_contract::build_profile::DOMAIN57_COUNTRY_TAG_DB_ID,
                CANONICAL_SLOT as i32,
            );
            equivalence.write_u32((ALIAS_SLOT as usize) * 4, CANONICAL_SLOT);
            equivalence.write_u32((CANONICAL_SLOT as usize) * 4, CANONICAL_SLOT);
            country_table.write_u64(
                (ALIAS_SLOT as usize) * 8,
                country.addr() as u64,
            );
            country_table.write_u64(
                (CANONICAL_SLOT as usize) * 8,
                country.addr() as u64,
            );

            assert_eq!(
                domain57_country_slot_identity(
                    equivalence.addr(),
                    country_table.addr(),
                    COUNTRY_COUNT,
                    ALIAS_SLOT,
                    country.addr(),
                ),
                Some(Domain57CountrySlotIdentity::Alias(CANONICAL_SLOT))
            );
            assert_eq!(
                domain57_country_slot_identity(
                    equivalence.addr(),
                    country_table.addr(),
                    COUNTRY_COUNT,
                    CANONICAL_SLOT,
                    country.addr(),
                ),
                Some(Domain57CountrySlotIdentity::Canonical(CANONICAL_SLOT))
            );

            country_table.write_u64(
                (CANONICAL_SLOT as usize) * 8,
                country.addr().saturating_add(8) as u64,
            );
            assert_eq!(
                domain57_country_slot_identity(
                    equivalence.addr(),
                    country_table.addr(),
                    COUNTRY_COUNT,
                    ALIAS_SLOT,
                    country.addr(),
                ),
                None
            );
        }

        fn domain57_test_control_root(
            value: &serde_json::Value,
        ) -> BTreeMap<String, serde_json::Value> {
            value
                .as_object()
                .expect("test control object")
                .iter()
                .map(|(key, value)| (key.clone(), value.clone()))
                .collect()
        }

        fn current_domain57_gate_control_json(dir: &std::path::Path) -> serde_json::Value {
            let _ = fs::remove_dir_all(dir);
            fs::create_dir_all(dir).unwrap();
            let write_hashed = |name: &str, bytes: &[u8]| {
                let path = dir.join(name);
                fs::write(&path, bytes).unwrap();
                (
                    path.to_string_lossy().into_owned(),
                    format!("{:x}", Sha256::digest(bytes)),
                )
            };
            let (gate_path, gate_sha256) = write_hashed("gate.json", b"gate-v2");
            let (nonce_seal_path, nonce_seal_sha256) = write_hashed("nonce_seal.json", b"nonce-v2");
            let (verifier_path, verifier_sha256) =
                write_hashed("verify_speed5_stream.py", b"verifier-v2");

            let mut transcript = serde_json::json!({
                "schema": "battle-plan.speed_root_evidence_transcript.v2",
                "transcript_sha256": ""
            });
            let mut unhashed = transcript.clone();
            unhashed
                .as_object_mut()
                .unwrap()
                .remove("transcript_sha256");
            let transcript_sha256 = format!(
                "{:x}",
                Sha256::digest(serde_json::to_vec(&unhashed).unwrap())
            );
            transcript["transcript_sha256"] = serde_json::Value::String(transcript_sha256.clone());
            let transcript_bytes = serde_json::to_vec(&transcript).unwrap();
            let (transcript_path, transcript_file_sha256) =
                write_hashed("transcript.json", &transcript_bytes);

            serde_json::json!({
                "mode": "hourly_poll",
                "profile": "production",
                "session_id": "d57-v2-test",
                "scheduled_domains": RAW_SESSION_MULTIPLAYER_METADATA_LIVE_DOMAIN,
                "domain57_game_speed_transcript_file_sha256": transcript_file_sha256,
                "domain57_game_speed_gate_v2": {
                    "schema": DOMAIN57_GAME_SPEED_CONTROL_SCHEMA,
                    "verdict": "passed",
                    "required": true,
                    "enabled": true,
                    "gate_path": gate_path,
                    "gate_sha256": gate_sha256,
                    "transcript_path": transcript_path,
                    "transcript_sha256": transcript_sha256,
                    "transcript_file_id": {
                        "volume_serial_number": 1,
                        "file_index": 2,
                        "file_size": transcript_bytes.len()
                    },
                    "nonce_seal_path": nonce_seal_path,
                    "nonce_seal_sha256": nonce_seal_sha256,
                    "verifier_path": verifier_path,
                    "verifier_sha256": verifier_sha256,
                    "probe_tool_sha256": "1111111111111111111111111111111111111111111111111111111111111111",
                    "static_disasm_sha256": "2222222222222222222222222222222222222222222222222222222222222222",
                    "session_id": "d57-v2-test",
                    "evidence_nonce_hex": "3333333333333333333333333333333333333333333333333333333333333333",
                    "pid": unsafe { GetCurrentProcessId() },
                    "process_creation_filetime_utc": current_process_creation_filetime()
                        .expect("current process creation FILETIME"),
                    "exe_sha256": DOMAIN57_CURRENT_EXE_SHA256,
                    "module_base": format!("0x{:X}", unsafe {
                        GetModuleHandleW(ptr::null()) as usize
                    }),
                    "speed_sample_sequences": [1, 2, 3, 4, 5],
                    "pause_sample_sequences": [6, 7, 8]
                }
            })
        }

        #[test]
        fn domain57_v2_control_binds_semantic_and_raw_transcript_hashes() {
            let dir = std::env::temp_dir().join(format!(
                "hoi4_collector_d57_v2_gate_test_{}_{}",
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap()
                    .as_nanos()
            ));
            let valid = current_domain57_gate_control_json(&dir);
            let root = domain57_test_control_root(&valid);
            assert_eq!(
                parse_domain57_game_speed_gate_v2(
                    &root,
                    Some(compact_contract::CaptureProfile::Production),
                    true,
                ),
                (Domain57GameSpeedMode::ValidatedControl, true, None)
            );

            let module_path = dir.join("collector.dll");
            fs::write(
                dir.join("collector_control.json"),
                serde_json::to_vec(&valid).unwrap(),
            )
            .unwrap();
            let integrated = collector_control(&module_path).unwrap();
            assert!(integrated.domain57_game_speed_gate_valid);
            assert_eq!(
                integrated.domain57_game_speed_mode,
                Domain57GameSpeedMode::ValidatedControl
            );

            let mut wrong_process_creation = valid.clone();
            wrong_process_creation["domain57_game_speed_gate_v2"]
                ["process_creation_filetime_utc"] = serde_json::Value::from(
                current_process_creation_filetime()
                    .expect("current process creation FILETIME")
                    .saturating_add(1),
            );
            assert_eq!(
                parse_domain57_game_speed_gate_v2(
                    &domain57_test_control_root(&wrong_process_creation),
                    Some(compact_contract::CaptureProfile::Production),
                    true,
                ),
                (
                    Domain57GameSpeedMode::Disabled,
                    false,
                    Some("mismatched_domain57_game_speed_gate")
                )
            );

            let mut wrong_raw_hash = valid.clone();
            wrong_raw_hash["domain57_game_speed_transcript_file_sha256"] =
                serde_json::Value::String("0".repeat(64));
            let parsed = parse_domain57_game_speed_gate_v2(
                &domain57_test_control_root(&wrong_raw_hash),
                Some(compact_contract::CaptureProfile::Production),
                true,
            );
            assert_eq!(
                parsed,
                (
                    Domain57GameSpeedMode::Disabled,
                    false,
                    Some("mismatched_domain57_game_speed_gate")
                )
            );

            let transcript_path = valid["domain57_game_speed_gate_v2"]["transcript_path"]
                .as_str()
                .unwrap();
            let mut transcript_bytes = fs::read(transcript_path).unwrap();
            transcript_bytes.push(b'\n');
            fs::write(transcript_path, transcript_bytes).unwrap();
            let parsed = parse_domain57_game_speed_gate_v2(
                &root,
                Some(compact_contract::CaptureProfile::Production),
                true,
            );
            assert_eq!(
                parsed,
                (
                    Domain57GameSpeedMode::Disabled,
                    false,
                    Some("mismatched_domain57_game_speed_gate")
                )
            );
            let _ = fs::remove_dir_all(&dir);
        }

