        #[test]
        fn domain57_game_speed_reader_round_trips_and_fails_closed() {
            use compact_contract::build_profile::{
                DOMAIN57_CGAMESTATE_GAME_SPEED_INDEX, DOMAIN57_CGAMESTATE_SINGLETON_RVA,
                DOMAIN57_MAX_GAME_SPEED,
            };

            // The `0..=4` clamp must agree with the session57 encoder's GameSpeed
            // validation (session_multiplayer_metadata_live encode gate) so a
            // value the reader accepts can never be rejected downstream.
            assert_eq!(DOMAIN57_MAX_GAME_SPEED, 4);

            // Build a controllable singleton chain: `gs` carries the speed word at
            // +0x4BC; `slot` holds the gs pointer; choose module_base so that
            // module_base + SINGLETON_RVA lands exactly on `slot`.
            let mut gs = AlignedBytes::<{ DOMAIN57_CGAMESTATE_GAME_SPEED_INDEX + 8 }>::new();
            let mut slot = AlignedBytes::<8>::new();
            assert!(is_heap_pointer_aligned(gs.addr(), 8));
            assert!(slot.addr() > DOMAIN57_CGAMESTATE_SINGLETON_RVA);
            let module_base = slot.addr() - DOMAIN57_CGAMESTATE_SINGLETON_RVA;
            slot.write_u64(0, gs.addr() as u64);

            // Every in-range speed round-trips exactly.
            for speed in 0..=DOMAIN57_MAX_GAME_SPEED {
                gs.write_i32(DOMAIN57_CGAMESTATE_GAME_SPEED_INDEX, speed);
                assert_eq!(read_domain57_game_speed(module_base), Some(speed));
            }

            // Out-of-range words are torn/garbage -> fail closed (never coerced).
            for bad in [-1, DOMAIN57_MAX_GAME_SPEED + 1, i32::MIN, i32::MAX] {
                gs.write_i32(DOMAIN57_CGAMESTATE_GAME_SPEED_INDEX, bad);
                assert_eq!(read_domain57_game_speed(module_base), None);
            }

            // A null singleton pointer fails closed.
            gs.write_i32(DOMAIN57_CGAMESTATE_GAME_SPEED_INDEX, 3);
            slot.write_u64(0, 0);
            assert_eq!(read_domain57_game_speed(module_base), None);

            // A non-heap / misaligned singleton pointer fails closed.
            slot.write_u64(0, (gs.addr() as u64) | 0x1);
            assert_eq!(read_domain57_game_speed(module_base), None);
            slot.write_u64(0, (HEAP_LO as u64) - 8);
            assert_eq!(read_domain57_game_speed(module_base), None);

            // A zero / unmapped module base fails closed without faulting.
            assert_eq!(read_domain57_game_speed(0), None);
        }

