        #[test]
        fn domain57_x12_current_join_removes_only_authenticated_capture_barrier() {
            assert_eq!(
                domain57_x12_effective_current_pause(
                    false,
                    HOUR_LATCH_NO_PAUSE_OVERRIDE,
                ),
                Some(false)
            );
            assert_eq!(
                domain57_x12_effective_current_pause(
                    true,
                    HOUR_LATCH_NO_PAUSE_OVERRIDE,
                ),
                Some(true)
            );
            assert_eq!(
                domain57_x12_effective_current_pause(true, 0),
                Some(false),
                "running gameplay is represented by the authenticated pre-barrier override"
            );
            assert_eq!(
                domain57_x12_effective_current_pause(true, 1),
                Some(true),
                "a player-paused clock remains paused through the barrier"
            );
            assert_eq!(
                domain57_x12_effective_current_pause(false, 0),
                None,
                "an active override requires X12 to observe the real paused barrier"
            );
            assert_eq!(
                domain57_x12_effective_current_pause(false, 1),
                None,
                "a torn player-paused barrier must fail closed"
            );
            assert_eq!(
                domain57_x12_effective_current_pause(true, 3),
                None,
                "unknown override encodings must fail closed"
            );
        }

        #[test]
        fn domain57_player_and_chat_roots_decode_exact_layouts() {
            use compact_contract::build_profile as p;

            let mut game_state = AlignedBytes::<0x110>::new();
            let mut player_rows = AlignedBytes::<0x140>::new();
            let mut game_state_slot = AlignedBytes::<8>::new();
            let player_module_base = game_state_slot.addr() - p::DOMAIN57_CGAMESTATE_SINGLETON_RVA;
            game_state_slot.write_u64(0, game_state.addr() as u64);
            game_state.write_u64(
                p::DOMAIN57_CGAMESTATE_PLAYER_RECORDS,
                player_rows.addr() as u64,
            );
            game_state.write_i32(p::DOMAIN57_CGAMESTATE_PLAYER_RECORD_COUNT, 2);
            write_test_msvc_inline_string(
                &mut player_rows,
                p::DOMAIN57_PLAYER_RECORD_NAME,
                "Alice",
            );
            player_rows.write_i32(p::DOMAIN57_PLAYER_RECORD_COUNTRY_ID, 10);
            write_test_msvc_inline_string(
                &mut player_rows,
                p::DOMAIN57_PLAYER_RECORD_STRIDE + p::DOMAIN57_PLAYER_RECORD_NAME,
                "Bob",
            );
            player_rows.write_i32(
                p::DOMAIN57_PLAYER_RECORD_STRIDE + p::DOMAIN57_PLAYER_RECORD_COUNTRY_ID,
                20,
            );
            let players = read_domain57_player_snapshot(player_module_base).unwrap();
            assert_eq!(
                players.players,
                BTreeMap::from([("Alice".to_string(), 10), ("Bob".to_string(), 20)])
            );

            let mut chat = AlignedBytes::<0xC0>::new();
            let mut core = AlignedBytes::<0x98>::new();
            let mut users = AlignedBytes::<0x60>::new();
            let mut messages = AlignedBytes::<0x90>::new();
            let mut chat_slot = AlignedBytes::<8>::new();
            let chat_module_base = chat_slot.addr() - p::DOMAIN57_CCHAT_SINGLETON_RVA;
            chat_slot.write_u64(0, chat.addr() as u64);
            chat.write_u64(p::DOMAIN57_CCHAT_CORE, core.addr() as u64);
            core.write_u64(p::DOMAIN57_CCHAT_USER_ROWS, users.addr() as u64);
            core.write_i32(p::DOMAIN57_CCHAT_USER_ROWS_COUNT, 1);
            write_test_msvc_inline_string(&mut users, p::DOMAIN57_CCHAT_USER_ROW_NAME, "Alice");
            chat.write_u64(p::DOMAIN57_CCHAT_MESSAGE_ROWS, messages.addr() as u64);
            chat.write_i32(p::DOMAIN57_CCHAT_MESSAGE_ROWS_CAPACITY, 2);
            chat.write_i32(p::DOMAIN57_CCHAT_MESSAGE_ROWS_COUNT, 2);
            write_test_msvc_inline_string(
                &mut messages,
                p::DOMAIN57_CCHAT_MESSAGE_ROW_TEXT,
                "ready",
            );
            write_test_msvc_inline_string(
                &mut messages,
                p::DOMAIN57_CCHAT_MESSAGE_ROW_SENDER,
                "Alice",
            );
            write_test_msvc_inline_string(
                &mut messages,
                p::DOMAIN57_CCHAT_MESSAGE_ROW_STRIDE + p::DOMAIN57_CCHAT_MESSAGE_ROW_TEXT,
                "joined",
            );
            write_test_msvc_inline_string(
                &mut messages,
                p::DOMAIN57_CCHAT_MESSAGE_ROW_STRIDE + p::DOMAIN57_CCHAT_MESSAGE_ROW_SENDER,
                "SYSTEM",
            );
            let chat = read_domain57_chat_snapshot(chat_module_base).unwrap();
            assert_eq!(chat.user_names, BTreeSet::from(["Alice".to_string()]));
            assert_eq!(
                chat.rows,
                vec![
                    ("ready".to_string(), "Alice".to_string()),
                    ("joined".to_string(), "SYSTEM".to_string())
                ]
            );
        }

        #[test]
        fn domain57_event_tracker_baselines_then_emits_exact_deltas() {
            let mut tracker = Domain57EventTracker::default();
            let player_root = 0x1000;
            let chat_root = 0x2000;
            assert!(tracker
                .apply_player_snapshot(
                    Domain57PlayerSnapshot {
                        root: player_root,
                        players: BTreeMap::from([("Alice".to_string(), 10)]),
                    },
                    100,
                )
                .is_empty());
            assert!(tracker
                .apply_chat_snapshot(
                    Domain57ChatSnapshot {
                        root: chat_root,
                        user_names: BTreeSet::from(["Alice".to_string()]),
                        rows: vec![("old".to_string(), "Alice".to_string())],
                    },
                    100,
                )
                .is_empty());

            let mut events = tracker.apply_player_snapshot(
                Domain57PlayerSnapshot {
                    root: player_root,
                    players: BTreeMap::from([("Alice".to_string(), 11), ("Bob".to_string(), 20)]),
                },
                101,
            );
            events.extend(tracker.apply_chat_snapshot(
                Domain57ChatSnapshot {
                    root: chat_root,
                    user_names: BTreeSet::from(["Alice".to_string(), "Bob".to_string()]),
                    rows: vec![
                        ("old".to_string(), "Alice".to_string()),
                        ("ready".to_string(), "Alice".to_string()),
                        ("Bob joined".to_string(), "SYSTEM".to_string()),
                    ],
                },
                101,
            ));
            assert_eq!(events.len(), 4);
            assert!(events
                .iter()
                .any(|row| row.kind == session57::SessionEventKind::TagSwitch
                    && row.actor_name == "Alice"
                    && row.tag_db_id == 11
                    && row.related_value_i32 == 10));
            assert!(events
                .iter()
                .any(|row| row.kind == session57::SessionEventKind::Hotjoin
                    && row.actor_name == "Bob"
                    && row.value_i32 == 1));
            assert!(events
                .iter()
                .any(|row| row.kind == session57::SessionEventKind::Chat
                    && row.actor_name == "Alice"
                    && row.text == "ready"));
            assert!(events
                .iter()
                .any(|row| row.kind == session57::SessionEventKind::SystemMessage
                    && row.actor_name == "SYSTEM"
                    && row.text == "Bob joined"));
            assert!(events
                .windows(2)
                .all(|pair| pair[0].command_sequence < pair[1].command_sequence));

            let leave = tracker.apply_player_snapshot(
                Domain57PlayerSnapshot {
                    root: player_root,
                    players: BTreeMap::from([("Alice".to_string(), 11)]),
                },
                102,
            );
            assert_eq!(leave.len(), 1);
            assert_eq!(leave[0].kind, session57::SessionEventKind::Hotjoin);
            assert_eq!(leave[0].actor_name, "Bob");
            assert_eq!(leave[0].value_i32, 2);

            // Root replacement and vector truncation establish new baselines;
            // neither can replay stale/pre-capture rows as fresh events.
            assert!(tracker
                .apply_player_snapshot(
                    Domain57PlayerSnapshot {
                        root: player_root + 8,
                        players: BTreeMap::from([("Carol".to_string(), 30)]),
                    },
                    103,
                )
                .is_empty());
            assert!(tracker
                .apply_chat_snapshot(
                    Domain57ChatSnapshot {
                        root: chat_root,
                        user_names: BTreeSet::from(["Alice".to_string()]),
                        rows: Vec::new(),
                    },
                    103,
                )
                .is_empty());
        }

        #[test]
        fn politics_token_cache_address_reuse_a_b_a_never_returns_stale_token() {
            fn resolve<const N: usize>(
                arena: &mut AlignedBytes<N>,
                cache: &Mutex<BTreeMap<usize, (MsvcStringSnapshot, String)>>,
                cache_key: usize,
                value: &str,
            ) -> String {
                write_test_msvc_inline_string(arena, 0, value);
                let snapshot = read_stable_msvc_string_snapshot(arena.addr(), 32)
                    .expect("double-read-stable string snapshot");
                cached_token_from_snapshot(cache, cache_key, snapshot, 1, is_script_token)
                    .expect("valid cached script token")
            }

            let mut arena = AlignedBytes::<64>::new();
            let cache = Mutex::new(BTreeMap::new());
            let cache_key = arena.addr();

            // Same address, size, capacity, and inline character address for all
            // three observations. Exact bytes are the only changing identity.
            assert_eq!(
                resolve(&mut arena, &cache, cache_key, "alpha_token"),
                "alpha_token"
            );

            // Deterministically force the reviewed TOCTOU: read #1 observes A,
            // then the same-address object mutates to B before read #2. The
            // stable reader must fail closed, so the cache cannot store A's
            // identity with B's token.
            write_test_msvc_inline_string(&mut arena, 0, "alpha_token");
            let addr = arena.addr();
            let torn = read_stable_msvc_string_snapshot_with_between(addr, 32, || {
                write_test_msvc_inline_string(&mut arena, 0, "bravo_token");
            });
            assert!(torn.is_none());

            // A later reuse for A must resolve A, never stale B.
            write_test_msvc_inline_string(&mut arena, 0, "alpha_token");
            assert_eq!(
                resolve(&mut arena, &cache, cache_key, "alpha_token"),
                "alpha_token"
            );

            let guard = cache.lock().expect("test cache lock");
            let (identity, token) = guard.get(&cache_key).expect("cached A identity");
            assert_eq!(identity.bytes, b"alpha_token");
            assert_eq!(token, "alpha_token");
        }

