        fn payload_contains(payload: &[u8], needle: &str) -> bool {
            payload_find(payload, needle).is_some()
        }

        fn payload_find(payload: &[u8], needle: &str) -> Option<usize> {
            payload
                .windows(needle.len())
                .position(|window| window == needle.as_bytes())
        }

