        #[test]
        fn d69_paired_header_uses_count_at_24_and_bonus_count_at_3c() {
            let mut bytes = [0u8; 0x30];
            bytes[0..8].copy_from_slice(&0x1000u64.to_le_bytes());
            bytes[8..12].copy_from_slice(&9u32.to_le_bytes());
            bytes[12..16].copy_from_slice(&2u32.to_le_bytes());
            bytes[16..24].copy_from_slice(&0xaaaa_u64.to_le_bytes());
            bytes[24..32].copy_from_slice(&0x2000u64.to_le_bytes());
            bytes[32..36].copy_from_slice(&7u32.to_le_bytes());
            bytes[36..40].copy_from_slice(&2u32.to_le_bytes());
            bytes[40..48].copy_from_slice(&0xbbbb_u64.to_le_bytes());
            let header = decode_domain69_paired_header(&bytes).unwrap();
            assert_eq!(header.member_capacity, 9);
            assert_eq!(header.member_count, 2);
            assert_eq!(header.bonus_capacity, 7);
            assert_eq!(header.bonus_count, 2);
        }

        #[test]
        fn d69_paired_array_range_allows_unaligned_final_byte() {
            let mut members = AlignedBytes::<24>::new();
            let mut bonuses = AlignedBytes::<48>::new();
            for (index, value) in [1u32, 2, 3, 4, 5, 6].into_iter().enumerate() {
                members.write_u32(index * 4, value);
                bonuses.write_u64(index * 8, u64::from(value) * 100_000);
            }

            let member_bytes = read_domain69_array(members.addr(), 6, 4).unwrap();
            let bonus_bytes = read_domain69_array(bonuses.addr(), 6, 8).unwrap();
            assert_eq!(member_bytes.len(), 24);
            assert_eq!(bonus_bytes.len(), 48);
            assert_eq!(read_u32_from_slice(&member_bytes, 20), Some(6));
            assert_eq!(read_i64_from_slice(&bonus_bytes, 40), Some(600_000));
            assert!(read_domain69_array(members.addr(), 6, 3).is_none());
        }

