        #[test]
        fn collector_control_acceptance_fault_requires_exact_bound_authorization() {
            let dir = std::env::temp_dir().join(format!(
                "hoi4_collector_acceptance_fault_test_{}",
                std::process::id()
            ));
            let _ = fs::remove_dir_all(&dir);
            fs::create_dir_all(&dir).unwrap();
            let dll = dir.join("collector.dll");
            let control = dir.join("collector_control.json");
            let pipe = "acceptance-pipe-token";
            let session = "acceptance-session-1";
            let nonce = "a".repeat(64);
            let authorization =
                acceptance_test_authorization(pipe, session, "synthetic-fault", &nonce);
            let valid = serde_json::json!({
                "mode": "hourly_poll",
                "profile": "debug",
                "pipe_token": pipe,
                "session_id": session,
                "scheduled_domains": "weather_live",
                "acceptance_test_mode_v1": "synthetic-fault",
                "acceptance_test_nonce_v1": nonce,
                "acceptance_test_authorization_v1": authorization,
            });
            fs::write(&control, serde_json::to_vec(&valid).unwrap()).unwrap();
            let parsed = collector_control(&dll).unwrap();
            assert_eq!(parsed.acceptance_test_mode, Some("synthetic-fault"));
            assert!(parsed.acceptance_test_control_valid);
            assert!(control_authority_valid(&parsed));

            for (mode, expected) in [
                ("sink-open-fault", SinkAcceptanceFault::Open),
                (
                    "sink-write-fault",
                    SinkAcceptanceFault::WriteAfterFirstCommit,
                ),
            ] {
                let mut sink = valid.clone();
                sink["acceptance_test_mode_v1"] = serde_json::json!(mode);
                sink["acceptance_test_authorization_v1"] = serde_json::json!(
                    acceptance_test_authorization(pipe, session, mode, &nonce)
                );
                fs::write(&control, serde_json::to_vec(&sink).unwrap()).unwrap();
                let parsed = collector_control(&dll).unwrap();
                assert_eq!(parsed.acceptance_test_mode, Some(mode));
                assert_eq!(acceptance_sink_fault(&parsed), Some(expected));
                assert!(parsed.acceptance_test_control_valid);
            }

            let mut paused = valid.clone();
            paused["stream_format"] = serde_json::json!("compact");
            paused["scheduled_domains"] =
                serde_json::json!(RAW_SUNK_CONVOY_HISTORY_LIVE_DOMAIN);
            paused["acceptance_test_mode_v1"] = serde_json::json!("paused");
            paused["acceptance_test_authorization_v1"] = serde_json::json!(
                acceptance_test_authorization(pipe, session, "paused", &nonce)
            );
            fs::write(&control, serde_json::to_vec(&paused).unwrap()).unwrap();
            let parsed = collector_control(&dll).unwrap();
            assert_eq!(parsed.acceptance_test_mode, Some("paused"));
            assert!(parsed.acceptance_test_control_valid);
            assert!(control_authority_valid(&parsed));
            assert!(b4_production_domain_enabled(&parsed));

            let mut tampered = valid;
            tampered["acceptance_test_authorization_v1"] = serde_json::json!("b".repeat(64));
            fs::write(&control, serde_json::to_vec(&tampered).unwrap()).unwrap();
            let parsed = collector_control(&dll).unwrap();
            assert_eq!(parsed.acceptance_test_mode, None);
            assert!(!parsed.acceptance_test_control_valid);
            assert!(!control_authority_valid(&parsed));
            let _ = fs::remove_dir_all(&dir);
        }

