        #[test]
        fn collector_control_parses_prefetch_dist_overrides() {
            let dir = std::env::temp_dir().join(format!(
                "hoi4_collector_control_prefetch_test_{}",
                std::process::id()
            ));
            let _ = fs::remove_dir_all(&dir);
            fs::create_dir_all(&dir).unwrap();
            let dll = dir.join("collector.dll");
            let control = dir.join("collector_control.json");

            // Explicit values parse verbatim, including the meaningful 0
            // (prefetch OFF) — every arm of the live sweep must round-trip.
            fs::write(
                &control,
                r#"{"mode":"hourly_poll","duration_ms":8000,"sample_ms":10,"prefetch_dist_relation":8,"prefetch_dist_candidates":0}"#,
            )
            .unwrap();
            let parsed = collector_control(&dll).unwrap();
            assert_eq!(parsed.prefetch_dist_relation, Some(8));
            assert_eq!(parsed.prefetch_dist_candidates, Some(0));

            // `null` (what the Rust host writes for "no override") must parse as
            // None, exactly like an absent field — never as 0 or garbage.
            fs::write(
                &control,
                r#"{"mode":"hourly_poll","duration_ms":8000,"sample_ms":10,"prefetch_dist_relation":null,"prefetch_dist_candidates":null}"#,
            )
            .unwrap();
            let parsed = collector_control(&dll).unwrap();
            assert_eq!(parsed.prefetch_dist_relation, None);
            assert_eq!(parsed.prefetch_dist_candidates, None);

            // MALFORMED tokens must be REJECTED WHOLE, never digit-prefix
            // truncated — `"8x" -> Some(8)` would silently mislabel a live-A/B
            // arm (Codex gate finding 1). Foreign (non-Rust-host) writers are
            // the only source of these.
            // `8 x` (whitespace smuggling, re-stamp F1) must reject like `8x`.
            for bad in ["\"8x\"", "8.5", "8e2", "-1", "\"8\"", "0x10", "[8]", "8 x"] {
                fs::write(
                    &control,
                    format!(
                        r#"{{"mode":"hourly_poll","duration_ms":8000,"sample_ms":10,"prefetch_dist_relation":{bad},"prefetch_dist_candidates":{bad}}}"#
                    ),
                )
                .unwrap();
                let parsed = collector_control(&dll).unwrap();
                assert_eq!(
                    parsed.prefetch_dist_relation, None,
                    "malformed token {bad} must reject, not truncate"
                );
                assert_eq!(parsed.prefetch_dist_candidates, None);
            }
            // Whole tokens still accepted when the terminator is }, comma, or ws.
            fs::write(
                &control,
                r#"{"mode":"hourly_poll","duration_ms":8000,"sample_ms":10,"prefetch_dist_candidates":12,"prefetch_dist_relation":16}"#,
            )
            .unwrap();
            let parsed = collector_control(&dll).unwrap();
            assert_eq!(parsed.prefetch_dist_relation, Some(16));
            assert_eq!(parsed.prefetch_dist_candidates, Some(12));

            // Key-collision attack (re-stamp F1): the key name occurring as a
            // string VALUE must not alias a neighboring number — only a string
            // literal followed by ':' is a key. The real key later in the file
            // must win with its own value.
            fs::write(
                &control,
                r#"{"mode":"hourly_poll","duration_ms":8,"session_id":"prefetch_dist_relation","prefetch_dist_relation":16,"pipe_token":"prefetch_dist_candidates","sample_ms":7}"#,
            )
            .unwrap();
            let parsed = collector_control(&dll).unwrap();
            assert_eq!(parsed.prefetch_dist_relation, Some(16));
            // Key present only inside a string VALUE -> treated as absent.
            assert_eq!(parsed.prefetch_dist_candidates, None);
            let _ = fs::remove_dir_all(&dir);
        }

        // The session-start reset contract (Codex gate finding 5): applying a
        // control WITH overrides installs them; applying a control WITHOUT (or
        // no control at all — non-hoi4 process path) CLEARS them, so a resident
        // DLL can never carry one session's distances into the next. Runs in
        // ONE test because the slots are process-global (transient observation
        // by parallel tests is benign — hint-only — but mutation must not race).
        #[test]
        fn apply_prefetch_dist_overrides_installs_and_resets() {
            // 999_983: a sentinel no shell would export as the env distance, so
            // the post-reset assert_ne cannot collide with a real env value.
            let mut control = raw_test_control();
            control.prefetch_dist_relation = Some(999_983);
            control.prefetch_dist_candidates = Some(0);
            apply_prefetch_dist_overrides(Some(&control));
            assert_eq!(
                diplomacy53::extractor::effective_prefetch_dist_relation(),
                999_983
            );
            // 0 (prefetch OFF) must install verbatim — it is a real sweep arm.
            assert_eq!(
                diplomacy53::extractor::effective_prefetch_dist_candidates(),
                0
            );
            // Next session: control present but fields absent -> reset.
            control.prefetch_dist_relation = None;
            control.prefetch_dist_candidates = Some(999_983);
            apply_prefetch_dist_overrides(Some(&control));
            assert_ne!(
                diplomacy53::extractor::effective_prefetch_dist_relation(),
                999_983
            );
            assert_eq!(
                diplomacy53::extractor::effective_prefetch_dist_candidates(),
                999_983
            );
            // No control at all (parse failed / non-hoi4 process) -> also reset.
            apply_prefetch_dist_overrides(None);
            assert_ne!(
                diplomacy53::extractor::effective_prefetch_dist_candidates(),
                999_983
            );
        }

