        fn collector_control_explicit_field_overrides_profile_preset() {
            let dir = std::env::temp_dir().join(format!(
                "hoi4_collector_profile_override_test_{}",
                std::process::id()
            ));
            let _ = fs::remove_dir_all(&dir);
            fs::create_dir_all(&dir).unwrap();
            let dll = dir.join("collector.dll");
            let control = dir.join("collector_control.json");
            // debug preset => perf-gate on & sidecar on; explicit fields override
            // both back off — the same override semantics as the host.
            fs::write(
                &control,
                r#"{"mode":"hourly_poll","duration_ms":8000,"sample_ms":10,"profile":"debug","extraction_perf_gate":false,"sidecar_log":false,"reader_concurrency":7}"#,
            )
            .unwrap();

            let parsed = collector_control(&dll).unwrap();

            assert!(
                !parsed.extraction_perf_gate,
                "explicit false overrides debug preset"
            );
            assert!(!parsed.sidecar_log, "explicit false overrides debug preset");
            assert_eq!(parsed.reader_concurrency, 7);
            let _ = fs::remove_dir_all(&dir);
        }

