        // ---- P2 anchored naval discovery ----

        // The anchored discovery walks the SAME manager land combats use; the
        // offsets MUST stay tied to the land constants so a future land-manager
        // move can never silently desync the naval root.
        #[test]
        fn p2_naval_manager_offsets_track_land_constants() {
            assert_eq!(NAVAL_COMBAT_MANAGER_OFFSET, LAND_COMBAT_MANAGER_OFFSET);
            assert_eq!(NAVAL_COMBAT_MANAGER_DATA, LAND_COMBAT_MANAGER_DATA);
            assert_eq!(NAVAL_COMBAT_MANAGER_COUNT, LAND_COMBAT_MANAGER_COUNT);
            // Live-confirmed 870ebf side FEX group vector header: data @ +0xC8,
            // count(u32) @ +0xD0, capacity(u32) @ +0xD4 (the prior rejection read
            // count at the capacity dword). count and capacity are 4 bytes apart.
            assert_eq!(NAVAL_COMBAT_SIDE_OFF_GROUP_VEC_DATA, 0xC8);
            assert_eq!(NAVAL_COMBAT_SIDE_OFF_GROUP_VEC_COUNT, 0xD0);
            assert_eq!(
                NAVAL_COMBAT_SIDE_OFF_GROUP_VEC_CAPACITY,
                NAVAL_COMBAT_SIDE_OFF_GROUP_VEC_COUNT + 4
            );
            assert_eq!(NAVAL_COMBAT_GROUP_OFF_NEXT, 0x20);
        }

        // Audit mode is opt-in: unset env -> fast anchored path, no heap scan.
        #[test]
        fn p2_naval_discovery_audit_defaults_off() {
            // The process env is not set in the normal test harness; the gate
            // must read false. (Guarded so a CI runner that DID set it is not a
            // spurious failure.)
            if std::env::var("BATTLE_PLAN_NAVAL_DISCOVERY_AUDIT").or_else(|_| std::env::var("HOI4_NAVAL_DISCOVERY_AUDIT")).is_err() {
                assert!(!naval_discovery_audit_enabled());
            }
        }

        // Ring-closure control logic (loop-safety) — memory read fully mocked via
        // the `next` closure, so these prove termination WITHOUT live memory.
        #[test]
        fn p2_ring_closure_closes_on_full_cycle() {
            // 4-node ring: a -> b -> c -> d -> a. Seeding at a visits all four
            // exactly once and stops.
            let ring: std::collections::BTreeMap<usize, usize> =
                [(10, 20), (20, 30), (30, 40), (40, 10)]
                    .into_iter()
                    .collect();
            let mut out = BTreeSet::new();
            assert_eq!(
                naval_ring_closure_into(10, &mut out, |c| ring.get(&c).copied()),
                Ok(())
            );
            assert_eq!(out, BTreeSet::from([10, 20, 30, 40]));
        }

        #[test]
        fn p2_ring_closure_excludes_invalid_terminator_node() {
            // 10 is a valid node whose successor is 20; 20 is NOT a valid node
            // (visit returns None). With the validate-before-insert contract, 20
            // must NOT be inserted — this is the guard against the last group's
            // +0x20 pointer (which leaves the CFEXGroup vtable) contaminating the
            // candidate set.
            let mut out = BTreeSet::new();
            assert_eq!(
                naval_ring_closure_into(10, &mut out, |c| match c {
                    10 => Some(20),
                    _ => None,
                }),
                Ok(())
            );
            assert_eq!(out, BTreeSet::from([10]));
        }

        #[test]
        fn p2_ring_closure_fails_closed_past_hop_cap() {
            // An ever-advancing chain that never repeats and never returns None
            // MUST fail closed at the hop cap (no infinite loop, no OOM, and NOT
            // a silent truncation — a ring this long is a torn/looping list).
            let mut out = BTreeSet::new();
            assert_eq!(
                naval_ring_closure_into(0, &mut out, |c| Some(c + 2)),
                Err("naval_group_ring_overflow")
            );
            // It still bounded its work to the hop cap before erroring.
            assert_eq!(out.len(), MAX_NAVAL_COMBAT_RING_HOPS);
        }

        #[test]
        fn p2_ring_closure_self_loop_is_single_node() {
            // Degenerate ring: a -> a. One node, then close.
            let mut out = BTreeSet::new();
            let mut hops = 0u32;
            assert_eq!(
                naval_ring_closure_into(10, &mut out, |c| {
                    hops += 1;
                    Some(c) // always points at itself
                }),
                Ok(())
            );
            assert_eq!(out, BTreeSet::from([10]));
            // Exactly one successor read before local_seen catches the repeat.
            assert_eq!(hops, 1);
        }

        #[test]
        fn p2_ring_closure_accumulates_across_seeds_into_shared_out() {
            // Two disjoint rings unioned into one `out` (mirrors both sides'
            // seeds contributing to one candidate set). The second seed's ring
            // is NOT truncated by the first ring's nodes already in `out`.
            let ring_a: std::collections::BTreeMap<usize, usize> =
                [(10, 20), (20, 10)].into_iter().collect();
            let ring_b: std::collections::BTreeMap<usize, usize> =
                [(30, 40), (40, 30)].into_iter().collect();
            let mut out = BTreeSet::new();
            assert_eq!(
                naval_ring_closure_into(10, &mut out, |c| ring_a.get(&c).copied()),
                Ok(())
            );
            assert_eq!(
                naval_ring_closure_into(30, &mut out, |c| ring_b.get(&c).copied()),
                Ok(())
            );
            assert_eq!(out, BTreeSet::from([10, 20, 30, 40]));
        }

        // Anchored discovery fails closed (never panics / never reads OOB) on a
        // zero module base — rejected before any memory read. (A non-heap gs is
        // also rejected, but only after the RTTI vtable gate, which cannot be
        // satisfied without a live module, so it is exercised by the live
        // audit-mode parity run rather than this pure unit test.)
        #[test]
        fn p2_anchored_discovery_rejects_zero_module_base() {
            assert_eq!(
                discover_naval_combat_anchored(0, HEAP_LO),
                Err("naval_module_base_zero")
            );
        }

