        #[test]
        fn army_order_tracker_splits_generation_on_pointer_reuse() {
            let control = raw_test_control();
            let clock = ClockSample {
                date: "1936.1.1.12".to_string(),
                hour_index: ((1936 * 365) * 24 + 12) as u64,
                raw_date: DATE_EPOCH_CONST + ((1936 * 365) * 24 + 12),
            };
            let mut tracker = ArmyOrderTracker::default();
            let sample = ArmyOrderSample {
                owner_kind: battleplans54::ORDER_OWNER_KIND_ARMY,
                army_id: 17,
                generation: 0,
                engine_order_instance_id: 2_005,
                order_addr: HEAP_LO + 0x33000,
                slot_index: 2,
                order_type: ORDER_TYPE_AREA_DEFENSE,
                target_states: Some(vec![107, 108]),
                target_state_count: Some(2),
                target_status: "exact",
                path_provinces: None,
                geometry_status: "exact",
                assigned_division_ids: Some(vec![703]),
                assigned_units_status: "exact",
                active: Some(true),
                active_status: "exact",
            };
            let _ = build_army_order_raw_lines_from_samples(
                1234,
                &control,
                &mut tracker,
                vec![sample.clone()],
                10,
                100,
                123456,
                Some(125),
                "worker_poll",
                &clock,
            );

            let mut reused = sample;
            reused.army_id = 23;
            reused.engine_order_instance_id = 2_006;
            reused.slot_index = 0;
            let split = build_army_order_raw_lines_from_samples(
                1234,
                &control,
                &mut tracker,
                vec![reused],
                20,
                200,
                123556,
                Some(225),
                "worker_poll",
                &clock,
            );

            assert_eq!(split.len(), 4);
            assert!(split[0].contains("\"entity_key\":\"army_order:17:2005:0\""));
            assert!(split[0].contains("\"payload\":{\"op\":\"delete\",\"after\":null"));
            assert!(split[1].contains("\"event_type\":\"army_order_removed\""));
            assert!(split[1].contains("\"entity_key\":\"army_order:17:2005:0\""));
            assert!(split[2].contains("\"entity_key\":\"army_order:23:2006:1\""));
            assert!(split[2].contains("\"order_key\":\"army_order:23:2006:1\""));
            assert!(split[3].contains("\"event_type\":\"army_order_added\""));
            assert!(split[3].contains("\"entity_key\":\"army_order:23:2006:1\""));
            for frame in &split {
                assert!(!frame.contains("order_addr"));
                assert!(!frame.contains("body_ptr"));
                assert!(!frame.contains("body_addr"));
                assert!(!frame.contains("tag_db_id"));
                assert!(!frame.contains("0x"));
            }
        }

