        #[test]
        fn land_combat_manager_fails_closed_when_any_slot_is_unreadable() {
            let sample = LandCombatSample {
                combat_id: 271,
                generation: 0,
                body_addr: HEAP_LO + 0x12000,
                attacker_side_addr: 0,
                defender_side_addr: 0,
                location: Some(3986),
                day: Some(4618),
                duration: Some(17),
                attacker_divisions: Some(vec![1053, 2837]),
                defender_divisions: Some(vec![465]),
                attacker_status: "exact",
                defender_status: "exact",
                attacker_detail: None,
                defender_detail: None,
                attacker_attribution: Vec::new(),
                defender_attribution: Vec::new(),
                attacker_reserve_divisions: None,
                defender_reserve_divisions: None,
            };
            let mut samples = BTreeMap::new();
            samples.insert(sample.combat_id, sample);

            let failure = LandCombatFailure::new(
                "manager_entry_invalid",
                D21_FAILURE_SIDE_VECTOR_ELEMENT,
            )
            .at_manager_index(2)
            .for_combat(271)
            .for_side(1)
            .with_vector_header(HEAP_LO + 0x22000, 3, 3)
            .at_vector_element(1);
            let error =
                land_combat_manager_samples_result(samples, Some(failure)).unwrap_err();
            assert_eq!(error, failure);
            let units = error.diagnostic_units();
            assert_eq!(
                units
                    .iter()
                    .find(|unit| unit.name == "d21_failure_code")
                    .map(|unit| unit.value),
                Some(D21_FAILURE_SIDE_VECTOR_ELEMENT)
            );
            assert_eq!(
                units
                    .iter()
                    .find(|unit| unit.name == "d21_failure_vector_size")
                    .map(|unit| unit.value),
                Some(3)
            );
        }

