        #[test]
        fn land_combat_side_vector_requires_wrappers_and_preserves_complete_census() {
            let module_base = HEAP_LO + 0x40_0000;
            let mut first_wrapper = AlignedBytes::<0x20>::new();
            let mut second_wrapper = AlignedBytes::<0x20>::new();
            for (wrapper, division_id) in [
                (&mut first_wrapper, 701u32),
                (&mut second_wrapper, 305u32),
            ] {
                wrapper.write_u64(0, (module_base + DIVISION_WRAPPER_VTABLE_RVA) as u64);
                wrapper.write_u64(
                    DIVISION_WRAPPER_TO_BODY,
                    (module_base + DIVISION_VTABLE_RVA) as u64,
                );
                wrapper.write_u32(
                    DIVISION_WRAPPER_TO_BODY + DIVISION_OFF_ID_TYPE,
                    DIVISION_TYPE,
                );
                wrapper.write_u32(
                    DIVISION_WRAPPER_TO_BODY + DIVISION_OFF_ID_ID,
                    division_id,
                );
            }
            let mut elements = AlignedBytes::<0x10>::new();
            elements.write_u64(0, first_wrapper.addr() as u64);
            elements.write_u64(8, second_wrapper.addr() as u64);
            let mut side = AlignedBytes::<0x30>::new();
            side.write_u64(0, (module_base + LAND_COMBAT_SIDE_VTABLE_RVA) as u64);
            side.write_u64(LAND_COMBAT_SIDE_OFF_DATA, elements.addr() as u64);
            side.write_u32(LAND_COMBAT_SIDE_OFF_CAPACITY, 2);
            side.write_u32(LAND_COMBAT_SIDE_OFF_SIZE, 2);

            assert_eq!(
                read_land_combat_side_units(module_base, side.addr()).unwrap(),
                vec![701, 305],
                "the authenticated engine order is preserved without sorting"
            );
            assert_eq!(
                resolve_land_combat_unit_id(
                    module_base,
                    first_wrapper.addr() + DIVISION_WRAPPER_TO_BODY
                ),
                None,
                "a bare body is not an authenticated side-vector wrapper"
            );

            elements.write_u64(8, first_wrapper.addr() as u64);
            let duplicate = read_land_combat_side_units(module_base, side.addr()).unwrap_err();
            assert_eq!(duplicate.code, D21_FAILURE_SIDE_VECTOR_DUPLICATE);
            assert_eq!(duplicate.vector_element_index_plus_one, 2);
            assert_eq!(duplicate.vector_size, 2);
        }

