        #[test]
        fn naval_strategic_region_parser_extracts_id_and_provinces() {
            let text = "strategic_region={\n\tid=178 # region id\n\tname=\"REGION\"\n\tprovinces={\n\t\t12 34 56\n\t}\n}";
            let stripped = strip_line_comments_bytes(text.as_bytes());
            assert_eq!(parse_first_word_u32_bytes(&stripped, b"id"), Some(178));
            let mut map = BTreeMap::new();
            assert!(insert_first_brace_list_u32_bytes(
                &stripped,
                b"provinces",
                178,
                &mut map
            ));
            assert_eq!(map.get(&12), Some(&178));
            assert_eq!(map.get(&34), Some(&178));
            assert_eq!(map.get(&56), Some(&178));
            assert!(!map.contains_key(&178));
        }

