        #[test]
        fn naval_combat_live_delta_emits_start_update_end_and_new_generation() {
            let mut tracker = CompactNavalCombatLiveTracker::default();
            let walk = naval_walk_fixture();
            let joins = naval_walk_joins();

            let started = naval_combat_live_emit_delta(
                Instant::now(),
                0,
                &mut tracker,
                &walk,
                &joins,
                1,
                2,
                0,
            );
            assert_eq!(started.lifecycle_emitted_rows, 1);
            assert_eq!(started.member_emitted_rows, 2);
            assert_eq!(
                started.lifecycle_payload_status_flags,
                naval4950::STATUS_DELTA_DATA,
                "promoted location+region must not set the unvalidated badge"
            );
            let lifecycle = naval4950::decode_lifecycle_data_payload(0, &started.lifecycle_payload);
            assert!(
                lifecycle.parse_errors.is_empty(),
                "{:?}",
                lifecycle.parse_errors
            );
            assert_eq!(lifecycle.row_count, 1);
            let members = naval4950::decode_members_data_payload(0, &started.member_payload);
            assert!(
                members.parse_errors.is_empty(),
                "{:?}",
                members.parse_errors
            );
            assert_eq!(members.row_count, 2);
            assert_eq!(
                members
                    .data_units_total
                    .get("naval_combat_cship_validated_member_rows"),
                Some(&1)
            );
            assert_eq!(
                members
                    .data_units_total
                    .get("naval_combat_convoy_member_rows"),
                Some(&1)
            );

            // Unchanged frame emits zero rows for both domains.
            let unchanged = naval_combat_live_emit_delta(
                Instant::now(),
                0,
                &mut tracker,
                &walk,
                &joins,
                1,
                2,
                0,
            );
            assert_eq!(unchanged.lifecycle_emitted_rows, 0);
            assert_eq!(unchanged.member_emitted_rows, 0);

            // Teardown frame emits deleted lifecycle + member rows.
            let empty = NavalWalkFrame {
                combats: Vec::new(),
                stale_dropped: 0,
            };
            let ended = naval_combat_live_emit_delta(
                Instant::now(),
                0,
                &mut tracker,
                &empty,
                &BTreeMap::new(),
                0,
                0,
                0,
            );
            assert_eq!(ended.lifecycle_emitted_rows, 1);
            assert_eq!(ended.member_emitted_rows, 2);
            let ended_members = naval4950::decode_members_data_payload(0, &ended.member_payload);
            assert!(ended_members.parse_errors.is_empty());
            assert_eq!(
                ended_members
                    .data_units_total
                    .get("naval_combat_member_deleted_rows"),
                Some(&2)
            );

            // A restart of the same combat id starts a NEW generation.
            let restarted = naval_combat_live_emit_delta(
                Instant::now(),
                0,
                &mut tracker,
                &walk,
                &joins,
                1,
                2,
                0,
            );
            assert_eq!(restarted.lifecycle_emitted_rows, 1);
            let generations: std::collections::BTreeSet<u64> = tracker
                .previous_lifecycle
                .keys()
                .map(|(_, generation)| *generation)
                .collect();
            assert_eq!(generations.len(), 1);
            assert!(generations.iter().next().copied().unwrap() > 1);
        }

