        #[test]
        fn project_breakthrough_reads_all_three_program_status_records() {
            let base = HEAP_LO;
            let status_vtable = base + PROJECT_PROGRAM_STATUS_A_VTABLE_RVA;
            let breakthrough_vtable = base + PROJECT_BREAKTHROUGH_PROGRESS_VTABLE_RVA;
            let mut status = AlignedBytes::<0x400>::new();
            let mut headers = [
                AlignedBytes::<0x28>::new(),
                AlignedBytes::<0x28>::new(),
                AlignedBytes::<0x28>::new(),
            ];
            let mut nodes = [
                AlignedBytes::<0x28>::new(),
                AlignedBytes::<0x28>::new(),
                AlignedBytes::<0x28>::new(),
            ];
            for index in 0..MAX_PROJECT_PROGRAM_STATUS_RECORDS {
                let record = index * PROJECT_PROGRAM_STATUS_RECORD_STRIDE;
                status.write_u64(record, status_vtable as u64);
                status.write_u64(
                    record + PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH,
                    breakthrough_vtable as u64,
                );
                status.write_u64(
                    record + PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH + 0x08,
                    headers[index].addr() as u64,
                );
                status.write_u64(record + PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH + 0x10, 1);
                headers[index].write_u64(0, nodes[index].addr() as u64);
                headers[index].write_u64(0x08, nodes[index].addr() as u64);
                headers[index].write_u64(0x10, nodes[index].addr() as u64);
                headers[index].write_u8(0x19, 1);
                nodes[index].write_u64(0, headers[index].addr() as u64);
                nodes[index].write_u64(0x08, headers[index].addr() as u64);
                nodes[index].write_u64(0x10, headers[index].addr() as u64);
                nodes[index].write_u8(0x19, 0);
                nodes[index].write_u32(0x1C, 22_214 + index as u32);
                nodes[index].write_u32(0x20, 10 + index as u32 * 10);
            }

            let rows = match read_project_breakthrough_rows_from_status_records(
                status.addr(),
                status_vtable,
                breakthrough_vtable,
                47,
            ) {
                ProjectRootRead::Valid(rows) => rows,
                _ => panic!("all three valid program-status records must parse"),
            };
            assert_eq!(rows.len(), 3);
            assert_eq!(rows[0].program_status_index, 0);
            assert_eq!(rows[1].program_status_index, 1);
            assert_eq!(rows[2].program_status_index, 2);
            assert_eq!(rows[0].specialization_handle, 22_214);
            assert_eq!(rows[1].specialization_handle, 22_215);
            assert_eq!(rows[2].specialization_handle, 22_216);
        }

        #[test]
        fn project_breakthrough_uses_exact_successor_walk_from_minimum_node() {
            let base = HEAP_LO;
            let status_vtable = base + PROJECT_PROGRAM_STATUS_A_VTABLE_RVA;
            let breakthrough_vtable = base + PROJECT_BREAKTHROUGH_PROGRESS_VTABLE_RVA;
            let mut status = AlignedBytes::<0x200>::new();
            let mut header = AlignedBytes::<0x28>::new();
            let mut minimum = AlignedBytes::<0x28>::new();
            let mut root = AlignedBytes::<0x28>::new();
            let mut maximum = AlignedBytes::<0x28>::new();

            status.write_u64(0, status_vtable as u64);
            status.write_u64(
                PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH,
                breakthrough_vtable as u64,
            );
            status.write_u64(
                PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH + 0x08,
                header.addr() as u64,
            );
            status.write_u64(PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH + 0x10, 3);

            header.write_u64(0, minimum.addr() as u64);
            header.write_u64(0x08, root.addr() as u64);
            header.write_u64(0x10, maximum.addr() as u64);
            header.write_u8(0x19, 1);

            minimum.write_u64(0, header.addr() as u64);
            minimum.write_u64(0x08, root.addr() as u64);
            minimum.write_u64(0x10, header.addr() as u64);
            minimum.write_u8(0x19, 0);
            minimum.write_u32(0x1C, 22_214);
            minimum.write_u32(0x20, 10);

            root.write_u64(0, minimum.addr() as u64);
            root.write_u64(0x08, header.addr() as u64);
            root.write_u64(0x10, maximum.addr() as u64);
            root.write_u8(0x19, 0);
            root.write_u32(0x1C, 22_215);
            root.write_u32(0x20, 20);

            maximum.write_u64(0, header.addr() as u64);
            maximum.write_u64(0x08, root.addr() as u64);
            maximum.write_u64(0x10, header.addr() as u64);
            maximum.write_u8(0x19, 0);
            maximum.write_u32(0x1C, 22_216);
            maximum.write_u32(0x20, 30);

            let rows = match read_project_breakthrough_rows_from_status_records(
                status.addr(),
                status_vtable,
                breakthrough_vtable,
                47,
            ) {
                ProjectRootRead::Valid(rows) => rows,
                _ => panic!("exact minimum-node successor walk must parse"),
            };
            assert_eq!(
                rows.iter()
                    .map(|row| (row.specialization_handle, row.points_raw))
                    .collect::<Vec<_>>(),
                vec![(22_214, 10), (22_215, 20), (22_216, 30)]
            );
        }

        #[test]
        fn project_breakthrough_preserves_same_handle_in_distinct_status_records() {
            let base = HEAP_LO;
            let status_vtable = base + PROJECT_PROGRAM_STATUS_A_VTABLE_RVA;
            let breakthrough_vtable = base + PROJECT_BREAKTHROUGH_PROGRESS_VTABLE_RVA;
            let mut status = AlignedBytes::<0x300>::new();
            let mut headers = [AlignedBytes::<0x28>::new(), AlignedBytes::<0x28>::new()];
            let mut nodes = [AlignedBytes::<0x28>::new(), AlignedBytes::<0x28>::new()];
            for index in 0..2usize {
                let record = index * PROJECT_PROGRAM_STATUS_RECORD_STRIDE;
                status.write_u64(record, status_vtable as u64);
                status.write_u64(
                    record + PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH,
                    breakthrough_vtable as u64,
                );
                status.write_u64(
                    record + PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH + 0x08,
                    headers[index].addr() as u64,
                );
                status.write_u64(record + PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH + 0x10, 1);
                headers[index].write_u64(0, nodes[index].addr() as u64);
                headers[index].write_u64(0x08, nodes[index].addr() as u64);
                headers[index].write_u64(0x10, nodes[index].addr() as u64);
                headers[index].write_u8(0x19, 1);
                nodes[index].write_u64(0, headers[index].addr() as u64);
                nodes[index].write_u64(0x08, headers[index].addr() as u64);
                nodes[index].write_u64(0x10, headers[index].addr() as u64);
                nodes[index].write_u8(0x19, 0);
                nodes[index].write_u32(0x1C, 22_214);
                nodes[index].write_u32(0x20, 10);
            }
            nodes[1].write_u32(0x20, 11);
            let rows = match read_project_breakthrough_rows_from_status_records(
                status.addr(),
                status_vtable,
                breakthrough_vtable,
                47,
            ) {
                ProjectRootRead::Valid(rows) => rows,
                _ => panic!("record index is part of the exact engine-row identity"),
            };
            assert_eq!(
                rows.iter()
                    .map(|row| (
                        row.program_status_index,
                        row.specialization_handle,
                        row.points_raw,
                    ))
                    .collect::<Vec<_>>(),
                vec![(0, 22_214, 10), (1, 22_214, 11)]
            );
        }

        #[test]
        fn project_breakthrough_rejects_torn_tree_without_emitting_prefix() {
            let base = HEAP_LO;
            let status_vtable = base + PROJECT_PROGRAM_STATUS_A_VTABLE_RVA;
            let breakthrough_vtable = base + PROJECT_BREAKTHROUGH_PROGRESS_VTABLE_RVA;
            let mut status = AlignedBytes::<0x200>::new();
            let mut header = AlignedBytes::<0x28>::new();
            let mut node = AlignedBytes::<0x28>::new();
            status.write_u64(0, status_vtable as u64);
            status.write_u64(
                PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH,
                breakthrough_vtable as u64,
            );
            status.write_u64(
                PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH + 0x08,
                header.addr() as u64,
            );
            status.write_u64(PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH + 0x10, 2);
            header.write_u64(0, node.addr() as u64);
            header.write_u64(0x08, node.addr() as u64);
            header.write_u64(0x10, node.addr() as u64);
            header.write_u8(0x19, 1);
            node.write_u64(0, header.addr() as u64);
            node.write_u64(0x08, header.addr() as u64);
            node.write_u64(0x10, header.addr() as u64);
            node.write_u8(0x19, 0);
            node.write_u32(0x1C, 22_214);
            node.write_u32(0x20, 10);

            assert!(matches!(
                read_project_breakthrough_rows_from_status_records(
                    status.addr(),
                    status_vtable,
                    breakthrough_vtable,
                    47,
                ),
                ProjectRootRead::Invalid
            ));
        }

        #[test]
        fn country_project_pool_cache_reads_scientists_from_country_roster_root() {
            let base = HEAP_LO;
            let status_a_vtable = base + PROJECT_PROGRAM_STATUS_A_VTABLE_RVA;
            let status_b_vtable = base + PROJECT_PROGRAM_STATUS_B_VTABLE_RVA;
            let breakthrough_vtable = base + PROJECT_BREAKTHROUGH_PROGRESS_VTABLE_RVA;
            let character_vtable = base + PROJECT_CHARACTER_VTABLE_RVA;
            let scientist_vtable = base + PROJECT_SCIENTIST_VTABLE_RVA;

            let mut country = AlignedBytes::<0x1200>::new();
            let mut status = AlignedBytes::<0x80>::new();
            let mut roster = AlignedBytes::<0xC0>::new();
            let mut roster_slots = AlignedBytes::<0x08>::new();
            let mut wrapper = AlignedBytes::<0x10>::new();
            let mut character = AlignedBytes::<0x140>::new();
            let mut scientist = AlignedBytes::<0x140>::new();
            let mut skills = AlignedBytes::<0x80>::new();

            country.write_u64(0, (base + COUNTRY_VTABLE_RVA) as u64);
            country.write_u32(OBJ_TAG_DB_ID, 47);
            status.write_u64(0, status_a_vtable as u64);
            status.write_u64(8, status_b_vtable as u64);
            status.write_u64(
                PROJECT_PROGRAM_STATUS_OFF_BREAKTHROUGH,
                breakthrough_vtable as u64,
            );
            country.write_u64(COUNTRY_OFF_PROGRAM_STATUS, status.addr() as u64);
            country.write_u64(PROJECT_COUNTRY_OFF_SCIENTIST_ROSTER, roster.addr() as u64);
            roster.write_u64(PROJECT_SCIENTIST_ROSTER_VECTOR, roster_slots.addr() as u64);
            roster.write_u32(
                PROJECT_SCIENTIST_ROSTER_VECTOR + PROJECT_SCIENTIST_ROSTER_VECTOR_COUNT,
                1,
            );
            roster_slots.write_u64(0, wrapper.addr() as u64);
            wrapper.write_u64(
                PROJECT_SCIENTIST_ROSTER_WRAPPER_CHARACTER,
                character.addr() as u64,
            );

            character.write_u64(0, character_vtable as u64);
            character.write_u32(PROJECT_CHARACTER_OFF_TYPE, PROJECT_CHARACTER_TYPE);
            character.write_u32(PROJECT_CHARACTER_OFF_ID, 44);
            character.write_u64(PROJECT_CHARACTER_OFF_SCIENTIST_PTR, scientist.addr() as u64);
            scientist.write_u64(0, scientist_vtable as u64);
            scientist.write_u32(PROJECT_SCIENTIST_OFF_TRAIT_COUNT, 3);
            scientist.write_u64(PROJECT_SCIENTIST_OFF_SKILLS_PTR, skills.addr() as u64);
            for (idx, level) in [4, 0, 1, 2].iter().copied().enumerate() {
                let rec = idx * PROJECT_SKILL_STRIDE;
                skills.write_u16(rec, PROJECT_SKILL_HEADER_BASE + idx as u16);
                skills.write_i32(rec + PROJECT_SKILL_LEVEL_OFF, level);
            }

            let country_identity = CountryIdentityCache {
                status: "gamestate_country_table_verified",
                scan_ms: 0,
                country_vtable: base + COUNTRY_VTABLE_RVA,
                bridge_rows_supplied: 0,
                record_rows_supplied: 0,
                rows: vec![test_country_row("POR", 47, country.addr())],
                rejected_objects: 0,
                duplicate_tags: 0,
            };
            let special_projects =
                SpecialProjectsCache::from_country_project_pools(base, &country_identity);

            assert_eq!(special_projects.status, "country_project_pool_verified");
            assert_eq!(special_projects.scientists.len(), 1);
            assert_eq!(special_projects.scientists[0].char_id, 44);

            let state = CollectorState {
                base,
                daily_addr: 0,
                long_string_addr: 0,
                daily_match: true,
                long_string_match: true,
                date_ptr: 0,
                country_database_ptr: 0,
                country_identity,
                special_projects,
                weather: CompactWeatherRoot::default(),
            };
            let mut tracker = CompactProjectsTracker::default();
            let read = read_compact_projects(
                &state,
                COMPACT_STATUS_EXTRACTION_PERF_GATE,
                D41EmitMode::Delta,
                &mut tracker,
            );

            assert_eq!(read.scientists.len(), 1);
            assert_eq!(read.observed_scientist_rows, 1);
            assert_eq!(read.scientists[0].char_id, 44);
            assert_eq!(
                read.scientists[0]
                    .skills
                    .get("specialization_nuclear")
                    .copied(),
                Some(4)
            );
            assert_eq!(read.scientists[0].trait_count, Some(3));
            assert_eq!(read.status_flags & COMPACT_STATUS_SOURCE_UNAVAILABLE, 0);
            assert_eq!(read.status_flags & COMPACT_STATUS_PARTIAL_DATA, 0);

            // A cached tag must not be applied to a country object whose live
            // tag_db_id changed or whose pointer was reused between scans.
            country.write_u32(OBJ_TAG_DB_ID, 48);
            let mut stale_owner_tracker = CompactProjectsTracker::default();
            let stale_owner_read = read_compact_projects(
                &state,
                COMPACT_STATUS_EXTRACTION_PERF_GATE,
                D41EmitMode::Delta,
                &mut stale_owner_tracker,
            );
            assert_ne!(
                stale_owner_read.status_flags & COMPACT_STATUS_PARTIAL_DATA,
                0
            );
            assert!(stale_owner_read.breakthrough.is_empty());
        }

        // P4c-2: prove the batched facility-cluster read [0x50,0x60) yields
        // byte-identical u32 values to the per-field `read_u32` at each offset,
        // and that `read_project_facility_row` returns the SAME row whether it
        // sources the four fields from the batch slice (committed object -> batch
        // Some) or would fall back per-field. This is the P4c-2 byte-identical
        // criterion for the d41 facility cluster.
        #[test]
        fn project_facility_cluster_batch_matches_per_field() {
            let facility_vtable = HEAP_LO + 0x1000;
            let mut facility = AlignedBytes::<0x200>::new();
            assert!(is_map_control_heap_pointer(facility.addr()));

            facility.write_u64(0, facility_vtable as u64);
            facility.write_u32(PROJECT_FACILITY_OFF_TYPE, PROJECT_FACILITY_TYPE);
            facility.write_u32(PROJECT_FACILITY_OFF_ID, 118);
            facility.write_u32(PROJECT_FACILITY_OFF_PROVINCE, 341);
            // The batched cluster: active_handle=9001, active_flag=1,
            // scientist_type=PROJECT_CHARACTER_TYPE, scientist_id=44.
            facility.write_u32(PROJECT_FACILITY_OFF_ACTIVE_HANDLE, 9001);
            facility.write_u32(PROJECT_FACILITY_OFF_ACTIVE_FLAG, 1);
            facility.write_u32(PROJECT_FACILITY_OFF_SCIENTIST_TYPE, PROJECT_CHARACTER_TYPE);
            facility.write_u32(PROJECT_FACILITY_OFF_SCIENTIST_ID, 44);
            facility.write_u32(PROJECT_FACILITY_OFF_UNREAD_REWARDS, 0);

            let addr = facility.addr();

            // Byte-identical field parse: batch slice vs per-field primitive.
            let cluster = read_bytes(addr + PROJECT_FACILITY_OFF_ACTIVE_HANDLE, 16)
                .expect("committed facility cluster batches");
            assert_eq!(
                read_u32_from_slice(&cluster, 0x00),
                read_u32(addr + PROJECT_FACILITY_OFF_ACTIVE_HANDLE),
                "active_handle slice vs per-field"
            );
            assert_eq!(
                read_u32_from_slice(&cluster, 0x04),
                read_u32(addr + PROJECT_FACILITY_OFF_ACTIVE_FLAG),
                "active_flag slice vs per-field"
            );
            assert_eq!(
                read_u32_from_slice(&cluster, 0x08),
                read_u32(addr + PROJECT_FACILITY_OFF_SCIENTIST_TYPE),
                "scientist_type slice vs per-field"
            );
            assert_eq!(
                read_u32_from_slice(&cluster, 0x0C),
                read_u32(addr + PROJECT_FACILITY_OFF_SCIENTIST_ID),
                "scientist_id slice vs per-field"
            );

            // Whole-row parity: the reader (which uses the batch) produces the
            // expected row from the committed object.
            let pin = ProjectFacilityPin {
                addr,
                facility_id: 118,
                province_id: 341,
            };
            let row = read_project_facility_row(pin, facility_vtable)
                .expect("committed facility row parses");
            assert_eq!(row.id, 118);
            assert_eq!(row.province, 341);
            assert_eq!(row.active_project_handle, 9001);
            assert!(row.active);
            assert_eq!(row.scientist_char_id, Some(44));
            assert_eq!(row.unread_prototype_rewards, 0);
        }

        // P4c-2: prove the batched scientist-skills cluster read [0, 0x7C) yields
        // byte-identical header(u16)/level(i32) values to the per-field reads at
        // each record, and that `read_project_scientist_skills` returns the SAME
        // map. This is the P4c-2 byte-identical criterion for the d41 skills
        // cluster.
        #[test]
        fn project_scientist_skills_cluster_batch_matches_per_field() {
            let mut skills = AlignedBytes::<0x80>::new();
            assert!(is_map_control_heap_pointer(skills.addr()));
            let levels = [4i32, 0, 1, 2];
            for (idx, level) in levels.iter().copied().enumerate() {
                let rec = idx * PROJECT_SKILL_STRIDE;
                skills.write_u16(rec, PROJECT_SKILL_HEADER_BASE + idx as u16);
                skills.write_i32(rec + PROJECT_SKILL_LEVEL_OFF, level);
            }
            let skills_ptr = skills.addr();

            const SKILL_CLUSTER_LEN: usize = 3 * PROJECT_SKILL_STRIDE + PROJECT_SKILL_LEVEL_OFF + 4;
            // The batch span must equal the per-field union span (0x7C), never
            // larger -- so the batch can only fail where a per-field read also
            // would.
            assert_eq!(SKILL_CLUSTER_LEN, 0x7C);
            let cluster = read_bytes(skills_ptr, SKILL_CLUSTER_LEN)
                .expect("committed skills cluster batches");
            for idx in 0..4usize {
                let rec = skills_ptr + idx * PROJECT_SKILL_STRIDE;
                let cluster_off = idx * PROJECT_SKILL_STRIDE;
                assert_eq!(
                    read_u16_from_slice(&cluster, cluster_off),
                    read_u16(rec),
                    "skill {idx} header slice vs per-field"
                );
                assert_eq!(
                    read_i32_from_slice(&cluster, cluster_off + PROJECT_SKILL_LEVEL_OFF),
                    read_i32(rec + PROJECT_SKILL_LEVEL_OFF),
                    "skill {idx} level slice vs per-field"
                );
            }

            // Whole-map parity: the reader takes a SCIENTIST pointer and hops
            // `+SKILLS_PTR` to reach the array. Build a scientist object pointing
            // at our committed skills array.
            let mut scientist = AlignedBytes::<0x140>::new();
            assert!(is_map_control_heap_pointer(scientist.addr()));
            scientist.write_u64(PROJECT_SCIENTIST_OFF_SKILLS_PTR, skills_ptr as u64);
            let map = read_project_scientist_skills(scientist.addr()).expect("skills map parses");
            assert_eq!(map.get("specialization_nuclear").copied(), Some(4));
            assert_eq!(map.get("specialization_naval").copied(), Some(0));
            assert_eq!(map.get("specialization_air").copied(), Some(1));
            assert_eq!(map.get("specialization_land").copied(), Some(2));
        }

