        #[test]
        fn compact_projects_empty_sentinel_roots_are_neutral_before_first_pin() {
            let facility_vtable = HEAP_LO + 0x1000;
            let pool_vtable = HEAP_LO + 0x2000;
            let project_vtable = HEAP_LO + 0x3000;
            let sentinel_vtable = HEAP_LO + 0x4000;
            let mut status = AlignedBytes::<0x40>::new();
            let mut program_slots = AlignedBytes::<0x10>::new();
            let mut facility_sentinel = AlignedBytes::<0x20>::new();
            let mut pool = AlignedBytes::<0x20>::new();
            let mut project_sentinel = AlignedBytes::<0x20>::new();
            assert!(is_map_control_heap_pointer(status.addr()));
            assert!(is_map_control_heap_pointer(program_slots.addr()));
            assert!(is_map_control_heap_pointer(facility_sentinel.addr()));
            assert!(is_map_control_heap_pointer(pool.addr()));
            assert!(is_map_control_heap_pointer(project_sentinel.addr()));

            let mut root_reasons = ProjectRootReasonCounters::default();
            status.write_u64(PROJECT_PROGRAM_STATUS_OFF_PROGRAMS, 1);
            match facility_pins_from_program_status(
                status.addr(),
                facility_vtable,
                &mut root_reasons,
            ) {
                ProjectRootRead::Absent => {}
                _ => panic!("facility root sentinel pointer should be neutral"),
            }
            facility_sentinel.write_u64(0, sentinel_vtable as u64);
            program_slots.write_u64(0, facility_sentinel.addr() as u64);
            status.write_u64(
                PROJECT_PROGRAM_STATUS_OFF_PROGRAMS,
                program_slots.addr() as u64,
            );
            match facility_pins_from_program_status(
                status.addr(),
                facility_vtable,
                &mut root_reasons,
            ) {
                ProjectRootRead::Absent => {}
                _ => panic!("facility sentinel before first pin should be neutral"),
            }

            status.write_u64(PROJECT_PROGRAM_STATUS_OFF_POOL, 1);
            match project_pins_from_program_status(
                status.addr(),
                pool_vtable,
                project_vtable,
                &mut root_reasons,
            ) {
                ProjectRootRead::Absent => {}
                _ => panic!("project pool root sentinel pointer should be neutral"),
            }
            pool.write_u64(0, sentinel_vtable as u64);
            status.write_u64(PROJECT_PROGRAM_STATUS_OFF_POOL, pool.addr() as u64);
            match project_pins_from_program_status(
                status.addr(),
                pool_vtable,
                project_vtable,
                &mut root_reasons,
            ) {
                ProjectRootRead::Absent => {}
                _ => panic!("project pool root sentinel vtable should be neutral"),
            }
            project_sentinel.write_u64(0, sentinel_vtable as u64);
            pool.write_u64(0, pool_vtable as u64);
            pool.write_u64(
                PROJECT_POOL_OFF_FIRST_PROJECT,
                project_sentinel.addr() as u64,
            );
            status.write_u64(PROJECT_PROGRAM_STATUS_OFF_POOL, pool.addr() as u64);
            match project_pins_from_program_status(
                status.addr(),
                pool_vtable,
                project_vtable,
                &mut root_reasons,
            ) {
                ProjectRootRead::Absent => {}
                _ => panic!("project pool sentinel before first pin should be neutral"),
            }
            assert_eq!(root_reasons.invalid_facility_root_read_fail, 0);
            assert_eq!(
                root_reasons.invalid_facility_candidate_sentinel_after_pin,
                0
            );
            assert_eq!(root_reasons.invalid_project_pool_root_read_fail, 0);
            assert_eq!(root_reasons.invalid_project_candidate_sentinel_after_pin, 0);
        }

        #[test]
        fn compact_projects_populated_roots_accept_later_sentinel_terminator() {
            const PROJECT_TEST_BYTES: usize = PROJECT_COUNTRY_STRIDE * 2 + 0x80;
            let facility_vtable = HEAP_LO + 0x1000;
            let pool_vtable = HEAP_LO + 0x2000;
            let project_vtable = HEAP_LO + 0x3000;
            let sentinel_vtable = HEAP_LO + 0x4000;
            let mut status = AlignedBytes::<0x40>::new();
            let mut program_slots = AlignedBytes::<0x18>::new();
            let mut facility = AlignedBytes::<0x200>::new();
            let mut facility_sentinel = AlignedBytes::<0x20>::new();
            let mut pool = AlignedBytes::<0x20>::new();
            let mut project_array = AlignedBytes::<PROJECT_TEST_BYTES>::new();
            assert!(is_map_control_heap_pointer(status.addr()));
            assert!(is_map_control_heap_pointer(program_slots.addr()));
            assert!(is_map_control_heap_pointer(facility.addr()));
            assert!(is_map_control_heap_pointer(facility_sentinel.addr()));
            assert!(is_map_control_heap_pointer(pool.addr()));
            assert!(is_map_control_heap_pointer(project_array.addr()));

            let mut root_reasons = ProjectRootReasonCounters::default();
            facility.write_u64(0, facility_vtable as u64);
            facility.write_u32(PROJECT_FACILITY_OFF_TYPE, PROJECT_FACILITY_TYPE);
            facility.write_u32(PROJECT_FACILITY_OFF_ID, 118);
            facility.write_u32(PROJECT_FACILITY_OFF_PROVINCE, 341);
            facility_sentinel.write_u64(0, sentinel_vtable as u64);
            program_slots.write_u64(0, facility.addr() as u64);
            program_slots.write_u64(8, facility_sentinel.addr() as u64);
            status.write_u64(
                PROJECT_PROGRAM_STATUS_OFF_PROGRAMS,
                program_slots.addr() as u64,
            );
            match facility_pins_from_program_status(
                status.addr(),
                facility_vtable,
                &mut root_reasons,
            ) {
                ProjectRootRead::Valid(pins) => {
                    assert_eq!(pins.len(), 1);
                    assert_eq!(pins[0].facility_id, 118);
                }
                _ => panic!("facility sentinel after a valid pin should terminate normally"),
            }

            project_array.write_u64(0, project_vtable as u64);
            project_array.write_u32(PROJECT_PROJECT_OFF_TYPE, PROJECT_PROJECT_TYPE);
            project_array.write_u32(PROJECT_PROJECT_OFF_ID, 77);
            project_array.write_u32(PROJECT_PROJECT_OFF_DEF_HANDLE, 9001);
            project_array.write_u64(PROJECT_COUNTRY_STRIDE, sentinel_vtable as u64);
            pool.write_u64(0, pool_vtable as u64);
            pool.write_u64(PROJECT_POOL_OFF_FIRST_PROJECT, project_array.addr() as u64);
            status.write_u64(PROJECT_PROGRAM_STATUS_OFF_POOL, pool.addr() as u64);
            match project_pins_from_program_status(
                status.addr(),
                pool_vtable,
                project_vtable,
                &mut root_reasons,
            ) {
                ProjectRootRead::Valid(pins) => {
                    assert_eq!(pins.len(), 1);
                    assert_eq!(pins[0].project_id, 77);
                }
                _ => panic!("project sentinel after a valid pin should terminate normally"),
            }
            assert_eq!(
                root_reasons.invalid_facility_candidate_sentinel_after_pin,
                0
            );
            assert_eq!(root_reasons.invalid_project_candidate_sentinel_after_pin, 0);
        }

        #[test]
        fn compact_projects_matched_vtable_bad_fields_after_pin_stay_partial() {
            const PROJECT_TEST_BYTES: usize = PROJECT_COUNTRY_STRIDE * 2 + 0x80;
            let facility_vtable = HEAP_LO + 0x1000;
            let pool_vtable = HEAP_LO + 0x2000;
            let project_vtable = HEAP_LO + 0x3000;
            let mut status = AlignedBytes::<0x40>::new();
            let mut program_slots = AlignedBytes::<0x18>::new();
            let mut facility = AlignedBytes::<0x200>::new();
            let mut bad_facility = AlignedBytes::<0x200>::new();
            let mut pool = AlignedBytes::<0x20>::new();
            let mut project_array = AlignedBytes::<PROJECT_TEST_BYTES>::new();
            let mut root_reasons = ProjectRootReasonCounters::default();
            assert!(is_map_control_heap_pointer(status.addr()));
            assert!(is_map_control_heap_pointer(program_slots.addr()));
            assert!(is_map_control_heap_pointer(facility.addr()));
            assert!(is_map_control_heap_pointer(bad_facility.addr()));
            assert!(is_map_control_heap_pointer(pool.addr()));
            assert!(is_map_control_heap_pointer(project_array.addr()));

            facility.write_u64(0, facility_vtable as u64);
            facility.write_u32(PROJECT_FACILITY_OFF_TYPE, PROJECT_FACILITY_TYPE);
            facility.write_u32(PROJECT_FACILITY_OFF_ID, 118);
            facility.write_u32(PROJECT_FACILITY_OFF_PROVINCE, 341);
            bad_facility.write_u64(0, facility_vtable as u64);
            program_slots.write_u64(0, facility.addr() as u64);
            program_slots.write_u64(8, bad_facility.addr() as u64);
            status.write_u64(
                PROJECT_PROGRAM_STATUS_OFF_PROGRAMS,
                program_slots.addr() as u64,
            );
            match facility_pins_from_program_status(
                status.addr(),
                facility_vtable,
                &mut root_reasons,
            ) {
                ProjectRootRead::Partial(pins) => {
                    assert_eq!(pins.len(), 1);
                    assert_eq!(pins[0].facility_id, 118);
                }
                _ => panic!("matched facility vtable with bad fields after pin should be partial"),
            }

            project_array.write_u64(0, project_vtable as u64);
            project_array.write_u32(PROJECT_PROJECT_OFF_TYPE, PROJECT_PROJECT_TYPE);
            project_array.write_u32(PROJECT_PROJECT_OFF_ID, 77);
            project_array.write_u32(PROJECT_PROJECT_OFF_DEF_HANDLE, 9001);
            project_array.write_u64(PROJECT_COUNTRY_STRIDE, project_vtable as u64);
            pool.write_u64(0, pool_vtable as u64);
            pool.write_u64(PROJECT_POOL_OFF_FIRST_PROJECT, project_array.addr() as u64);
            status.write_u64(PROJECT_PROGRAM_STATUS_OFF_POOL, pool.addr() as u64);
            match project_pins_from_program_status(
                status.addr(),
                pool_vtable,
                project_vtable,
                &mut root_reasons,
            ) {
                ProjectRootRead::Partial(pins) => {
                    assert_eq!(pins.len(), 1);
                    assert_eq!(pins[0].project_id, 77);
                }
                _ => panic!("matched project vtable with bad fields after pin should be partial"),
            }
            assert_eq!(root_reasons.invalid_facility_candidate_fields_invalid, 1);
            assert_eq!(root_reasons.invalid_project_candidate_fields_invalid, 1);
        }

        #[test]
        fn compact_project_row_snapshot_reads_active_project_fields() {
            let project_vtable = HEAP_LO + 0x3000;
            let mut project = AlignedBytes::<PROJECT_ROW_PROJECT_SNAPSHOT_LEN>::new();
            assert!(is_map_control_heap_pointer(project.addr()));
            project.write_u64(0, project_vtable as u64);
            project.write_u32(PROJECT_PROJECT_OFF_TYPE, PROJECT_PROJECT_TYPE);
            project.write_u32(PROJECT_PROJECT_OFF_ID, 77);
            project.write_u32(PROJECT_PROJECT_OFF_DEF_HANDLE, 9001);
            project.write_u32(PROJECT_PROJECT_OFF_OWNER_TAG, PROJECT_FACILITY_TYPE);
            project.write_u32(PROJECT_PROJECT_OFF_OWNER_FACILITY, 118);
            project.write_u32(PROJECT_PROJECT_OFF_ITERATIONS, 3);

            let pin = ProjectPin {
                addr: project.addr(),
                project_id: 77,
                static_def_handle: 9001,
            };
            let row = read_project_row(pin, project_vtable).expect("active project row");
            assert_eq!(row.id, 77);
            assert_eq!(row.static_def_handle, 9001);
            assert_eq!(row.iterations, 3);
            assert_eq!(row.worked_at_facility, Some(118));

            project.write_u32(PROJECT_PROJECT_OFF_ITERATIONS, MAX_PROJECT_ITERATIONS + 1);
            assert!(
                read_project_row(pin, project_vtable).is_none(),
                "over-range iteration count must still reject the row"
            );
        }

        fn write_project_pool_record<const N: usize>(
            project_array: &mut AlignedBytes<N>,
            index: usize,
            project_vtable: usize,
            project_id: u32,
            static_def_handle: u32,
            started: bool,
            completed: bool,
        ) {
            let off = index * PROJECT_COUNTRY_STRIDE;
            project_array.write_u64(off, project_vtable as u64);
            project_array.write_u32(off + PROJECT_PROJECT_OFF_TYPE, PROJECT_PROJECT_TYPE);
            project_array.write_u32(off + PROJECT_PROJECT_OFF_ID, project_id);
            project_array.write_u32(off + PROJECT_PROJECT_OFF_DEF_HANDLE, static_def_handle);
            project_array.write_u8(off + PROJECT_PROJECT_OFF_START, u8::from(started));
            project_array.write_u8(off + PROJECT_PROJECT_OFF_COMPLETED, u8::from(completed));
        }

        fn project_pin_tuples(read: &ProjectRootRead<Vec<ProjectPin>>) -> Vec<(usize, u32, u32)> {
            match read {
                ProjectRootRead::Valid(pins) | ProjectRootRead::Partial(pins) => pins
                    .iter()
                    .map(|pin| (pin.addr, pin.project_id, pin.static_def_handle))
                    .collect(),
                ProjectRootRead::Absent | ProjectRootRead::Invalid => Vec::new(),
            }
        }

        fn project_root_kind<T>(read: &ProjectRootRead<T>) -> &'static str {
            match read {
                ProjectRootRead::Absent => "absent",
                ProjectRootRead::Valid(_) => "valid",
                ProjectRootRead::Partial(_) => "partial",
                ProjectRootRead::Invalid => "invalid",
            }
        }

        #[test]
        fn project_pool_bulk_pins_match_scalar_path() {
            page_cache_new_frame();
            let project_vtable = HEAP_LO + 0x3000;
            let pool_vtable = HEAP_LO + 0x2000;
            let mut pool = AlignedBytes::<0x20>::new();
            let mut project_array = AlignedBytes::<PROJECT_POOL_ARRAY_BULK_LEN>::new();
            assert!(is_map_control_heap_pointer(pool.addr()));
            assert!(is_map_control_heap_pointer(project_array.addr()));

            pool.write_u64(0, pool_vtable as u64);
            pool.write_u64(PROJECT_POOL_OFF_FIRST_PROJECT, project_array.addr() as u64);
            pool.write_u64(PROJECT_POOL_OFF_PACKED_SIZE, (2u64 << 32) | 2);
            write_project_pool_record(&mut project_array, 0, project_vtable, 77, 9001, true, false);
            write_project_pool_record(&mut project_array, 1, project_vtable, 78, 9002, false, true);
            project_array.write_u64(2 * PROJECT_COUNTRY_STRIDE, 0);

            let mut bulk_reasons = ProjectRootReasonCounters::default();
            let bulk = project_pins_from_program_status_bulk(
                pool.addr(),
                project_array.addr(),
                project_vtable,
                &mut bulk_reasons,
            )
            .expect("contiguous pool bulk read accepted");
            let mut scalar_reasons = ProjectRootReasonCounters::default();
            let scalar = project_pins_from_project_array_scalar(
                project_array.addr(),
                project_vtable,
                &mut scalar_reasons,
            );

            assert_eq!(project_root_kind(&bulk), project_root_kind(&scalar));
            assert_eq!(project_pin_tuples(&bulk), project_pin_tuples(&scalar));
            assert_eq!(bulk_reasons.invalid_project_candidate_fields_invalid, 0);
            assert_eq!(scalar_reasons.invalid_project_candidate_fields_invalid, 0);
        }

        fn lifecycle_rows(mut read: CountryLifecycle, tag_db_id: u32) -> Vec<ProjectLifecycleRow> {
            match &mut read {
                CountryLifecycle::Rows { lifecycle, .. } => {
                    for row in lifecycle.iter_mut() {
                        row.tag_db_id = tag_db_id;
                    }
                    lifecycle.clone()
                }
                CountryLifecycle::None => Vec::new(),
                CountryLifecycle::Aborted => panic!("expected lifecycle rows"),
            }
        }

