        #[test]
        fn project_lifecycle_bulk_payload_matches_scalar_path() {
            page_cache_new_frame();
            let project_vtable = HEAP_LO + 0x3000;
            let state_machine_vtable = HEAP_LO + 0x4000;
            let prototype_vtable = HEAP_LO + 0x5000;
            let simple_vtable = HEAP_LO + 0x6000;
            let mut project_array = AlignedBytes::<PROJECT_POOL_ARRAY_BULK_LEN>::new();
            let mut state_a = AlignedBytes::<PROJECT_STATE_MACHINE_SNAPSHOT_LEN>::new();
            let mut state_b = AlignedBytes::<PROJECT_STATE_MACHINE_SNAPSHOT_LEN>::new();
            assert!(is_map_control_heap_pointer(project_array.addr()));
            write_project_pool_record(&mut project_array, 0, project_vtable, 77, 9001, true, false);
            write_project_pool_record(&mut project_array, 1, project_vtable, 78, 9002, true, true);
            write_project_state_machine(
                &mut state_a,
                state_machine_vtable,
                prototype_vtable,
                simple_vtable,
            );
            write_project_state_machine(
                &mut state_b,
                state_machine_vtable,
                prototype_vtable,
                simple_vtable,
            );
            project_array.write_u64(PROJECT_PROJECT_OFF_STATE_MACHINE_PTR, state_a.addr() as u64);
            project_array.write_u64(
                PROJECT_COUNTRY_STRIDE + PROJECT_PROJECT_OFF_STATE_MACHINE_PTR,
                state_b.addr() as u64,
            );

            let bulk_rows = lifecycle_rows(
                read_country_project_lifecycle_bulk(
                    project_array.addr(),
                    2,
                    project_vtable,
                    state_machine_vtable,
                    prototype_vtable,
                    simple_vtable,
                    None,
                )
                .expect("contiguous lifecycle bulk read accepted"),
                47,
            );
            let scalar_rows = lifecycle_rows(
                read_country_project_lifecycle_scalar(
                    project_array.addr(),
                    2,
                    project_vtable,
                    state_machine_vtable,
                    prototype_vtable,
                    simple_vtable,
                    None,
                ),
                47,
            );
            assert_eq!(bulk_rows, scalar_rows);

            let bulk_payload =
                compact_projects_data_payload(&compact_projects_read_with_lifecycle(bulk_rows), 96);
            let scalar_payload = compact_projects_data_payload(
                &compact_projects_read_with_lifecycle(scalar_rows),
                96,
            );
            assert_eq!(
                bulk_payload, scalar_payload,
                "domain-41 payload bytes must stay identical"
            );
        }

        fn write_project_state_machine<const N: usize>(
            state: &mut AlignedBytes<N>,
            state_machine_vtable: usize,
            prototype_vtable: usize,
            simple_vtable: usize,
        ) {
            state.write_u64(0, state_machine_vtable as u64);
            state.write_u64(
                PROJECT_STATE_MACHINE_OFF_CURRENT_STATE_PTR,
                (state.addr() + PROJECT_STATE_MACHINE_OFF_PROTOTYPE_STATE) as u64,
            );
            state.write_u8(PROJECT_STATE_MACHINE_OFF_NOT_COMPLETED_FLAG, 1);
            state.write_u64(PROJECT_STATE_MACHINE_OFF_PROTOTYPE_STATE, prototype_vtable as u64);
            for offset in [
                PROJECT_STATE_MACHINE_OFF_SIMPLE_1,
                PROJECT_STATE_MACHINE_OFF_SIMPLE_2,
                PROJECT_STATE_MACHINE_OFF_SIMPLE_3,
            ] {
                state.write_u64(offset, simple_vtable as u64);
            }
            for (offset, value) in [
                (PROJECT_STATE_MACHINE_OFF_PROTOTYPE_STATE, 0),
                (PROJECT_STATE_MACHINE_OFF_SIMPLE_1, 1),
                (PROJECT_STATE_MACHINE_OFF_SIMPLE_2, 2),
                (PROJECT_STATE_MACHINE_OFF_SIMPLE_3, 3),
            ] {
                state.write_u32(offset + PROJECT_STATE_OFF_CURRENT_STATE_ENUM, value);
            }
            state.write_u32(
                PROJECT_STATE_MACHINE_OFF_PROTOTYPE_STATE
                    + PROJECT_PROTOTYPE_STATE_OFF_ITERATIONS,
                7,
            );
            state.write_u32(
                PROJECT_STATE_MACHINE_OFF_PROTOTYPE_STATE
                    + PROJECT_PROTOTYPE_STATE_OFF_PHASE_PROGRESS_RAW,
                3_000_000,
            );
            state.write_u32(
                PROJECT_STATE_MACHINE_OFF_PROTOTYPE_STATE
                    + PROJECT_PROTOTYPE_STATE_OFF_PHASE_TARGET,
                60,
            );
        }

        #[test]
        fn project_pool_refused_bulk_window_falls_back_to_scalar_walk() {
            const PAGE: usize = 0x1000;
            const T_PAGE_READONLY: Dword = 0x02;
            page_cache_new_frame();
            let project_vtable = HEAP_LO + 0x3000;
            let pool_vtable = HEAP_LO + 0x2000;
            let mut status = AlignedBytes::<0x80>::new();
            let mut pool = AlignedBytes::<0x20>::new();
            assert!(is_map_control_heap_pointer(status.addr()));
            assert!(is_map_control_heap_pointer(pool.addr()));
            status.write_u64(PROJECT_PROGRAM_STATUS_OFF_POOL, pool.addr() as u64);
            pool.write_u64(0, pool_vtable as u64);
            pool.write_u64(PROJECT_POOL_OFF_PACKED_SIZE, (1u64 << 32) | 1);

            unsafe {
                let mut base = ptr::null_mut();
                for index in 0..256usize {
                    let hint = (HEAP_LO + 0x1000_0000 + index * 0x1_0000) as *mut c_void;
                    base = VirtualAlloc(hint, 2 * PAGE, T_MEM_RESERVE, T_PAGE_READWRITE);
                    if !base.is_null() {
                        break;
                    }
                }
                assert!(!base.is_null());
                let first = VirtualAlloc(base, PAGE, MEM_COMMIT, T_PAGE_READWRITE);
                assert_eq!(first, base);
                let second = VirtualAlloc(
                    (base as usize + PAGE) as *mut c_void,
                    PAGE,
                    MEM_COMMIT,
                    T_PAGE_READWRITE,
                );
                assert_eq!(second as usize, base as usize + PAGE);

                let project_addr = base as usize + PAGE - PROJECT_COUNTRY_STRIDE;
                assert!(is_map_control_heap_pointer(project_addr));
                let project = project_addr as *mut u8;
                core::ptr::copy_nonoverlapping(
                    (project_vtable as u64).to_le_bytes().as_ptr(),
                    project,
                    8,
                );
                core::ptr::copy_nonoverlapping(
                    PROJECT_PROJECT_TYPE.to_le_bytes().as_ptr(),
                    project.add(PROJECT_PROJECT_OFF_TYPE),
                    4,
                );
                core::ptr::copy_nonoverlapping(
                    77u32.to_le_bytes().as_ptr(),
                    project.add(PROJECT_PROJECT_OFF_ID),
                    4,
                );
                core::ptr::copy_nonoverlapping(
                    9001u32.to_le_bytes().as_ptr(),
                    project.add(PROJECT_PROJECT_OFF_DEF_HANDLE),
                    4,
                );
                let sentinel = (project_addr + PROJECT_COUNTRY_STRIDE) as *mut u8;
                core::ptr::copy_nonoverlapping(0u64.to_le_bytes().as_ptr(), sentinel, 8);

                let mut old: Dword = 0;
                let ok = VirtualProtect(
                    (base as usize + PAGE) as *mut c_void,
                    PAGE,
                    T_PAGE_READONLY,
                    &mut old as *mut Dword,
                );
                assert_ne!(ok, 0, "VirtualProtect readonly failed");
                page_cache_new_frame();
                assert_eq!(read_u64(project_addr), Some(project_vtable as u64));
                assert_eq!(
                    read_u32(project_addr + PROJECT_PROJECT_OFF_TYPE),
                    Some(PROJECT_PROJECT_TYPE)
                );
                assert_eq!(read_u64(project_addr + PROJECT_COUNTRY_STRIDE), Some(0));
                assert_eq!(read_u64(pool.addr()), Some(pool_vtable as u64));

                assert!(
                    project_pins_from_program_status_bulk(
                        pool.addr(),
                        project_addr,
                        project_vtable,
                        &mut ProjectRootReasonCounters::default(),
                    )
                    .is_none(),
                    "cross-region bulk window must be refused"
                );
                pool.write_u64(PROJECT_POOL_OFF_FIRST_PROJECT, project_addr as u64);
                assert_eq!(
                    read_u64(pool.addr() + PROJECT_POOL_OFF_FIRST_PROJECT),
                    Some(project_addr as u64)
                );
                let mut scalar_reasons = ProjectRootReasonCounters::default();
                let scalar = project_pins_from_project_array_scalar(
                    project_addr,
                    project_vtable,
                    &mut scalar_reasons,
                );
                assert_eq!(project_root_kind(&scalar), "valid");
                assert!(
                    project_pins_from_program_status_bulk(
                        pool.addr(),
                        project_addr,
                        project_vtable,
                        &mut ProjectRootReasonCounters::default(),
                    )
                    .is_none(),
                    "bulk window must remain refused after scalar cache warmup"
                );
                let mut root_reasons = ProjectRootReasonCounters::default();
                let read = project_pins_from_program_status(
                    status.addr(),
                    pool_vtable,
                    project_vtable,
                    &mut root_reasons,
                );
                assert_eq!(project_root_kind(&read), "valid");
                assert_eq!(project_pin_tuples(&read), vec![(project_addr, 77, 9001)]);
                assert_eq!(root_reasons.invalid_project_candidate_vtable_read_fail, 0);
                assert_eq!(root_reasons.invalid_project_candidate_fields_invalid, 0);

                let _ = VirtualFree(base, 0, T_MEM_RELEASE);
            }
        }

        #[test]
        fn compact_projects_candidate_pins_do_not_inflate_observed_project_rows() {
            let candidate_projects = (0..128)
                .map(|index| ProjectPin {
                    addr: index * 8,
                    project_id: index as u32 + 1,
                    static_def_handle: index as u32 + 10_000,
                })
                .collect::<Vec<_>>();
            let state = CollectorState {
                base: 0,
                daily_addr: 0,
                long_string_addr: 0,
                daily_match: true,
                long_string_match: true,
                date_ptr: 0,
                country_database_ptr: 0,
                country_identity: CountryIdentityCache::not_attempted("test"),
                special_projects: SpecialProjectsCache {
                    status: "country_project_pool_verified",
                    scan_ms: 0,
                    bridge_rows_supplied: 0,
                    facilities: Vec::new(),
                    projects: candidate_projects,
                    scientists: Vec::new(),
                    too_many: false,
                    invalid_program_status_countries: 0,
                    invalid_facility_countries: 0,
                    invalid_project_pool_countries: 0,
                    neutral_program_status_countries: 0,
                    neutral_facility_countries: 0,
                    neutral_project_pool_countries: 0,
                    root_reasons: ProjectRootReasonCounters::default(),
                },
                weather: CompactWeatherRoot::default(),
            };

            let mut tracker = CompactProjectsTracker::default();
            let read = read_compact_projects(
                &state,
                COMPACT_STATUS_EXTRACTION_PERF_GATE,
                D41EmitMode::Delta,
                &mut tracker,
            );
            let payload = compact_projects_data_payload(&read, 0);

            assert_eq!(state.special_projects.projects.len(), 128);
            assert_eq!(read.projects.len(), 0);
            assert_eq!(read.observed_project_rows, 0);
            assert_eq!(read.observed_project_state_rows, 0);
            assert_eq!(read.changed_rows, 0);
            assert_eq!(read.status_flags & COMPACT_STATUS_SOURCE_UNAVAILABLE, 0);
            assert_eq!(read.status_flags & COMPACT_STATUS_PARTIAL_DATA, 0);
            assert_eq!(u32::from_le_bytes(payload[24..28].try_into().unwrap()), 0);
            assert_eq!(u32::from_le_bytes(payload[36..40].try_into().unwrap()), 0);
        }

