        #[test]
        fn political_party_leader_vector_accepts_packed_singleton_only() {
            let data = HEAP_LO + 0x1000;
            assert!(political_party_leader_vector_is_singleton(
                data,
                0x0000_0001_0000_0001,
            ));
            assert!(political_party_leader_vector_is_singleton(data, data + 8));
            assert!(!political_party_leader_vector_is_singleton(
                data,
                0x0000_0002_0000_0002,
            ));
            assert!(!political_party_leader_vector_is_singleton(
                data,
                0x0000_0005_0000_0006,
            ));
            assert!(!political_party_leader_vector_is_singleton(0, data + 8));
        }

        fn resource_row(amount_raw: i32, resource_id: u32) -> [u8; STATE_RESOURCE_STRIDE] {
            let mut row = [0u8; STATE_RESOURCE_STRIDE];
            row[0..4].copy_from_slice(&amount_raw.to_le_bytes());
            row[8..12].copy_from_slice(&resource_id.to_le_bytes());
            row
        }

        fn resource_rows(rows: &[(i32, u32)]) -> Vec<u8> {
            rows.iter()
                .flat_map(|(amount_raw, resource_id)| resource_row(*amount_raw, *resource_id))
                .collect()
        }

        #[test]
        fn state_resource_rows_accepts_trailing_no_id_sentinel_past_cap() {
            let rows = resource_rows(&[
                (2_400_000, 0x3E03),
                (1_600_000, 0x4E1F),
                (200_000, 0x3E07),
                (100_000, 0x3E06),
                (100_000, 0x4E25),
                (29_816, STATE_RESOURCE_NO_ID),
            ]);

            let json = state_resource_rows_json(6, 5, &rows).expect("resource rows should parse");

            assert!(json.contains("\"steel\":24"));
            assert!(json.contains("\"aluminium\":16"));
            assert!(json.contains("\"chromium\":2"));
            assert!(json.contains("\"tungsten\":1"));
            assert!(json.contains("\"coal\":1"));
            assert!(!json.contains("tid_0xFFFFFFFF"));
        }

        #[test]
        fn state_resource_rows_rejects_real_resource_past_logical_cap() {
            let rows = resource_rows(&[
                (2_400_000, 0x3E03),
                (1_600_000, 0x4E1F),
                (200_000, 0x3E07),
                (100_000, 0x3E06),
                (100_000, 0x4E25),
                (100_000, 0x4E37),
            ]);

            assert!(state_resource_rows_json(6, 5, &rows).is_none());
        }

        #[test]
        fn state_resource_logical_rows_uses_cap_when_lower_than_size() {
            assert_eq!(state_resource_logical_rows(6, 5), Some(5));
            assert_eq!(state_resource_logical_rows(6, 0), Some(6));
            assert_eq!(state_resource_logical_rows(0, 0), Some(0));
            assert_eq!(
                state_resource_logical_rows(STATE_RESOURCE_MAX_ROWS + 1, STATE_RESOURCE_MAX_ROWS),
                None
            );
        }

        #[test]
        fn country_object_row_json_includes_scheduled_politics_residuals() {
            let row = CountryObjectRow {
                tag: "POR".to_string(),
                tag_db_id: 47,
                name: "Portugal".to_string(),
                object_ptr: 0x1234,
                record_ptr: None,
                original_capital: None,
                original_tag: None,
                templates_locked: None,
                reserved_dynamic_country: None,
                stability: None,
                war_support: None,
                political_power: None,
                command_power: None,
                num_ships: None,
                manpower_pool: None,
                convoys: None,
                misc: None,
                fuel: None,
                production: None,
                focus: None,
                research: None,
                politics: None,
                politics_residuals: Some(CountryPoliticsResidualsRow {
                    last_election: Some("1933.7.1.1".to_string()),
                    elections_allowed: Some(false),
                    appointed_advisors: Some(vec![
                        "ENG_maxwell_aitken".to_string(),
                        "POR_salazar".to_string(),
                    ]),
                    appointed_advisor_details: Some(vec![AppointedAdvisorRow {
                        idea_token: "POR_salazar".to_string(),
                        slot: Some("political_advisor".to_string()),
                        ledger: Some("political".to_string()),
                        character: Some("POR_antonio_de_oliveira_salazar".to_string()),
                    }]),
                    appointed_advisor_slots: Some({
                        let mut slots = BTreeMap::new();
                        slots.insert(
                            "political_advisor".to_string(),
                            vec!["POR_salazar".to_string()],
                        );
                        slots
                    }),
                    appointed_advisor_ledgers: Some({
                        let mut ledgers = BTreeMap::new();
                        ledgers.insert("political".to_string(), vec!["POR_salazar".to_string()]);
                        ledgers
                    }),
                }),
                decisions: None,
                diplomacy: None,
            };

            let scheduled = row_json(&row, false, false, false, false, false, false, true, false);
            let worker = row_json(&row, false, false, false, false, false, false, false, false);

            assert!(scheduled.contains("\"politics\""));
            assert!(scheduled.contains("\"last_election\":\"1933.7.1.1\""));
            assert!(scheduled.contains("\"elections_allowed\":false"));
            assert!(scheduled
                .contains("\"appointed_advisors\":[\"ENG_maxwell_aitken\",\"POR_salazar\"]"));
            assert!(scheduled.contains("\"appointed_advisor_details\""));
            assert!(scheduled.contains("\"idea_token\":\"POR_salazar\""));
            assert!(scheduled.contains("\"slot\":\"political_advisor\""));
            assert!(scheduled.contains("\"ledger\":\"political\""));
            assert!(scheduled.contains("\"character\":\"POR_antonio_de_oliveira_salazar\""));
            assert!(scheduled
                .contains("\"appointed_advisor_slots\":{\"political_advisor\":[\"POR_salazar\"]}"));
            assert!(scheduled
                .contains("\"appointed_advisor_ledgers\":{\"political\":[\"POR_salazar\"]}"));
            assert!(!worker.contains("\"politics\""));
            let cache = CountryIdentityCache::not_attempted("test");
            let domains = cache.domains_json_from_rows(
                &[row],
                false, // state rows
                false, // province rows
                false, // special-project rows
                false, // compact country frame
                false, // fuel
                false, // production
                false, // focus
                false, // research
                false, // politics
                true,  // politics residuals
                false, // decisions
            );
            assert!(domains.contains("\"politics_residuals\""));
            assert!(!domains.contains("\"politics_live\""));
        }

