        #[test]
        fn country_object_row_json_includes_scheduled_decisions() {
            assert_eq!(
                (0..=4).map(decision_state_name).collect::<Vec<_>>(),
                vec![
                    "active",
                    "available",
                    "completed",
                    "removed",
                    "re_enable_cooldown"
                ]
            );
            assert_eq!(
                (0..=4)
                    .map(targeted_decision_state_name)
                    .collect::<Vec<_>>(),
                vec![
                    "available",
                    "active",
                    "re_enable_cooldown",
                    "completed",
                    "removed"
                ]
            );
            let mut status_present = BTreeMap::new();
            status_present.insert("active_timed_decision".to_string(), 1);
            status_present.insert("decision_to_re_enable".to_string(), 2);
            let row = CountryObjectRow {
                tag: "POR".to_string(),
                tag_db_id: 47,
                name: "Portugal".to_string(),
                object_ptr: 0x1234,
                record_ptr: None,
                original_capital: None,
                original_tag: None,
                templates_locked: None,
                reserved_dynamic_country: None,
                stability: None,
                war_support: None,
                political_power: None,
                command_power: None,
                num_ships: None,
                manpower_pool: None,
                convoys: None,
                misc: None,
                fuel: None,
                production: None,
                focus: None,
                research: None,
                politics: None,
                politics_residuals: None,
                decisions: Some(CountryDecisionsRow {
                    status_present: Some(status_present),
                    timed_live: Some(vec![TimedDecisionRow {
                        decision: "POR_countdown_mission".to_string(),
                        days: 43,
                        state: 0,
                        state_name: "active".to_string(),
                    }]),
                    targeted_live: TargetedTimedCountryTargetRead {
                        rows: vec![TargetedTimedDecisionRow {
                            decision: "POR_targeted_decision".to_string(),
                            target: TargetedDecisionTarget::Country(47),
                            lifecycle_state: 2,
                            lifecycle_state_name: "re_enable_cooldown".to_string(),
                            ignore: false,
                            days: 12,
                        }],
                        omitted_rows: 0,
                        structural_failure: false,
                        failure_reason_mask: 0,
                    },
                    targeted_timed_live: TargetedTimedCountryTargetRead::default(),
                    re_enable_cooldowns: Some(vec![DecisionCooldownRow {
                        decision: "POR_countdown_mission".to_string(),
                        days: 12,
                    }]),
                    remove_cooldowns: Some(vec![DecisionCooldownRow {
                        decision: "POR_countdown_mission".to_string(),
                        days: 5,
                    }]),
                }),
                diplomacy: None,
            };

            let scheduled = row_json(&row, false, false, false, false, false, false, false, true);
            let worker = row_json(&row, false, false, false, false, false, false, false, false);

            assert!(scheduled.contains("\"decisions\""));
            assert!(scheduled.contains("\"status_present\""));
            assert!(scheduled.contains("\"active_timed_decision\":1"));
            assert!(scheduled.contains("\"decision\":\"POR_countdown_mission\""));
            assert!(scheduled.contains("\"days\":43"));
            assert!(scheduled.contains("\"state_name\":\"active\""));
            assert!(scheduled.contains("\"targeted_live\""));
            assert!(scheduled.contains("\"target_kind\":\"country\""));
            assert!(scheduled.contains("\"target_id\":47"));
            assert!(scheduled.contains("\"lifecycle_state_name\":\"re_enable_cooldown\""));
            assert!(scheduled.contains("\"ignore\":false"));
            assert!(scheduled.contains(
                "\"re_enable_cooldowns\":[{\"decision\":\"POR_countdown_mission\",\"days\":12}]"
            ));
            assert!(scheduled.contains(
                "\"remove_cooldowns\":[{\"decision\":\"POR_countdown_mission\",\"days\":5}]"
            ));
            assert!(!worker.contains("\"decisions\""));
            let cache = CountryIdentityCache::not_attempted("test");
            let domains = cache.domains_json_from_rows(
                &[row],
                false, // state rows
                false, // province rows
                false, // special-project rows
                false, // compact country frame
                false, // fuel
                false, // production
                false, // focus
                false, // research
                false, // politics
                false, // politics residuals
                true,  // decisions
            );
            assert!(domains.contains("\"decisions_live\""));
        }

